* {
  box-sizing: border-box;
}

html, body {
  overscroll-behavior: none;
}
/* Portrait-only: block landscape on phones with a rotate prompt. Scoped to
   touch devices with a short viewport so desktops/large tablets are unaffected. */
#rotateLock { display: none; }
@media (orientation: landscape) and (max-height: 540px) and (pointer: coarse) {
  #rotateLock {
    display: flex;
    position: fixed;
    inset: 0;
    z-index: 2147483600;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin: 0;
    padding: 24px;
    text-align: center;
    background: #eff6ff;
    color: #172033;
  }
  #rotateLock .material-symbols-outlined {
    font-size: 3.2rem;
    color: #1d4ed8;
    animation: rotateHint 2.4s ease-in-out infinite;
  }
  #rotateLock strong { font-size: 1.15rem; font-weight: 900; }
  #rotateLock p { margin: 0; max-width: 360px; line-height: 1.45; color: #475569; }
  /* Keep the app from scrolling/interacting behind the prompt. */
  body { overflow: hidden !important; }
}
@keyframes rotateHint {
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(-90deg); }
}
html {
  touch-action: pan-x pan-y;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}
input, textarea, [contenteditable] {
  -webkit-user-select: text;
  user-select: text;
  -webkit-touch-callout: default;
}
button,
label,
input,
textarea,
select,
.main-btn,
.small-btn,
.icon-btn,
.chapter-grid label {
  touch-action: manipulation;
}

:root {
  --primary-color: #dbeafe;
  --primary-light: #eff6ff;
  --secondary-color: #1d4ed8;
  --accent-color: #f59e0b;
  --card-color: rgba(255, 255, 255, 0.88);
  --border-color: #93c5fd;
  --font-color: #172033;
  --muted-color: #475569;
  --btn-text-color: #ffffff;
  --card-solid-color: #ffffff;
  --memorization-page-color: var(--primary-light);
  /* shorthand aliases used by new UI components */
  --primary: var(--primary-color);
  --secondary: var(--secondary-color);
  --accent: var(--accent-color);
}
body {
  margin: 0;
  font-family: system-ui, sans-serif;
   background: linear-gradient(180deg, var(--primary-color), var(--primary-light));
  color: var(--font-color);
}

.app-launch-screen {
  position: fixed;
  inset: 0;
  z-index: 2147483000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
  background: radial-gradient(circle at 42% 34%, var(--primary-light), var(--primary-color) 78%);
  color: var(--font-color);
  transition: opacity 0.32s ease, visibility 0.32s ease;
}

.app-launch-screen.dismissed {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.app-launch-emblem {
  position: relative;
  z-index: 2;
  width: min(64vw, 300px);
  aspect-ratio: 1 / 1;
}

/* The progress ring sits behind the icon artwork so the open Bible overlaps
   the ring's lower edge, exactly like the app icon. */
.app-launch-emblem .app-launch-ring-svg,
.app-launch-emblem .app-launch-emblem-art {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.app-launch-emblem-art {
  object-fit: contain;
}

.app-launch-status {
  position: relative;
  z-index: 3;
  margin-top: 30px;
  width: min(72vw, 360px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
  color: color-mix(in srgb, var(--font-color) 82%, transparent);
  font-size: 0.82rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* Status bar background — solid bar behind iOS status bar so content never bleeds under the notch */
#statusBarBg {
  position: fixed; top: 0; left: 0; right: 0; z-index: 9999;
  height: env(safe-area-inset-top, 0px);
  background: var(--primary-color);
  pointer-events: none;
}

.app {
  max-width: 900px;
  margin: 0 auto;
  min-height: 100vh;
  padding: 24px;
  padding-bottom: 100px;
}

.header {
  text-align: center;
  margin-bottom: 20px;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(36, 52, 71, 0.15);
  cursor: pointer;
  border-radius: 12px;
  transition: background 0.15s;
}
.header:hover, .header:focus {
  background: rgba(36, 52, 71, 0.04);
  outline: none;
}

.header h1 {
  margin-bottom: 8px;
  color: var(--font-color);
}

.header p {
  color: #5f6c7b;
}

.header-info-hint {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-top: 6px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--font-color);
  opacity: 0.35;
  letter-spacing: 0.3px;
}
.header-info-hint .material-symbols-outlined {
  font-size: 13px !important;
}
.app-header.lesson-header-mode {
  border-bottom-color: color-mix(in srgb, var(--secondary-color) 22%, transparent);
}
.app-header.lesson-header-mode h1 {
  letter-spacing: 0.02em;
}
.app-header.lesson-header-mode p {
  max-width: 520px;
  margin: 0 auto;
  color: var(--muted-color);
  line-height: 1.45;
}
.app-header.lesson-header-mode .header-info-hint {
  color: var(--secondary-color);
  opacity: 0.68;
}
body.dark .header:hover, body.dark .header:focus {
  background: rgba(255,255,255,0.05);
}

.screen {
  display: none;
}

.screen.active {
   background: rgba(255, 252, 242, 0.6);
  display: block;

}

.desktop-shell-nav,
.desktop-home-shell {
  display: none;
}

.main-btn {
  width: 100%;
  padding: 14px 18px;
  margin: 8px 0;
  border: none;
  border-radius: 14px;
  background: var(--secondary-color);
  color: var(--btn-text-color);
  font-size: 1rem;
  cursor: pointer;
}

.main-btn:hover {
  opacity: 0.92;
}

.secondary {
 background: var(--secondary-color);
  opacity: 0.85;
}

.text-btn {
  background: transparent;
  color: var(--font-color);
  text-decoration: underline;
  width: auto;
  padding: 8px;
  border: none;
  cursor: pointer;
}

.chapter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(70px, 1fr));
  gap: 10px;
  margin: 18px 0;
}

.chapter-grid label {
  position: relative;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(0,0,0,0.08);
  border-radius: 12px;
  padding: 10px 0;
  text-align: center;
  cursor: pointer;
  font-weight: 600;
   font-size: 1.05rem;
  letter-spacing: 0.5px;
  color: var(--font-color);
  transition: background 0.15s ease, transform 0.12s ease;
}

.chapter-grid label:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.85);
}

.chapter-grid label input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.chapter-grid label.selected {
  background: var(--secondary-color);
  color: white !important;
  border-color: var(--secondary-color);
  box-shadow: 0 8px 18px rgba(36, 52, 71, 0.22);
}

.test-mode-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 14px 0 18px;
}

.test-mode-tab {
  min-height: 74px;
  border: 1px solid var(--border-color);
  border-radius: 14px;
  background: var(--card-color);
  color: var(--font-color);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-weight: 800;
  font-size: 0.78rem;
  text-align: center;
  cursor: pointer;
}

.test-mode-tab .material-symbols-outlined {
  font-size: 1.4rem;
}

.test-mode-tab.active {
  background: var(--secondary-color);
  border-color: var(--secondary-color);
  color: var(--btn-text-color);
  box-shadow: 0 10px 24px rgba(36, 52, 71, 0.18);
}

.test-mode-panel {
  display: none;
}

.test-mode-panel.active {
  display: block;
}

.paradigm-test-card {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  padding: 16px;
  border-radius: 16px;
  border: 1px solid var(--border-color);
  background: var(--card-color);
  margin: 10px 0 18px;
}

.paradigm-test-card > .material-symbols-outlined {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  color: var(--secondary-color);
}

.paradigm-test-card h3 {
  margin: 0 0 5px;
}

.paradigm-test-card p,
.test-question-meta,
.paradigm-lesson-card small {
  color: var(--muted-color);
}

.paradigm-lesson-grid {
  display: grid;
  gap: 10px;
  margin: 16px 0;
}

.paradigm-lesson-card {
  width: 100%;
  border: 1px solid var(--border-color);
  border-radius: 14px;
  background: var(--card-color);
  color: var(--font-color);
  padding: 13px 14px;
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 4px 10px;
  text-align: left;
  cursor: pointer;
}

.paradigm-lesson-card .material-symbols-outlined {
  grid-row: span 2;
  color: var(--secondary-color);
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
}

.paradigm-lesson-card.selected {
  border-color: var(--secondary-color);
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--secondary-color) 18%, transparent), transparent 68%),
    var(--card-color);
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--secondary-color) 28%, transparent),
    0 12px 28px rgba(0,0,0,0.12);
  transform: translateY(-1px);
}

.paradigm-lesson-card.selected .material-symbols-outlined {
  background: var(--secondary-color);
  color: var(--btn-text-color);
}

.paradigm-lesson-card.selected strong::after {
  content: "Selected";
  display: inline-flex;
  margin-left: 8px;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--secondary-color);
  color: var(--btn-text-color);
  font-size: 0.66rem;
  font-weight: 900;
  vertical-align: middle;
}

.test-question-meta {
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 10px;
}

.paradigm-options {
  display: grid;
  gap: 10px;
  margin: 18px 0;
}

.paradigm-option-btn {
  width: 100%;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid var(--border-color);
  background: rgba(255,255,255,0.55);
  color: var(--font-color);
  font-weight: 800;
  text-align: left;
}

.paradigm-option-btn.selected {
  border-color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 12%, white);
}

.paradigm-option-btn.correct {
  border-color: #16a34a;
  background: rgba(34, 197, 94, 0.14);
}

.paradigm-option-btn.incorrect {
  border-color: #dc2626;
  background: rgba(239, 68, 68, 0.12);
}

.label {
  display: block;
  margin-top: 16px;
  margin-bottom: 6px;
  font-weight: 600;
}

input[type="number"],
input[type="text"] {
  width: 100%;
  padding: 14px;
  border-radius: 12px;
  border: 1px solid #c8b894;
  font-size: 1rem;
}

.checkbox-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 18px 0;
}

.checkbox-row input {
  width: auto;
  accent-color: #243447;
}

.top-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.flashcard {
  perspective: 1000px;
  height: 330px;
  margin: 20px 0;
}

.card-inner {
  position: relative;
  width: 100%;
  height: 100%;
}

.card-face {
  position: absolute;
  inset: 0;
  transition: opacity 0.22s ease, transform 0.22s ease;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.card-front {
  opacity: 1;
  transform: translateY(0);
}

.card-back {
  opacity: 0;
  transform: translateY(8px);
}

.flashcard.flipped .card-front {
  opacity: 0;
  transform: translateY(-8px);
}

.flashcard.flipped .card-back {
  opacity: 1;
  transform: translateY(0);
}

.greek-word {
  font-size: 3rem;
  font-weight: 700;
  color: var(--font-color);
}

.meaning {
  font-size: 1.6rem;
  color: var(--font-color);
}

.tap-hint {
  margin-top: 18px;
  color: #7b6f55;
  font-size: 0.95rem;
}

.swipe-hint {
  text-align: center;
  color: rgba(36, 52, 71, 0.45);
  animation: bounce 1.2s infinite;
}

@keyframes bounce {
  0%, 100% { transform: translateX(0); }
  50% { transform: translateX(12px); }
}

.test-card,
.settings-card {
  background: rgba(255, 252, 242, 0.95);
  border: 1px solid #d6c49a;
  border-radius: 24px;
  box-shadow: 0 12px 30px rgba(0,0,0,0.12);
  padding: 28px;
  text-align: center;
}

.feedback {
  margin-top: 16px;
  font-weight: 700;
}

.correct {
  color: #15803d;
}

.incorrect {
  color: #b91c1c;
}

.score {
  font-size: 2rem;
  font-weight: 700;
  margin: 20px 0;
}

.review-word {
  background: rgba(255,255,255,0.7);
  border-radius: 12px;
  padding: 12px;
  margin: 8px 0;
}

.material-symbols-outlined {
  font-size: 28px;
  color: var(--font-color);
}

/* When Material Symbols font fails to load (no internet on first launch),
   hide the ligature text so icons degrade invisibly instead of showing raw names */
body.no-icon-font .material-symbols-outlined {
  font-size: 0 !important;
  line-height: 0 !important;
  min-width: 24px;
  min-height: 24px;
  display: inline-block;
  vertical-align: middle;
}

.icon-btn {
  width: 46px;
  height: 46px;
  min-width: 46px;
  padding: 0;
  margin: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid #d3c4a3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.icon-btn:hover {
  background: rgba(255, 255, 255, 0.9);
}



.settings-card p {
  color: #5f6c7b;
  line-height: 1.5;
}

.danger-btn {
  width: 100%;
  padding: 14px 18px;
  margin: 8px 0;
  border: none;
  border-radius: 14px;
  background: #9f1239;
  color: white;
  font-size: 1rem;
  cursor: pointer;
}

/* Top Navigation Bar */
.nav-bar {
  display: grid;
  grid-template-columns: 40px 1fr 40px;
  align-items: center;
  margin-top: 10px;
  margin-bottom: 20px;
}
.nav-title {
  text-align: center;
  font-weight: 600;
  font-size: 1.1rem;
  color: var(--font-color);
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.2;
}

.nav-subtitle {
  display: block;
  font-size: 0.6rem;
  font-weight: 500;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  opacity: 0.55;
  margin-top: 2px;
  line-height: 1;
}

/* Icon buttons (cleaner + flatter) */
.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid #d3c4a3;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.icon-btn:hover {
  background: rgba(255, 255, 255, 0.9);
}

/* Icon styling */
.material-symbols-outlined {
  font-size: 22px;
  color: var(--font-color);
}
.screen.active {
  display: block;
  background: rgba(255, 252, 242, 0.6);
  padding: 18px;
  border-radius: 18px;
  box-shadow: 0 8px 20px rgba(0,0,0,0.06);
  /* No generic fade here: screens drive their own open/slide transitions, and a
     blanket screenFade re-fired whenever a transition class was removed (the
     post-animation flicker). Explicit transitions handle entrances now. */
}
@keyframes screenFade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.flashcard {
  transition: transform 0.22s ease, opacity 0.22s ease;
}

.flashcard.slide-out {
  opacity: 0;
  transform: translateX(-20px);
}

