  background: linear-gradient(135deg, #111827, #1f2937);
  color: #f3f4f6;
}

body.dark .header {
  border-bottom-color: rgba(255, 255, 255, 0.12);
}

body.dark .header h1,
body.dark .header p,
body.dark h2,
body.dark h3,
body.dark .nav-title,
body.dark #learnProgress,
body.dark #testProgress {
