.collapse-btn {
  width: 100%;
  padding: 12px;
  border: none;
  border-radius: 12px;
  background: transparent;
  cursor: pointer;
  font-weight: 600;
}

.collapse-content {
  display: none;
  overflow: hidden;
}

.collapse-content.open {
  display: block;
  margin-top: 12px;
  animation: none;
  transition: none;
}

/* Toggle Switch */
.switch {
  position: relative;
  display: inline-block;
  width: 46px;
  height: 26px;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  inset: 0;
  background-color: #c8b894;
  border-radius: 999px;
  transition: 0.25s;
}

.slider:before {
  content: "";
  position: absolute;
  height: 20px;
  width: 20px;
  left: 3px;
  top: 3px;
  background: white;
  border-radius: 50%;
  transition: 0.25s;
}

.switch input:checked + .slider {
  background: var(--secondary-color);
}

.switch input:checked + .slider:before {
  transform: translateX(20px);
}
body.dark .slider {
  background-color: #4b5563;
}

body.dark .switch input:checked + .slider {
  background-color: #d6c49a;
}

body.dark .slider:before {
  background: #f9fafb;
}
.helper-text {
  margin-top: -4px;
  margin-bottom: 18px;
  color: #5f6c7b;
  font-size: 0.9rem;
}

body.dark .helper-text {
  color: #cbd5e1;
}

.chapter-actions {
  display: flex;
  gap: 10px;
  margin: 12px 0;
}

.small-btn {
  flex: 1;
  padding: 10px 12px;
  border: 1px solid #d3c4a3;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
  color: var(--font-color);
  font-weight: 600;
  cursor: pointer;
}

.small-btn:hover {
