}

@keyframes lockBreak {
  0% { transform: scale(1) rotate(0deg); opacity: 1; }
  35% { transform: scale(1.15) rotate(-8deg); }
  60% { transform: scale(0.95) rotate(10deg); }
  100% { transform: translateY(-24px) rotate(25deg) scale(0.2); opacity: 0; }
}

