/* Habits */
/* ─── Habits page ─────────────────────────────────────────────────── */
#habitsPage.screen.active {
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  background: var(--primary-color) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border: none !important;
  padding: 0 !important;
}

.habits-scroll {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  padding: 0 0 32px;
}

/* Hero */
.habits-hero {
  position: relative;
  overflow: hidden;
  padding: max(env(safe-area-inset-top, 0px), 18px) 18px 0;
  background: linear-gradient(160deg,
    color-mix(in srgb, var(--secondary-color) 10%, var(--primary-color)),
    var(--primary-color) 72%);
  min-height: 210px;
}

.habits-hero-text {
  padding-right: min(34vw, 150px);
  padding-bottom: 22px;
  position: relative;
  z-index: 2;
}

/* Full-width banner across the top of the hero; the title text overlaps it and
   a fog gradient fades the artwork into the hero so the words stay readable. */
.habits-hero-art {
  position: absolute;
  top: max(env(safe-area-inset-top, 0px), 18px);
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  line-height: 0;
  z-index: 0;
  overflow: hidden;
  border-radius: 0;
  background: none;
  box-shadow: none;
  transform: none;
  isolation: isolate; /* contain the color-tint blend to this artwork only */
}

/* Recolor the habit artwork to the selected theme: the tint keeps the image's
   shading (luminance) but takes the theme hue/saturation via "color" blend. */
.habits-hero-tint,
.hhw-art-tint {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: var(--secondary-color);
  mix-blend-mode: color;
}

.habits-hero-art::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg,
      var(--primary-color) 0%,
      color-mix(in srgb, var(--primary-color) 80%, transparent) 30%,
      color-mix(in srgb, var(--primary-color) 32%, transparent) 52%,
      transparent 72%),
    linear-gradient(0deg,
      var(--primary-color) 0%,
      color-mix(in srgb, var(--primary-color) 42%, transparent) 26%,
      transparent 52%);
}

.habits-hero-art img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 74% 30%;
  opacity: 0.95;
  filter: saturate(1.06) contrast(1.02);
  mix-blend-mode: normal;
}

body.dark .habits-hero-art,
body.dark .hhw-art,
body.dark .hjw-art {
  background:
    radial-gradient(100% 86% at 50% 12%, rgba(255,255,255,0.18), transparent 64%),
    color-mix(in srgb, var(--secondary-color) 14%, rgba(15,23,42,0.62));
}

body.dark .habits-hero-art img,
body.dark .hhw-art img,
