  align-items: center;
  gap: 10px;
  background: color-mix(in srgb, #f97316 12%, transparent);
  border: 1px solid color-mix(in srgb, #f97316 30%, transparent);
  border-radius: 10px;
  padding: 10px 12px;
  margin-bottom: 14px;
