}

.habit-reminder-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-reminder-item {
  border: 1px solid var(--border-color);
  border-radius: 12px;
  background: var(--light-color);
  overflow: hidden;
}

.habit-reminder-item-top {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
}

.habit-reminder-item-name {
  flex: 1;
  font-weight: 600;
  font-size: 0.95rem;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.habit-reminder-toggle {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  flex-shrink: 0;
}

.habit-reminder-toggle input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}

.habit-reminder-toggle-track {
  width: 44px;
  height: 24px;
  background: var(--border-color);
  border-radius: 12px;
  transition: background 0.2s;
  position: relative;
}

.habit-reminder-toggle-track::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 1px 4px rgba(0,0,0,0.2);
  transition: left 0.2s;
}

.habit-reminder-toggle input:checked + .habit-reminder-toggle-track {
  background: var(--secondary-color);
}

.habit-reminder-toggle input:checked + .habit-reminder-toggle-track::after {
  left: 22px;
}

.habit-reminder-settings {
  border-top: 1px solid var(--border-color);
  padding: 12px 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.habit-reminder-freq-row {
  display: flex;
  gap: 8px;
}

.habit-reminder-freq-btn {
  flex: 1;
  padding: 7px 8px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--card-color);
  color: var(--muted-color);
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
  letter-spacing: 0.02em;
}

.habit-reminder-freq-btn.active {
  background: var(--secondary-color);
  border-color: var(--secondary-color);
  color: white;
}

.habit-reminder-times-label {
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted-color);
  margin-bottom: -4px;
}

.habit-reminder-times {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.habit-reminder-time-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.habit-reminder-time-row input[type="time"] {
  flex: 1;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--card-color);
  color: var(--text-color);
