  color: var(--muted-color);
  font-size: 17px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  line-height: 1;
}

.habit-reminder-remove-time:hover {
  background: color-mix(in srgb, #ef4444 10%, transparent);
