/* When there's no title change, don't reserve space — keeps the toast
   content vertically centered in the banner instead of sitting high. */
.xp-title-change:empty {
  display: none;
}

.xp-modal-bar {
  height: 9px;
  border-radius: 999px;
  background: rgba(0,0,0,0.1);
  overflow: hidden;
}

.xp-modal-fill {
  height: 100%;
  width: 0%;
  background: var(--profile-color, #4f8cff);
  border-radius: 999px;
  transition: width 0.8s ease;
}

.xp-modal-progress-text {
  margin-top: 5px;
  font-size: 0.75rem;
  font-weight: 700;
  opacity: 0.7;
}

.xp-toast-close {
  position: absolute;
  top: 6px;
  left: 8px;
  width: 32px;
  height: 32px;
  border: none;
  background: transparent;
  cursor: pointer;
  padding: 0;
}

.xp-close-x {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--font-color);
  opacity: 0.8;
  pointer-events: none;
}

.xp-close-ring {
  width: 32px;
  height: 32px;
  transform: rotate(-90deg);
}

.xp-ring-bg {
  fill: none;
  stroke: rgba(0,0,0,0.12);
  stroke-width: 3;
}

.xp-ring-progress {
  fill: none;
  stroke: #86898f;
  stroke-width: 3;
  stroke-linecap: round;

  stroke-dasharray: 97.4;
  stroke-dashoffset: 0;
}

.xp-ring-progress.animate {
  animation: xpRingCountdown 9s linear forwards;
}

@keyframes xpRingCountdown {
  from {
    stroke-dashoffset: 0;
  }

  to {
    stroke-dashoffset: 97.4;
  }
}

body.dark .xp-ring-bg {
  stroke: rgba(255,255,255,0.14);
}

body.dark .xp-close-x {
  color: #f3f4f6;
}

body.dark .xp-toast {
  background: rgba(31, 41, 55, 0.98);
  border-color: #4b5563;
}

body.dark .xp-title-change,
body.dark .xp-toast-close {
  color: #f3f4f6;
}

body.dark .xp-modal-bar {
  background: rgba(255,255,255,0.13);
}

.xp-toast:hover {
  transform: translate(-50%, 2px);
}

.complete-lesson-btn.completed {
  opacity: 0.75;
  cursor: default;
}

.complete-lesson-btn.completed::after {
  content: " ✓";
}

.profile-journey-card {
