/* =========================================================
   SETTINGS SCREEN — HARD OVERRIDE
   MUST STAY AT VERY BOTTOM OF FILE
========================================================= */

body #settingsScreen,
body #settingsScreen * {
  transition:
    background-color 0.25s ease,
    border-color 0.25s ease,
    color 0.25s ease,
    box-shadow 0.25s ease;
}

/* Main screen */
body #settingsScreen.screen.active {
  background: var(--primary-light) !important;
  color: var(--font-color) !important;
  display: flex !important;
  flex-direction: column !important;
  height: 100vh !important;
  height: 100dvh !important;            /* cover the bottom safe area (no Safari strip) */
  overflow: hidden !important;
  padding: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* EVERYTHING card-like */
body #settingsScreen .settings-card,
body #settingsScreen .modal-card,
body #settingsScreen .collapse-content,
body #settingsScreen .theme-settings,
body #settingsScreen .theme-preset,
body #settingsScreen .reset-warning,
body #settingsScreen .danger-zone {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--profile-color, #4f8cff) 8%, var(--card-color)),
      var(--card-color)
    ) !important;

  border: 1px solid
    color-mix(in srgb, var(--profile-color, #4f8cff) 28%, var(--border-color))
    !important;

  border-radius: 22px !important;

  box-shadow:
    0 10px 24px rgba(0,0,0,0.10) !important;

  color: var(--font-color) !important;
}

/* ALL settings text */
body #settingsScreen h1,
body #settingsScreen h2,
body #settingsScreen h3,
body #settingsScreen h4,
body #settingsScreen strong,
body #settingsScreen label,
body #settingsScreen span,
body #settingsScreen li,
body #settingsScreen .nav-title {
  color: var(--font-color) !important;
}

/* Muted/helper text */
body #settingsScreen p,
body #settingsScreen small,
body #settingsScreen .helper-text {
  color: var(--muted-color) !important;
}

/* Collapse buttons */
body #settingsScreen .collapse-btn {
  background:
    color-mix(in srgb, var(--profile-color, #4f8cff) 12%, var(--card-color))
    !important;

  border:
    1px solid
    color-mix(in srgb, var(--profile-color, #4f8cff) 35%, var(--border-color))
    !important;

  border-radius: 18px !important;

  color: var(--font-color) !important;

  box-shadow:
    0 8px 18px rgba(0,0,0,0.06)
    !important;
}

body #settingsScreen .collapse-btn:hover {
  background:
    color-mix(in srgb, var(--profile-color, #4f8cff) 18%, var(--card-color))
    !important;
}

/* Theme buttons — strip card styles from the new list-row design */
body #settingsScreen .sett-theme-row.theme-preset {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 14px 16px !important;
}

/* Old grid-style theme buttons (not used in settings any more, kept for safety) */
body #settingsScreen .theme-preset:not(.sett-theme-row) {
  padding: 14px 16px !important;
}

body #settingsScreen .theme-preset.selected {
  outline:
    3px solid var(--profile-color, #4f8cff)
    !important;

  background:
    color-mix(in srgb, var(--profile-color, #4f8cff) 28%, var(--card-color))
    !important;
}

/* Back button */
body #settingsScreen .icon-btn {
  background:
    color-mix(in srgb, var(--profile-color, #4f8cff) 12%, var(--card-color))
    !important;

  border:
    1px solid
    color-mix(in srgb, var(--profile-color, #4f8cff) 35%, var(--border-color))
    !important;

  color: var(--font-color) !important;
}

/* Inputs */
body #settingsScreen input,
body #settingsScreen select {
  background:
    color-mix(in srgb, var(--primary-light) 70%, white)
    !important;

  border:
    1px solid
    color-mix(in srgb, var(--profile-color, #4f8cff) 25%, var(--border-color))
    !important;

  color: var(--font-color) !important;

  border-radius: 14px !important;
}

/* Danger buttons stay red */
body #settingsScreen .danger-btn {
  background: #9f1239 !important;
  color: white !important;
  border: none !important;
}

body #settingsScreen .theme-wheel-tile.theme-preset {
  padding: 8px !important;
  border: 1px solid color-mix(in srgb, var(--border-color) 56%, transparent) !important;
  border-radius: 14px !important;
  background: color-mix(in srgb, var(--card-color) 88%, rgba(255,255,255,0.42)) !important;
  box-shadow: none !important;
  outline: none !important;
}

body #settingsScreen .theme-wheel-tile.theme-preset.selected {
  border-color: color-mix(in srgb, var(--secondary-color) 86%, var(--border-color)) !important;
  background:
    linear-gradient(135deg,
      color-mix(in srgb, var(--secondary-color) 22%, var(--card-color)),
      color-mix(in srgb, var(--accent-color) 14%, var(--card-color))) !important;
  box-shadow:
    0 12px 26px color-mix(in srgb, var(--secondary-color) 24%, transparent),
    inset 0 1px 0 rgba(255,255,255,0.68) !important;
  outline: 2px solid color-mix(in srgb, var(--secondary-color) 42%, transparent) !important;
}

@media (max-width: 380px) {
  body #settingsScreen .theme-wheel-tile.theme-preset {
    padding: 7px !important;
  }
}
html,
body {
  width: 100%;
  min-height: 100%;
  overflow-x: hidden;
  /* Solid (not a gradient) and matched to the screen colour so any sliver of body
     showing past a screen's content on the right edge is invisible — no "band". */
  background: var(--primary-color) !important;
  -webkit-text-size-adjust: 100%;
}

/* allows scrolling, blocks double-tap zoom on controls */
button,
a,
label,
input,
textarea,
select,
.icon-btn,
.main-btn,
.small-btn,
.collapse-btn,
.theme-preset,
.chapter-grid label {
  touch-action: manipulation;
}

/* prevents iPhone zoom when tapping inputs */
input,
textarea,
select {
  font-size: 16px !important;
}
body {
  overflow-y: auto;
  overscroll-behavior: contain;
}
/* HOME SCREEN CLEANUP */
/* ══ Home screen ═══════════════════════════════════════════════════════════ */

#homeScreen.screen.active {
  padding: 0 0 calc(0px + 32px) !important;
  border-radius: 0 !important;
