}
.home-nav-btn .material-symbols-outlined { font-size: 32px !important; color: var(--secondary-color) !important; font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 32 !important; }

/* Hero text block */
.home-hero {
  padding: 24px 22px 18px;
}
.home-title {
