  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted-color);
  opacity: 0.55;
  margin: 22px 0 10px;
}

/* Shared card base for Lessons + grid cards */
.home-feature-card,
.home-grid-card {
  display: flex;
  align-items: center;
  gap: 14px;
