  border: 1px solid var(--border-color);
  border-radius: 20px;
  padding: 16px;
  cursor: pointer;
  text-align: left;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.12s;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}
.home-feature-card:active,
.home-grid-card:active { background: color-mix(in srgb, var(--border-color) 60%, var(--card-color)); }

/* Circular icon background */
.home-feat-icon-wrap {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.home-feat-icon-wrap .material-symbols-outlined {
  font-size: 1.5rem !important;
  color: var(--secondary-color) !important;
  font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 24 !important;
}

/* Text column */
.home-feat-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.home-feat-name {
  font-size: 1rem;
  font-weight: 800;
  color: var(--font-color);
  line-height: 1.1;
}
.home-feat-sub {
  font-size: 0.75rem;
  color: var(--muted-color);
  line-height: 1.3;
}

/* Right chevron */
.home-card-chev {
  font-size: 1.5rem !important;
  color: var(--muted-color) !important;
  opacity: 0.35;
  flex-shrink: 0;
}
.home-rhema-card .home-card-chev {
  color: var(--btn-text-color) !important;
  opacity: 0.6;
}

/* Lessons card sits alone */
.home-feature-card { margin: 0; }

/* 2-col grid */
.home-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 18px;
}
/* Grid cards: row layout matching Lessons card */
.home-grid-card {
  flex-direction: row;
  align-items: center;
  gap: 12px;
  padding: 14px 12px;
}
.home-grid-card .home-feat-text { width: auto; }
.home-grid-card .home-card-chev { display: block; }

/* Locked state mutes the icon wrap slightly */
.home-grid-card.locked-feature-btn .home-feat-icon-wrap {
  background: color-mix(in srgb, var(--muted-color) 10%, transparent);
}
.home-grid-card.locked-feature-btn .home-feat-icon-wrap .material-symbols-outlined {
  color: var(--muted-color) !important;
  opacity: 0.6;
}

/* Rhēma button + cards sit inside horizontal padding */
#homeScreen .home-rhema-card,
#homeScreen .home-feature-card,
#homeScreen .home-grid,
#homeScreen .home-section-label {
  margin-left: 20px;
