  line-height: 1.4;
  color: var(--text-color, inherit);
  /* No transition on the base rule — prevents gold from bleeding into slide animation */
}

.quiz-modal-opt:hover:not(:disabled) {
  border-color: #c9a227;
  background: rgba(201,162,39,0.07);
  transition: border-color 0.12s, background 0.12s;
}

.quiz-modal-opt.qm-selected {
  border-color: #c9a227;
