/* 4. Table inside .paradigm-table fix — the class was designed for div grids,
   but the manuscripts block uses a real <table> element which display:grid breaks */
table.paradigm-table {
  display: table;
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}

.paradigm-table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  border-radius: 10px;
  border: 1px solid rgba(0,0,0,0.1);
  margin: 12px 0;
}

table.paradigm-table th {
  padding: 8px 12px !important;
  text-align: left !important;
  font-weight: 700 !important;
  background: rgba(201, 162, 39, 0.12) !important;
  border-bottom: 2px solid rgba(201, 162, 39, 0.25) !important;
  color: var(--font-color) !important;
}

table.paradigm-table td {
  padding: 8px 12px !important;
  border-bottom: 1px solid rgba(0,0,0,0.07) !important;
  background: transparent !important;
  color: var(--font-color) !important;
}

table.paradigm-table tr:last-child td {
  border-bottom: none !important;
}

body.dark .paradigm-table-wrap {
  border-color: rgba(255,255,255,0.12);
}

