.lb-tab-btn {
  flex: 1;
  padding: 9px 6px;
  border-radius: 12px;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--font-color);
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
  opacity: 0.6;
}
.lb-tab-btn.active {
  background: var(--secondary-color);
  color: var(--btn-text-color);
  border-color: var(--secondary-color);
  opacity: 1;
}

/* Tab panes */
.lb-tab-pane { display: none; flex-direction: column; flex: 1; overflow: hidden; padding: 12px 16px 0; }
.lb-tab-pane.active { display: flex; }
.lb-board-desc { font-size: 0.82rem; color: var(--font-color); opacity: 0.65; margin: 0 0 10px; line-height: 1.4; }

/* Leaderboard list */
.lb-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-bottom: 8px;
  overscroll-behavior: contain;
}
.lb-entry {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--secondary-color) 4%, var(--card-color));
  border: 1px solid var(--border-color);
}
.lb-entry.lb-me {
  border-color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
}
.lb-entry.lb-top-1 { background: linear-gradient(135deg, rgba(255,215,0,0.15), rgba(255,215,0,0.06)); border-color: rgba(255,215,0,0.5); }
.lb-entry.lb-top-2 { background: linear-gradient(135deg, rgba(192,192,192,0.15), rgba(192,192,192,0.06)); border-color: rgba(192,192,192,0.5); }
.lb-entry.lb-top-3 { background: linear-gradient(135deg, rgba(205,127,50,0.15), rgba(205,127,50,0.06)); border-color: rgba(205,127,50,0.5); }
.lb-rank { font-size: 1.3rem; flex-shrink: 0; width: 28px; text-align: center; }
.lb-rank-num { font-size: 0.82rem; font-weight: 900; color: var(--font-color); opacity: 0.5; }
.lb-name { flex: 1; font-weight: 700; font-size: 0.95rem; color: var(--font-color); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lb-value { font-size: 0.82rem; font-weight: 700; color: var(--secondary-color); white-space: nowrap; flex-shrink: 0; }
.lb-loading, .lb-empty { text-align: center; color: var(--font-color); opacity: 0.5; font-size: 0.9rem; padding: 24px 0; }
.lb-retry-btn { background: none; border: 1.5px solid var(--secondary-color); color: var(--secondary-color); border-radius: 20px; padding: 3px 12px; font-size: 0.82rem; font-weight: 700; cursor: pointer; margin-left: 4px; }

/* Join area */
.lb-join-area {
  padding: 12px 0 20px;
  flex-shrink: 0;
}
.lb-join-btn {
  width: 100%;
  padding: 14px;
  border-radius: 14px;
  border: none;
  background: linear-gradient(135deg, #c9a227, #a07c10);
  color: #fff;
  font-size: 1rem;
  font-weight: 900;
  cursor: pointer;
  transition: transform 0.15s;
}
.lb-join-btn:hover { transform: translateY(-1px); }
.lb-retake-btn { background: linear-gradient(135deg, var(--secondary-color), color-mix(in srgb, var(--secondary-color) 70%, #000)); margin-top: 8px; }
.lb-joined-note { text-align: center; font-size: 0.88rem; color: var(--font-color); opacity: 0.7; margin: 0 0 8px; }

/* Primary button (shared) */
.lb-primary-btn {
  display: block;
  width: 100%;
  padding: 14px;
  border-radius: 14px;
  border: none;
  background: linear-gradient(135deg, #c9a227, #a07c10);
  color: #fff;
  font-size: 1rem;
  font-weight: 900;
  cursor: pointer;
  margin-top: 8px;
  transition: transform 0.15s;
}
.lb-primary-btn:hover { transform: translateY(-1px); }

/* Name entry modal */
.lb-name-btns { display: flex; gap: 10px; }
.lb-cancel-btn {
  flex: 1;
  padding: 12px;
  border-radius: 12px;
  border: 1.5px solid var(--border-color);
  background: transparent;
  color: var(--font-color);
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
}

/* Scholar test modal */
.lb-scholar-overlay.open {
  display: flex;
  align-items: center;
  justify-content: center;
}
.lb-scholar-card {
  background: var(--card-color);
  border-radius: 24px;
  padding: 28px 24px 32px;
  max-width: 380px;
  width: 92%;
  text-align: center;
  box-shadow: 0 24px 60px rgba(0,0,0,0.25);
}
.lb-scholar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}
.lb-scholar-timer-wrap {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--secondary-color);
}
.lb-scholar-timer-wrap .material-symbols-outlined { font-size: 20px; }
.scholar-timer-warning { color: #e53935 !important; }
.lb-scholar-score-wrap { font-size: 0.95rem; color: var(--font-color); opacity: 0.8; }
.lb-scholar-word {
  font-size: 2.8rem;
  font-weight: 900;
  color: var(--font-color);
  margin: 16px 0 14px;
  letter-spacing: -1px;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.scholar-feedback {
  min-height: 22px;
  font-size: 0.88rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 10px;
}
.scholar-feedback-correct { color: #2e7d32; }
.scholar-feedback-wrong { color: #c62828; }
.scholar-answer-input {
  width: 100%;
  box-sizing: border-box;
  padding: 13px 16px;
  border-radius: 14px;
  border: 2px solid var(--border-color);
  background: var(--card-color);
  color: var(--font-color);
  font-size: 1rem;
  margin-bottom: 12px;
  outline: none;
  transition: border-color 0.15s;
}
.scholar-answer-input:focus { border-color: var(--secondary-color); }
.scholar-input-correct { border-color: #2e7d32 !important; background: rgba(46,125,50,0.08) !important; }
.scholar-input-wrong { border-color: #c62828 !important; background: rgba(198,40,40,0.08) !important; }
.scholar-answer-input:disabled { opacity: 0.7; }
.lb-scholar-btns { display: flex; gap: 10px; }
.lb-skip-btn {
  flex: 1;
  padding: 13px;
  border-radius: 14px;
  border: 1.5px solid var(--border-color);
  background: transparent;
  color: var(--font-color);
  font-size: 0.92rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
}
.lb-skip-btn:hover { background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color)); }
.lb-know-btn {
  flex: 2;
  padding: 13px;
  border-radius: 14px;
  border: none;
  background: linear-gradient(135deg, var(--secondary-color), color-mix(in srgb, var(--secondary-color) 70%, #000));
  color: var(--btn-text-color);
  font-size: 0.96rem;
  font-weight: 900;
  cursor: pointer;
  transition: transform 0.15s;
}
.lb-know-btn:hover { transform: translateY(-1px); }
.lb-skip-btn:disabled, .lb-know-btn:disabled { opacity: 0.4; cursor: default; transform: none; }
.lb-scholar-quit {
  background: transparent;
  border: none;
  font-size: 1.4rem;
  color: var(--font-color);
  opacity: 0.45;
  cursor: pointer;
  padding: 0 2px;
  line-height: 1;
}
.lb-scholar-quit:hover { opacity: 0.8; }

/* Profile badges */
.profile-badge-row {
  display: flex;
  gap: 6px;
  justify-content: center;
  flex-wrap: wrap;
  min-height: 0;
  margin-bottom: 4px;
}
.profile-lb-badge {
  font-size: 1.5rem;
  cursor: default;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));
  transition: transform 0.15s;
}
.profile-lb-badge:hover { transform: scale(1.2); }

/* ── v1.4.0 Profile & Leaderboard Overhaul ──────────────────────────────── */

/* Profile avatar wrap + pencil edit button */
.profile-avatar-wrap {
  position: relative;
  display: inline-block;
  margin-bottom: 10px;
}
.profile-avatar-edit {
  position: absolute;
  bottom: 0;
  right: -4px;
  width: 28px;
  height: 28px;
