.profile-lb-badge .material-symbols-outlined { font-size: 14px; }
.lb-badge-rank-num { font-size: 0.72rem; font-weight: 900; }

/* Board-specific badge colors */
.lb-badge-xp     { background: rgba(245,158,11,0.18); color: #d97706; border: 1px solid rgba(245,158,11,0.4); }
.lb-badge-scholar { background: rgba(59,130,246,0.15); color: #2563eb; border: 1px solid rgba(59,130,246,0.35); }
