.lb-badge-rank-2 { opacity: 0.88; }
.lb-badge-rank-3 { opacity: 0.72; }

body.dark .lb-badge-xp     { background: rgba(245,158,11,0.22); color: #fbbf24; }
body.dark .lb-badge-scholar { background: rgba(96,165,250,0.2);  color: #60a5fa; }
body.dark .lb-badge-cons   { background: rgba(252,165,165,0.2); color: #f87171; }

/* Badge info modal */
.badge-info-card {
  background: var(--card-color);
  border-radius: 20px;
  padding: 32px 24px 24px;
