.lb-badge-scholar.badge-info-big-icon { color: #2563eb; }
.lb-badge-cons.badge-info-big-icon   { color: #dc2626; }
.badge-info-title { font-size: 1.1rem; font-weight: 900; color: var(--font-color); margin: 0 0 6px; }
.badge-info-sub { font-size: 0.88rem; color: var(--font-color); opacity: 0.65; margin: 0 0 20px; line-height: 1.4; }

/* Avatar picker modal */
.avatar-picker-card {
  background: var(--card-color);
  border-radius: 24px;
  padding: 24px 20px;
  max-width: 400px;
