}
.reminder-label {
  font-size: 0.72rem;
  font-weight: 700;
  opacity: 0.45;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}
.reminder-time-wrapper {
  display: flex;
  align-items: center;
  padding: 11px 14px;
  border-radius: 12px;
  border: 1.5px solid color-mix(in srgb, var(--font-color) 18%, transparent);
  background: color-mix(in srgb, var(--font-color) 5%, transparent);
