}
.reminder-time-wrapper:focus-within {
  border-color: var(--accent-color, #c9a227);
}
.reminder-time-input {
  -webkit-appearance: none;
  appearance: none;
  border: none;
  outline: none;
  background: transparent;
  color: var(--font-color);
  font-size: 1rem;
  font-family: inherit;
  width: 100%;
  min-width: 0;
  padding: 0;
}
.reminder-freq-options {
  display: flex;
  gap: 6px;
}
.reminder-freq-opt {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 9px 6px;
