.reminder-freq-opt input[type="radio"] { display: none; }
.reminder-freq-opt:has(input:checked) {
  border-color: var(--accent-color, #c9a227);
  background: color-mix(in srgb, var(--accent-color, #c9a227) 14%, transparent);
  color: var(--accent-color, #c9a227);
