}
.reminder-notif-warning {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--secondary-color) 10%, var(--card-color));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 28%, transparent);
