.reminder-notif-warning .material-symbols-outlined { font-size: 1.15rem; flex-shrink: 0; }
.reminder-notif-warning > span:nth-child(2) { flex: 1; }
.reminder-notif-enable-btn {
  background: var(--secondary-color);
  color: #fff;
