  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  flex-shrink: 0;
}
.reminder-modal-card .main-btn {
  margin-top: 6px;
  padding: 12px;
  font-size: 0.95rem;
}
.reminder-modal-card .text-btn {
  font-size: 0.84rem;
  padding: 7px;
  opacity: 0.55;
  margin-top: 0;
}
.notifications-enabled .material-symbols-outlined { color: #16a34a; }


/* ══ Rhēma Word Study — all colors via CSS variables, theme-aware ════════════ */

/* ── Rhema full-screen wrapper: fixed to viewport, never transformed ── */
#rhemaModal {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: none;
  overflow: hidden;
}
#rhemaModal.open {
  display: block;
}

/* ── Animated slide-up panel: transform lives here, flex column layout lives here ── */
#rhemaSlide {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  background: var(--primary-light);
  overflow: hidden;
  transform: translateY(100%);
  transition: transform 0.32s cubic-bezier(0.32, 0.72, 0, 1);
  overscroll-behavior: none;
  /* allow both axes so .rsx-diagram can scroll horizontally */
  touch-action: pan-x pan-y;
}
#rhemaModal.open #rhemaSlide {
  transform: translateY(0);
}

/* ── Header ── */
.rhema-header {
  display: grid;
  grid-template-columns: 44px 1fr auto;
  align-items: center;
  gap: 8px;
  padding: calc(env(safe-area-inset-top, 20px) + 14px) 14px 14px;
  background: var(--card-color);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1.5px solid var(--border-color);
  flex-shrink: 0;
  touch-action: none; /* swipes here must not scroll ancestors */
  overscroll-behavior: none;
}

.rhema-title-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.rhema-title {
  font-size: 1.3rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--secondary-color);
  line-height: 1;
}
.rhema-title-greek {
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  color: var(--muted-color);
  text-transform: none;
}

.rhema-header-actions {
  display: flex;
  gap: 6px;
  align-items: center;
}

/* ── Shared raised-glass style for header action buttons ── */
.rhema-back-btn.icon-btn {
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(255,255,255,0.92), color-mix(in srgb, var(--secondary-color) 6%, rgba(255,255,255,0.85)));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 18%, rgba(255,255,255,0.6));
  box-shadow: 0 2px 8px color-mix(in srgb, var(--secondary-color) 12%, rgba(0,0,0,0.08)), 0 1px 2px rgba(0,0,0,0.06), inset 0 1px 1px rgba(255,255,255,0.8);
  color: var(--secondary-color);
  width: 40px;
  height: 40px;
  min-width: 40px;
  transition: all 0.15s;
}
.rhema-back-btn.icon-btn:active {
  background: linear-gradient(145deg, color-mix(in srgb, var(--secondary-color) 15%, rgba(255,255,255,0.85)), rgba(255,255,255,0.8));
  box-shadow: 0 1px 4px color-mix(in srgb, var(--secondary-color) 15%, rgba(0,0,0,0.1));
  transform: scale(0.96);
}

.rhema-swap-btn {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  background: linear-gradient(145deg, rgba(255,255,255,0.92), color-mix(in srgb, var(--secondary-color) 6%, rgba(255,255,255,0.85)));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 18%, rgba(255,255,255,0.6));
  border-radius: 14px;
  padding: 3px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--secondary-color);
  cursor: pointer;
  transition: all 0.15s;
  letter-spacing: 0.02em;
  box-shadow: 0 2px 8px color-mix(in srgb, var(--secondary-color) 12%, rgba(0,0,0,0.08)), 0 1px 2px rgba(0,0,0,0.06), inset 0 1px 1px rgba(255,255,255,0.8);
}
.rhema-swap-btn:active {
  transform: scale(0.96);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--secondary-color) 15%, rgba(0,0,0,0.1));
}
.rhema-swap-seg {
  padding: 5px 9px;
  border-radius: 11px;
  color: color-mix(in srgb, var(--secondary-color) 70%, var(--muted-color));
  white-space: nowrap;
  transition: all 0.15s;
}
.rhema-swap-seg.active {
  background: linear-gradient(145deg, var(--secondary-color), color-mix(in srgb, var(--secondary-color) 80%, #000));
  color: var(--btn-text-color);
  box-shadow: 0 2px 6px color-mix(in srgb, var(--secondary-color) 35%, rgba(0,0,0,0.12));
}

/* ── Magic-wand tool button ── */
.rhema-tool-btn {
  position: relative;
  background: linear-gradient(145deg, rgba(255,255,255,0.92), color-mix(in srgb, var(--secondary-color) 6%, rgba(255,255,255,0.85)));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 18%, rgba(255,255,255,0.6));
  border-radius: 14px;
  padding: 8px 10px;
  color: var(--secondary-color);
  cursor: pointer;
  transition: all 0.15s;
  display: flex;
  align-items: center;
  box-shadow: 0 2px 8px color-mix(in srgb, var(--secondary-color) 12%, rgba(0,0,0,0.08)), 0 1px 2px rgba(0,0,0,0.06), inset 0 1px 1px rgba(255,255,255,0.8);
}
.rhema-tool-btn .material-symbols-outlined { font-size: 18px; }
.rhema-tool-dot {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--secondary-color);
  display: none;
}
.rhema-tool-btn.has-active .rhema-tool-dot { display: block; }
.rhema-tool-btn.has-active {
  background: linear-gradient(145deg, color-mix(in srgb, var(--secondary-color) 15%, rgba(255,255,255,0.9)), color-mix(in srgb, var(--secondary-color) 8%, rgba(255,255,255,0.85)));
  border-color: color-mix(in srgb, var(--secondary-color) 35%, rgba(255,255,255,0.6));
}
.rhema-tool-btn:active {
  transform: scale(0.96);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--secondary-color) 15%, rgba(0,0,0,0.1));
}

/* ── Wheel overlay ── */
.rhema-wheel-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1080;
  background: color-mix(in srgb, var(--secondary-color) 18%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  opacity: 0;
  transition: opacity 0.22s ease;
}
.rhema-wheel-overlay.open { opacity: 1; }
.rhema-wheel { position: relative; width: 0; height: 0; }
.rhema-wheel-center {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--card-color);
  border: 2px solid var(--border-color);
  color: var(--font-color);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 20px rgba(0,0,0,0.18);
  z-index: 2;
}
.rhema-wheel-center .material-symbols-outlined { font-size: 22px; }
.rhema-wheel-item {
  position: absolute;
  transform: translate(-50%, -50%) scale(0);
  opacity: 0;
  width: 78px;
  height: 78px;
  border-radius: 50%;
  background: var(--card-color);
  border: 2px solid var(--border-color);
  color: var(--font-color);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.14);
  transition: transform 0.3s cubic-bezier(0.34,1.56,0.64,1), opacity 0.2s ease, background 0.15s;
}
.rhema-wheel-item .material-symbols-outlined { font-size: 22px; }
.rwi-label { font-size: 0.55rem; font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase; opacity: 0.8; line-height: 1.05; }
#wheelItemHighlightsNotes {
  gap: 2px;
  text-align: center;
}
#wheelItemHighlightsNotes .material-symbols-outlined {
  font-size: 20px;
  line-height: 1;
}
#wheelItemHighlightsNotes .rwi-label {
  max-width: 58px;
  font-size: 0.48rem;
  line-height: 0.98;
  letter-spacing: 0.01em;
}
.rhema-wheel-item.active {
  background: var(--secondary-color);
  border-color: var(--secondary-color);
  color: var(--btn-text-color);
}
.rhema-wheel-item.disabled {
  opacity: 0.52;
  border-style: dashed;
  cursor: help;
  filter: grayscale(0.2);
}
.rhema-wheel-overlay.open .rhema-wheel-item.disabled {
  opacity: 0.62;
}
.rhema-wheel-item.rw-placeholder { opacity: 0; }
.rhema-wheel-overlay.open .rhema-wheel-item.rw-placeholder { opacity: 0.45; }
/* Decagon positions (r=128px, clockwise from top) */
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(1) { transform: translate(calc(-50% + 0px),    calc(-50% + -128px)) scale(1); opacity: 1; transition-delay: 0s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(2) { transform: translate(calc(-50% + 75px),   calc(-50% + -104px)) scale(1); opacity: 1; transition-delay: 0.03s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(3) { transform: translate(calc(-50% + 122px),  calc(-50% + -40px))  scale(1); opacity: 1; transition-delay: 0.06s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(4) { transform: translate(calc(-50% + 122px),  calc(-50% + 40px))   scale(1); opacity: 1; transition-delay: 0.09s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(5) { transform: translate(calc(-50% + 75px),   calc(-50% + 104px))  scale(1); opacity: 1; transition-delay: 0.12s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(6) { transform: translate(calc(-50% + 0px),    calc(-50% + 128px))  scale(1); opacity: 1; transition-delay: 0.15s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(7) { transform: translate(calc(-50% + -75px),  calc(-50% + 104px))  scale(1); opacity: 1; transition-delay: 0.18s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(8) { transform: translate(calc(-50% + -122px), calc(-50% + 40px))   scale(1); opacity: 1; transition-delay: 0.21s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(9) { transform: translate(calc(-50% + -122px), calc(-50% + -40px))  scale(1); opacity: 1; transition-delay: 0.24s; }
.rhema-wheel-overlay.open .rhema-wheel-item:nth-child(10){ transform: translate(calc(-50% + -75px),  calc(-50% + -104px)) scale(1); opacity: 1; transition-delay: 0.27s; }

/* Scripture Trail Cross References */
.rhema-xref-page {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: flex;
  flex-direction: column;
  background: var(--primary-color);
  color: var(--text-color);
  overscroll-behavior: none;
}
/* While a cross-reference overlay is open, freeze the page underneath so a
   scroll inside the panel never bleeds through to the reader in the back. */
html.rx-scroll-lock,
body.rx-scroll-lock {
  overflow: hidden !important;
  overscroll-behavior: none;
  touch-action: none;
}
.rhema-xref-page.hidden,
.rhema-xref-info.hidden { display: none; }
.rx-page-header {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  align-items: center;
  gap: 8px;
  padding: calc(env(safe-area-inset-top, 18px) + 12px) 16px 10px;
  background: var(--primary-color);
  flex-shrink: 0;
}
.rx-page-header h2 {
  margin: 0;
  text-align: center;
  font-size: 0.98rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-color);
}
.rx-icon-btn,
.rx-header-spacer {
  width: 40px;
  height: 40px;
  border-radius: 50%;
}
.rx-icon-btn {
  border: 1px solid color-mix(in srgb, var(--secondary-color) 14%, var(--border-color));
  background: color-mix(in srgb, var(--secondary-color) 9%, var(--card-color));
  color: var(--secondary-color);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.rx-icon-btn .material-symbols-outlined { font-size: 22px; }
.rx-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 10px 16px calc(0px + 22px);
  display: flex;
  flex-direction: column;
  gap: 14px;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}
.rx-breadcrumb {
  display: flex;
  align-items: center;
  padding-bottom: 10px;
  flex-shrink: 0;
  min-width: 0;
}
.rx-breadcrumb-scroll {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  overflow-x: auto;
  padding: 0 16px;
  scrollbar-width: none;
  overscroll-behavior: contain;
}
.rx-breadcrumb-scroll::-webkit-scrollbar { display: none; }
.rx-breadcrumb-scroll button {
  border: none;
  background: transparent;
  color: var(--muted-color);
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
  padding: 4px 3px;
  flex-shrink: 0;
}
.rx-breadcrumb-scroll button.active { color: var(--secondary-color); }
.rx-breadcrumb-scroll .material-symbols-outlined {
  font-size: 16px;
  color: color-mix(in srgb, var(--secondary-color) 32%, var(--muted-color));
  flex-shrink: 0;
}
.rx-breadcrumb-clear {
  flex-shrink: 0;
  border: none;
  background: transparent;
  padding: 0 10px 0 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  color: var(--muted-color);
  position: relative;
}
.rx-breadcrumb-clear::before {
  content: '';
  position: absolute;
  right: 100%;
  top: -6px;
  bottom: 0;
  width: 28px;
  background: linear-gradient(to right, transparent, var(--primary-color));
  pointer-events: none;
}
.rx-breadcrumb-clear .material-symbols-outlined { font-size: 18px; }
@keyframes rx-shake {
  0%, 100% { transform: translateX(0); }
  20%       { transform: translateX(-5px); }
  40%       { transform: translateX(5px); }
  60%       { transform: translateX(-4px); }
  80%       { transform: translateX(3px); }
}
.rx-category-card.rx-shaking { animation: rx-shake 0.35s ease; }
.rx-category-card.rx-no-data {
  opacity: 0.4;
  cursor: default;
}
.rx-category-card.rx-no-data .rx-category-icon {
  background: color-mix(in srgb, var(--muted-color) 12%, var(--card-color));
  color: var(--muted-color);
}
.rx-top-card {
  position: relative;
  display: block;
  width: 100%;
  min-height: 142px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 28%, var(--border-color));
  border-radius: 22px;
  padding: 20px 22px;
  text-align: left;
  background: color-mix(in srgb, var(--secondary-color) 6%, var(--card-color));
  color: var(--text-color);
  overflow: hidden;
  cursor: pointer;
  box-sizing: border-box;
}
.rx-top-card h3,
.rx-selected-card strong {
  margin: 0 0 8px;
  font-size: 1.22rem;
  line-height: 1.2;
  color: var(--secondary-color);
}
.rx-top-card p {
  margin: 0;
  max-width: 88%;
  font-size: 1rem;
  line-height: 1.55;
}
.rx-change {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 18px;
  color: var(--secondary-color);
  font-size: 0.82rem;
  font-weight: 700;
}
.rx-change .material-symbols-outlined { font-size: 19px; }
.rx-top-watermark {
  position: absolute;
  right: 26px;
  top: 50px;
  color: color-mix(in srgb, var(--secondary-color) 10%, transparent);
  font-size: 62px;
  pointer-events: none;
}
.rx-category-list,
.rx-verse-stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.rx-category-card,
.rx-active-category,
.rx-verse-card,
.rx-selected-card,
.ss-trail-item {
  border: 1px solid color-mix(in srgb, var(--secondary-color) 10%, var(--border-color));
  border-radius: 20px;
  background: var(--card-color);
  box-shadow: 0 8px 22px rgba(0,0,0,0.035);
}
.rx-category-card {
  width: 100%;
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) 24px;
  gap: 10px;
  align-items: start;
  padding: 18px;
  text-align: left;
  color: var(--text-color);
  cursor: pointer;
}
.rx-category-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--secondary-color) 10%, var(--card-color));
