  align-items: center;
  justify-content: center;
}
.rx-active-category strong {
  display: block;
  font-size: 0.96rem;
  line-height: 1.3;
}
.rx-active-category p {
  margin: 4px 0 0;
  color: var(--muted-color);
  font-size: 0.8rem;
  line-height: 1.35;
}
.rx-verse-card {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 46px;
  gap: 14px;
  align-items: center;
  padding: 22px;
  text-align: left;
  color: var(--text-color);
