  right: 26px;
  font-size: 44px;
  color: color-mix(in srgb, var(--text-color) 13%, transparent);
}

.rx-category-card,
.rx-active-category {
  --rx-cat-color: var(--secondary-color);
  border: 1px solid color-mix(in srgb, var(--rx-cat-color) 11%, var(--border-color));
  border-radius: 22px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--rx-cat-color) 4%, var(--card-color)),
    var(--card-color)
  );
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.075);
}

.rx-category-card {
  grid-template-columns: 58px minmax(0, 1fr) 28px;
  gap: 14px;
  align-items: center;
  padding: 20px 18px;
}

.rx-category-icon {
  background: color-mix(in srgb, var(--rx-cat-color) 12%, var(--card-color));
  color: var(--rx-cat-color);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  padding: 0;
  text-align: center;
  line-height: 1;
}

.rx-category-icon .material-symbols-outlined {
  position: absolute;
  top: 50%;
  left: 50%;
  display: block;
  width: auto;
  height: auto;
  color: currentColor;
  font-size: 28px;
  line-height: 1;
  text-align: center;
  transform: translate(-50%, -50%);
  font-variation-settings: 'FILL' 0, 'wght' 500, 'GRAD' 0, 'opsz' 28;
}

.rx-category-icon {
  width: 56px;
  height: 56px;
  min-width: 56px;
  min-height: 56px;
  align-self: start;
  margin-top: 2px;
  position: relative;
}

.rx-category-title {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  color: var(--text-color);
  font-size: 1.1rem;
}

.rx-category-title em,
.rx-active-category em {
  margin-left: 0;
  color: var(--rx-cat-color);
  background: color-mix(in srgb, var(--rx-cat-color) 11%, var(--card-color));
}

.rx-category-desc {
  font-size: 0.94rem;
}

.rx-preview-line {
  margin-top: 10px;
  padding: 12px 42px 12px 14px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--rx-cat-color) 12%, var(--border-color));
  border-left: 4px solid var(--rx-cat-color);
  background: color-mix(in srgb, var(--rx-cat-color) 3%, var(--card-color));
}

.rx-preview-line strong {
  color: var(--text-color);
  font-size: 0.95rem;
}

.rx-preview-line span {
  color: var(--muted-color);
  opacity: 1;
  font-size: 0.88rem;
}

.rx-chip-row span,
.rx-verse-copy em {
  color: var(--rx-cat-color);
  background: color-mix(in srgb, var(--rx-cat-color) 12%, var(--card-color));
}

.rx-card-arrow {
  color: var(--rx-cat-color);
  justify-self: center;
  align-self: center;
  line-height: 1;
}

.rx-category-card.rx-no-data {
  opacity: 0.48;
}

.rx-category-card.rx-no-data .rx-category-icon,
.rx-category-card.rx-no-data .rx-card-arrow {
  color: var(--muted-color);
}

.rx-category-card.rx-no-data .rx-category-icon .material-symbols-outlined {
  color: var(--muted-color);
}

.rx-active-category {
  grid-template-columns: 56px minmax(0, 1fr);
  padding: 18px;
}

.rx-active-category > .rx-category-icon {
  width: 52px;
  height: 52px;
  min-width: 52px;
  min-height: 52px;
}

.rx-active-category strong {
  color: var(--text-color);
}

.rx-verse-card {
  border-radius: 20px;
  box-shadow: 0 9px 24px rgba(15, 23, 42, 0.07);
}

.rx-arrow-btn {
  display: inline-grid;
  place-items: center;
  line-height: 1;
  text-align: center;
}

.rx-arrow-btn.material-symbols-outlined {
  display: inline-grid;
  place-items: center;
  line-height: 1;
}

@media (max-width: 420px) {
  .rx-top-card {
    padding-right: 68px;
  }

  .rx-category-card {
    grid-template-columns: 52px minmax(0, 1fr) 24px;
    gap: 12px;
    padding: 18px 16px;
  }

  .rx-category-icon {
    width: 50px;
    height: 50px;
    min-width: 50px;
    min-height: 50px;
  }
}

/* ── Syntax tree view ── */
.rsx-tree { padding: 0 12px 32px; }

.rsx-attr-bar { display: flex; align-items: center; justify-content: space-between; padding: 10px 2px 8px; }
.rsx-attr-label { font-size: 0.65rem; font-weight: 700; letter-spacing: 0.07em; text-transform: uppercase; color: var(--muted-color); opacity: 0.75; }
.rsx-info-btn { background: none; border: none; color: var(--muted-color); cursor: pointer; display: flex; align-items: center; padding: 4px; opacity: 0.65; transition: opacity 0.15s; }
.rsx-info-btn:active { opacity: 1; }
.rsx-info-btn .material-symbols-outlined { font-size: 18px; }

.rsx-warning {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 12px;
  padding: 10px 12px;
  background: color-mix(in srgb, #f59e0b 12%, var(--card-color));
  border: 1px solid color-mix(in srgb, #f59e0b 32%, transparent);
  border-radius: 10px;
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--font-color);
}
.rsx-warning .material-symbols-outlined { font-size: 18px; color: #f59e0b; flex-shrink: 0; margin-top: 1px; }

/* ── Syntax diagram (horizontal tree) ──────────────────────────────── */

/* Syntax tree must span all 4 grid columns so the diagram has full width for 2D scrolling */
.rhema-verse-display .rsx-tree {
  grid-column: 1 / -1;
}

.rsx-diagram {
  overflow-x: auto;
  overflow-y: auto;
  max-height: calc(100svh - 200px);
  padding: 12px 16px 28px;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  touch-action: pan-x pan-y;
  cursor: grab;
}
.rsx-diagram.grabbing { cursor: grabbing; }

/* Multiple top-level roots (genuine parallel main clauses) */
.rsx-dg-roots {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: max-content;
}

/* Branch = node card + its subtree of children, laid out left→right */
.rsx-dg-branch {
  display: flex;
  flex-direction: row;
  align-items: center;
  width: max-content;
}

/* ── Node card ── */
.rsx-dg-node {
  width: 168px;
  flex-shrink: 0;
  border: 2px solid var(--clr);
  border-radius: 11px;
  overflow: hidden;
  background: var(--card-color);
  box-shadow: 0 1px 5px rgba(0,0,0,0.07);
}

/* Colored header bar: conjunction word + clause-type label */
.rsx-dg-hdr {
  display: flex;
  align-items: baseline;
  gap: 5px;
  flex-wrap: wrap;
  padding: 5px 9px;
  background: var(--clr);
}
.rsx-dg-conj {
  font-family: 'Noto Serif', serif;
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
}
.rsx-dg-lbl {
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.82);
}

/* ── Phrase chip inside node ── */
.rsx-dg-chip {
  padding: 5px 9px;
  border-bottom: 1px solid rgba(0,0,0,0.05);
  cursor: pointer;
  transition: filter 0.12s;
}
.rsx-dg-chip:last-child { border-bottom: none; }
.rsx-dg-chip:active, .rsx-dg-chip.rsx-selected { filter: brightness(0.9); }

.rsx-dg-chip-role {
  display: block;
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  margin-bottom: 3px;
  opacity: 0.72;
}

.rsx-dg-chip-gr {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 6px;
}

.rsx-dg-wd {
  display: flex;
  flex-direction: column;
  cursor: pointer;
}
.rsx-dg-wd:active { opacity: 0.65; }
.rsx-dg-wd-gr { font-family: 'Noto Serif', serif; font-size: 0.95rem; color: var(--font-color); line-height: 1.3; }
.rsx-dg-wd-gl { font-size: 0.58rem; color: var(--muted-color); line-height: 1.2; }

/* Chip role-color tints */
.rsx-c-verb  .rsx-dg-chip-role { color: #c2410c; }
.rsx-c-subj  .rsx-dg-chip-role { color: #1d4ed8; }
.rsx-c-obj   .rsx-dg-chip-role { color: #15803d; }
.rsx-c-gen   .rsx-dg-chip-role { color: #6d28d9; }
.rsx-c-dat   .rsx-dg-chip-role { color: #be123c; }
.rsx-c-prep  .rsx-dg-chip-role { color: #0f766e; }
.rsx-c-conj  .rsx-dg-chip-role { color: #92400e; }
.rsx-c-part  .rsx-dg-chip-role { color: #c2410c; }
.rsx-c-other .rsx-dg-chip-role { color: var(--muted-color); }

.rsx-c-verb  .rsx-dg-chip { background: rgba(251,146,60,0.10); }
.rsx-c-subj  .rsx-dg-chip { background: rgba(96,165,250,0.10); }
.rsx-c-obj   .rsx-dg-chip { background: rgba(74,222,128,0.10); }
.rsx-c-gen   .rsx-dg-chip { background: rgba(167,139,250,0.10); }
.rsx-c-dat   .rsx-dg-chip { background: rgba(251,113,133,0.10); }
.rsx-c-prep  .rsx-dg-chip { background: rgba(45,212,191,0.10); }
.rsx-c-conj  .rsx-dg-chip { background: rgba(250,204,21,0.08); }
.rsx-c-part  .rsx-dg-chip { background: rgba(253,186,116,0.10); }

/* Main verb chip — visually dominant */
.rsx-dg-chip--main { padding: 7px 9px; }
.rsx-dg-chip--main .rsx-dg-chip-role { opacity: 0.9; font-size: 0.63rem; }
.rsx-dg-chip--main .rsx-dg-wd-gr { font-size: 1.05rem; }

/* Dependent genitive — indented under its anchor noun */
.rsx-dg-chip--dep {
  padding-left: 18px;
  border-left: 3px solid rgba(167,139,250,0.4);
  opacity: 0.88;
}

/* Clause subtitle — muted helper text inside header bar */
.rsx-dg-subtitle {
  flex-basis: 100%;
  font-size: 0.52rem;
  color: rgba(255,255,255,0.58);
  font-style: italic;
  line-height: 1.3;
  margin-top: -2px;
  letter-spacing: 0;
  text-transform: none;
}

/* ── Children subtree ── */
.rsx-dg-subtree {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-self: stretch;
  justify-content: center;
}

/* Vertical bus line when multiple children share the same parent */
.rsx-dg-multi {
  border-left: 2px solid var(--border-color);
  margin-left: 4px;
}

/* One child row = arm (arrow) + child branch */
.rsx-dg-child {
  display: flex;
  flex-direction: row;
  align-items: center;
}

/* Horizontal arrow connecting parent to child */
.rsx-dg-arm {
  width: 40px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  padding: 0 2px;
}
.rsx-dg-multi .rsx-dg-arm { width: 28px; }

.rsx-dg-arr {
  flex: 1;
  height: 2px;
  background: var(--clr);
  position: relative;
}
.rsx-dg-arr::after {
  content: '';
  position: absolute;
  right: -1px;
  top: 50%;
  transform: translateY(-50%);
  border-left: 7px solid var(--clr);
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
}

/* ── Syntax explanation sheet ── */
.rhema-syntax-sheet { min-height: unset; max-height: 72svh; }
.rsx-sheet-scroll { overflow-y: auto; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
.rsx-sheet-inner { padding: 4px 22px 32px; }
.rsx-sheet-greek { font-size: 1.4rem; font-weight: 500; letter-spacing: 0.03em; color: var(--font-color); line-height: 1.45; margin-bottom: 4px; word-break: break-word; }
.rsx-sheet-role  { font-size: 0.95rem; font-weight: 700; color: var(--secondary-color); margin-bottom: 14px; }
.rsx-body-main   { font-size: 0.88rem; line-height: 1.72; color: var(--font-color); margin: 0 0 12px; }
.rsx-body-section { margin-bottom: 10px; padding: 10px 12px; background: var(--primary-light); border-radius: 10px; }
.rsx-section-label { display: block; font-size: 0.59rem; font-weight: 800; letter-spacing: 0.09em; text-transform: uppercase; color: var(--muted-color); margin-bottom: 6px; }
.rsx-body-section p { font-size: 0.85rem; line-height: 1.68; color: var(--font-color); margin: 0; }
.rsx-study-q { background: color-mix(in srgb, var(--secondary-color) 10%, var(--card-color)); border: 1px solid color-mix(in srgb, var(--secondary-color) 22%, transparent); }
.rsx-study-q .rsx-section-label { color: var(--secondary-color); }
.rsx-study-q p { font-weight: 500; }

/* ── Syntax info sheet ── */
.rhema-syntax-info-sheet { min-height: unset; max-height: 78svh; }
.rsx-info-scroll { overflow-y: auto; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
.rsx-info-inner { padding: 8px 22px 36px; }
.rsx-info-title { font-size: 1.05rem; font-weight: 700; color: var(--font-color); margin: 0 0 14px; }
.rsx-info-text { font-size: 0.86rem; line-height: 1.72; color: var(--font-color); margin: 0 0 10px; }
.rsx-info-emphasis { font-size: 0.88rem; font-weight: 600; line-height: 1.65; color: var(--secondary-color); padding: 12px 14px; background: color-mix(in srgb, var(--secondary-color) 10%, var(--card-color)); border-radius: 10px; margin: 14px 0 12px; }
.rsx-info-source { font-size: 0.78rem; line-height: 1.6; color: var(--muted-color); margin: 0; }

/* ── Coach mark onboarding ── */
.rhema-coach-overlay {
  position: absolute;
  inset: 0;
  z-index: 1200;
  pointer-events: all;
}
.rhema-coach-overlay.hidden { display: none; }
.rhema-coach-spotlight {
  position: absolute;
  border-radius: 12px;
  box-shadow: 0 0 0 100vmax rgba(0,0,0,0.72);
  transition: top 0.35s cubic-bezier(.4,0,.2,1),
              left 0.35s cubic-bezier(.4,0,.2,1),
              width 0.35s cubic-bezier(.4,0,.2,1),
              height 0.35s cubic-bezier(.4,0,.2,1);
  pointer-events: none;
}
.rhema-coach-card {
  position: absolute;
  background: var(--card-color);
  border-radius: 18px;
  padding: 20px 20px 16px;
  width: min(320px, calc(100vw - 40px));
  max-height: calc(100% - 40px);
  overflow-y: auto;
  box-shadow: 0 8px 32px rgba(0,0,0,0.38);
  transition: top 0.28s cubic-bezier(.4,0,.2,1),
              left 0.28s cubic-bezier(.4,0,.2,1),
              transform 0.28s cubic-bezier(.4,0,.2,1);
  pointer-events: all;
  overscroll-behavior: contain;
}
.rhema-coach-step-label {
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--secondary-color);
  margin-bottom: 5px;
}
.rhema-coach-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--font-color);
  margin-bottom: 7px;
  line-height: 1.3;
}
.rhema-coach-body {
  font-size: 0.84rem;
  line-height: 1.65;
  color: var(--muted-color);
  margin-bottom: 16px;
}
.rhema-coach-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.rhema-coach-skip {
  font-size: 0.82rem;
  color: var(--muted-color);
  background: none;
  border: none;
  padding: 6px 0;
  cursor: pointer;
}
.rhema-coach-next {
  display: flex;
  align-items: center;
  gap: 5px;
  background: var(--secondary-color);
  color: var(--btn-text-color, #fff);
  border: none;
  border-radius: 50px;
  padding: 9px 18px;
  font-size: 0.87rem;
  font-weight: 700;
  cursor: pointer;
}
.rhema-coach-next .material-symbols-outlined { font-size: 1rem; }
.rhema-coach-back {
  background: none; border: 1px solid var(--border-color);
  border-radius: 10px; padding: 10px 16px; font-size: 0.9rem; font-weight: 600;
  color: var(--font-color); cursor: pointer; transition: background 0.15s;
}
.rhema-coach-back:active { background: var(--border-color); }

.app-coach-overlay {
  position: fixed;
  inset: 0;
  z-index: 30000;
  pointer-events: all;
}
.app-coach-overlay.hidden { display: none; }
.app-coach-overlay.coach-full-blur::before {
  content: "";
  position: fixed;
  inset: 0;
  background: rgba(8, 14, 26, 0.36);
  backdrop-filter: blur(10px) saturate(1.04);
  -webkit-backdrop-filter: blur(10px) saturate(1.04);
  animation: coachBlurIn 0.28s ease both;
}
.app-coach-spotlight {
  position: fixed;
  border-radius: 18px;
  box-shadow: 0 0 0 100vmax rgba(8, 14, 26, 0.68);
  outline: 2px solid color-mix(in srgb, var(--secondary-color) 72%, white);
  outline-offset: 3px;
  transition: top 0.34s cubic-bezier(.4,0,.2,1),
              left 0.34s cubic-bezier(.4,0,.2,1),
              width 0.34s cubic-bezier(.4,0,.2,1),
              height 0.34s cubic-bezier(.4,0,.2,1),
              border-radius 0.34s cubic-bezier(.4,0,.2,1);
  pointer-events: none;
  animation: coachPulse 1.9s ease-in-out infinite;
}
.app-coach-spotlight.no-target {
  opacity: 0;
  animation: none;
}
.app-coach-card {
  position: fixed;
  width: min(360px, calc(100vw - 32px));
  max-height: min(62svh, 440px);
  overflow-y: auto;
  padding: 20px 20px 16px;
  border-radius: 22px;
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--secondary-color) 9%, var(--card-color)), var(--card-color) 52%),
    var(--card-color);
  border: 1px solid color-mix(in srgb, var(--secondary-color) 28%, var(--border-color));
  box-shadow: 0 24px 70px rgba(0,0,0,0.34);
  overscroll-behavior: contain;
  transition: top 0.28s cubic-bezier(.4,0,.2,1),
              left 0.28s cubic-bezier(.4,0,.2,1),
              transform 0.28s cubic-bezier(.4,0,.2,1);
  pointer-events: all;
}
.app-coach-card::before {
  content: "";
  display: block;
  width: 42px;
  height: 5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 52%, transparent);
  margin-bottom: 12px;
}
.app-coach-step-label {
  font-size: 0.66rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--secondary-color);
  margin-bottom: 6px;
}
.app-coach-title {
  font-size: 1.08rem;
  font-weight: 800;
  color: var(--font-color);
  line-height: 1.25;
  margin-bottom: 8px;
}
.app-coach-body {
  font-size: 0.88rem;
  line-height: 1.68;
  color: var(--muted-color);
  margin-bottom: 18px;
}
.app-coach-body p {
  margin: 0 0 12px;
}
.coach-longpress-demo {
  position: relative;
  min-height: 142px;
  margin-top: 10px;
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 28%, var(--border-color));
  background:
    radial-gradient(circle at 30% 24%, color-mix(in srgb, var(--secondary-color) 16%, transparent), transparent 36%),
    color-mix(in srgb, var(--card-color) 88%, var(--secondary-color));
}
.coach-phone-line {
  position: absolute;
  top: 18px;
  left: 16px;
  right: 16px;
  padding: 13px 14px;
  border-radius: 14px;
  color: var(--font-color);
  background: color-mix(in srgb, var(--card-color) 92%, white);
  box-shadow: 0 10px 24px rgba(0,0,0,0.1);
}
.coach-phone-line strong {
  color: var(--secondary-color);
}
.coach-finger {
  position: absolute;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  left: 50%;
  top: 42px;
  background: color-mix(in srgb, var(--secondary-color) 85%, white);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--secondary-color) 36%, transparent);
  animation: coachLongPress 2.2s ease-in-out infinite;
}
.coach-finger::after {
  content: "";
  position: absolute;
  width: 12px;
  height: 36px;
  left: 10px;
  top: 22px;
  border-radius: 999px;
  background: inherit;
}
.coach-mini-wheel-demo {
  position: absolute;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%) scale(0.92);
  display: grid;
  grid-template-columns: repeat(2, auto);
  gap: 6px;
  opacity: 0;
  animation: coachWheelAppear 2.2s ease-in-out infinite;
}
.coach-mini-wheel-demo span {
  font-size: 0.68rem;
  font-weight: 800;
  color: var(--secondary-color);
  border-radius: 999px;
  padding: 5px 8px;
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
}
.app-coach-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.app-coach-back {
  border: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--card-color) 86%, var(--secondary-color));
  color: var(--font-color);
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 0.88rem;
  font-weight: 700;
}
.app-coach-next {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: none;
  border-radius: 999px;
  padding: 11px 18px;
  background: var(--secondary-color);
  color: var(--btn-text-color, #fff);
  font-size: 0.9rem;
  font-weight: 800;
  box-shadow: 0 12px 26px color-mix(in srgb, var(--secondary-color) 26%, transparent);
}
.app-coach-next .material-symbols-outlined { font-size: 1rem; }

@keyframes coachPulse {
  0%, 100% { outline-offset: 3px; }
  50% { outline-offset: 7px; }
}

@keyframes coachBlurIn {
  from { opacity: 0; backdrop-filter: blur(0); -webkit-backdrop-filter: blur(0); }
  to { opacity: 1; backdrop-filter: blur(10px) saturate(1.04); -webkit-backdrop-filter: blur(10px) saturate(1.04); }
}

@keyframes coachLongPress {
  0%, 100% { transform: translate(-50%, 0) scale(0.82); opacity: 0; box-shadow: 0 0 0 0 color-mix(in srgb, var(--secondary-color) 34%, transparent); }
  18% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  48% { opacity: 1; transform: translate(-50%, 0) scale(0.9); box-shadow: 0 0 0 22px color-mix(in srgb, var(--secondary-color) 0%, transparent); }
  68% { opacity: 0; transform: translate(-50%, 14px) scale(0.85); }
}

@keyframes coachWheelAppear {
  0%, 44% { opacity: 0; transform: translateX(-50%) translateY(10px) scale(0.86); }
  56%, 82% { opacity: 1; transform: translateX(-50%) translateY(0) scale(1); }
  100% { opacity: 0; transform: translateX(-50%) translateY(8px) scale(0.9); }
}

.coach-replay-card {
  max-width: 520px;
}
.coach-replay-card p {
  color: var(--muted-color);
  line-height: 1.55;
}
.coach-replay-list {
  display: grid;
  gap: 10px;
  margin-top: 16px;
}
.coach-replay-list button {
  display: grid;
  grid-template-columns: 40px 1fr;
  gap: 3px 12px;
  align-items: center;
  width: 100%;
  text-align: left;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 22%, var(--border-color));
  border-radius: 14px;
  padding: 13px;
  background: color-mix(in srgb, var(--secondary-color) 7%, var(--card-color));
  color: var(--font-color);
}
.coach-replay-list .material-symbols-outlined {
  grid-row: span 2;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
}
.coach-replay-list strong {
  font-size: 0.95rem;
}
.coach-replay-list small {
  color: var(--muted-color);
  line-height: 1.35;
}

.rhema-nerd-card {
  max-width: 640px;
  max-height: min(84svh, 760px);
  overflow-y: auto;
  padding: 24px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 24%, var(--border-color));
  background:
    radial-gradient(circle at 86% 8%, color-mix(in srgb, var(--secondary-color) 12%, transparent), transparent 28%),
    linear-gradient(155deg, color-mix(in srgb, var(--secondary-color) 7%, var(--card-color)), var(--card-color) 48%),
    var(--card-color);
}
.nerd-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border-radius: 999px;
  padding: 7px 11px;
  margin-bottom: 12px;
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
  color: var(--secondary-color);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.nerd-kicker .material-symbols-outlined {
  font-size: 1rem !important;
}
.rhema-nerd-card h2 {
  margin: 0 0 8px;
  font-size: 1.55rem;
  letter-spacing: 0;
}
.rhema-nerd-card h3 {
  margin: 0 0 8px;
  color: var(--font-color);
  font-size: 1rem;
}
.rhema-nerd-card p,
.rhema-nerd-card li {
  color: var(--muted-color);
  line-height: 1.58;
  font-size: 0.92rem;
}
.nerd-lead {
  margin: 0 0 16px;
}
.nerd-section {
  border: 1px solid color-mix(in srgb, var(--secondary-color) 16%, var(--border-color));
  border-radius: 18px;
  padding: 15px;
  margin-top: 12px;
  background: color-mix(in srgb, var(--card-color) 92%, var(--secondary-color));
}
.nerd-section p {
  margin: 0;
}
.nerd-section p + p {
  margin-top: 10px;
}
.nerd-hero-note {
  border-color: color-mix(in srgb, var(--secondary-color) 34%, var(--border-color));
  box-shadow: 0 14px 36px color-mix(in srgb, var(--secondary-color) 10%, transparent);
}
.nerd-hero-note strong {
  display: block;
  margin-bottom: 7px;
  color: var(--secondary-color);
  font-size: 1rem;
}
.nerd-source-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}
.nerd-source-item {
  display: grid;
  gap: 7px;
  align-content: start;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 14%, var(--border-color));
  border-radius: 16px;
  padding: 14px;
  background: color-mix(in srgb, var(--card-color) 96%, var(--secondary-color));
}
.nerd-source-item .material-symbols-outlined {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 13px;
  color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
  font-size: 1.25rem !important;
}
.nerd-source-item strong {
  color: var(--font-color);
  font-size: 0.94rem;
}
.nerd-source-item p {
  margin: 0;
  font-size: 0.84rem;
}
.nerd-flow ol {
  margin: 0;
  padding-left: 20px;
}
.nerd-flow li + li {
  margin-top: 7px;
}
.nerd-honesty {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--secondary-color) 10%, var(--card-color)), var(--card-color));
}

@media (max-width: 420px) {
  .app-coach-card,
  .rhema-coach-card {
    width: calc(100vw - 24px);
    max-height: 58svh;
    padding: 18px 18px 15px;
  }
  .rhema-nerd-card {
    width: calc(100vw - 24px);
    max-height: 86svh;
    padding: 21px 18px;
  }
  .nerd-source-grid {
    grid-template-columns: 1fr;
  }
}
/* Shake animation for placeholder buttons */
@keyframes rw-shake {
  0%, 100% { filter: brightness(1); }
  25%       { filter: brightness(1.4); }
  75%       { filter: brightness(0.8); }
}
.rhema-wheel-item.shake { animation: rw-shake 0.4s ease; }
.rhema-wheel-item.disabled.shake { animation: rw-shake 0.4s ease; }

/* ── POS Highlight toolbar ── */
.rhema-highlight-bar {
  display: flex;
  gap: 6px;
  padding: 6px 12px 8px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  background: var(--primary-light);
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  overscroll-behavior: contain;
}
.rhema-highlight-bar::-webkit-scrollbar { display: none; }
.rhema-highlight-bar.hidden { display: none; }

.rhema-hl-pill {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px 4px 7px;
  border-radius: 20px;
  border: 1.5px solid var(--border-color);
  background: var(--card-color);
  color: var(--secondary-color);
  font-size: 0.72rem;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, opacity 0.15s;
  flex-shrink: 0;
}
.rhema-hl-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
/* Present in verse but not selected — subtle highlight to show availability */
.rhema-hl-pill.hl-present {
  border-color: color-mix(in srgb, var(--border-color) 60%, currentColor);
}
/* Selected AND has matches in this verse — fully active */
.rhema-hl-pill.hl-active {
  border-color: transparent;
  color: #fff;
}
/* V = orange */
.rhema-hl-pill[data-cat="V"].hl-active    { background: rgba(251,146,60,0.85); }
/* N = blue */
.rhema-hl-pill[data-cat="N"].hl-active    { background: rgba(96,165,250,0.85); }
/* ADJ = green */
.rhema-hl-pill[data-cat="ADJ"].hl-active  { background: rgba(74,222,128,0.75); color: #14532d; }
/* T = purple */
.rhema-hl-pill[data-cat="T"].hl-active    { background: rgba(167,139,250,0.85); }
/* PRON = pink */
.rhema-hl-pill[data-cat="PRON"].hl-active { background: rgba(251,113,133,0.85); }
/* PREP = teal */
.rhema-hl-pill[data-cat="PREP"].hl-active { background: rgba(45,212,191,0.8); color: #134e4a; }
/* CONJ = amber */
.rhema-hl-pill[data-cat="CONJ"].hl-active { background: rgba(250,204,21,0.8); color: #78350f; }
.rhema-hl-pill[data-cat="ADV"].hl-active  { background: rgba(253,186,116,0.85); color: #7c2d12; }
.rhema-hl-pill[data-cat="NEG"].hl-active  { background: rgba(248,113,113,0.86); }
.rhema-hl-pill[data-cat="PART"].hl-active { background: rgba(148,163,184,0.9); color: #111827; }

/* Selected but no matches in this verse — dimmed */
.rhema-hl-pill.hl-dimmed {
  opacity: 0.45;
  border-style: dashed;
}

/* Shake animation when tapping a category with no matches */
@keyframes rhema-hl-shake {
  0%,100% { transform: translateX(0); }
  20%      { transform: translateX(-4px); }
  40%      { transform: translateX(4px); }
  60%      { transform: translateX(-3px); }
  80%      { transform: translateX(3px); }
}
.rhema-hl-pill.shake { animation: rhema-hl-shake 0.4s ease; }

/* Clause Compass: English discourse / argument flow */
.rhema-flow-bar {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px 11px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--secondary-color) 88%, #10273f), #18324a 58%, #284236);
  color: #f7fbff;
  border-bottom: 1px solid rgba(255,255,255,0.16);
  box-shadow: 0 8px 22px rgba(17, 31, 47, 0.18);
  flex-shrink: 0;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
}
.rhema-flow-bar.hidden { display: none; }
.rhema-flow-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.rhema-flow-head strong {
  display: block;
  font-size: 0.82rem;
  line-height: 1.1;
  letter-spacing: 0;
}
.rhema-flow-head span {
  display: block;
  margin-top: 2px;
  font-size: 0.68rem;
  color: rgba(247,251,255,0.76);
  line-height: 1.2;
}
.rhema-flow-head button {
  border: 1px solid rgba(255,255,255,0.24);
  background: rgba(255,255,255,0.12);
  color: #fff;
  border-radius: 999px;
  padding: 5px 10px;
  font-size: 0.68rem;
  font-weight: 800;
  cursor: pointer;
  flex-shrink: 0;
}
.rhema-flow-chips {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  overscroll-behavior: contain;
}
.rhema-flow-chips::-webkit-scrollbar { display: none; }
.rhema-flow-chip {
  border: 1px solid rgba(255,255,255,0.22);
  background: rgba(255,255,255,0.11);
  color: rgba(247,251,255,0.88);
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 0.69rem;
  font-weight: 800;
  white-space: nowrap;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease, transform 0.15s ease;
}
.rhema-flow-chip.flow-present {
  border-color: rgba(255,255,255,0.46);
}
.rhema-flow-chip.flow-active {
  color: #102033;
  border-color: transparent;
  transform: translateY(-1px);
}
.rhema-flow-chip.flow-dimmed {
  opacity: 0.42;
  border-style: dashed;
}
.rhema-flow-chip[data-flow-cat="COMMAND"].flow-active { background: #ffb86b; }
.rhema-flow-chip[data-flow-cat="REASON"].flow-active { background: #8dd7ff; }
.rhema-flow-chip[data-flow-cat="CONCLUSION"].flow-active { background: #c7f06d; }
.rhema-flow-chip[data-flow-cat="CONTRAST"].flow-active { background: #ff91ac; }
.rhema-flow-chip[data-flow-cat="PURPOSE"].flow-active { background: #c3a3ff; }
.rhema-flow-chip[data-flow-cat="CONDITION"].flow-active { background: #7ee3c5; }
.rhema-flow-chip[data-flow-cat="EMPHASIS"].flow-active { background: #ffe27a; }
.rhema-flow-mark {
  position: relative;
  display: inline;
  padding: 0 2px;
  border-radius: 5px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
  color: inherit;
}
.rhema-flow-mark.flow-high {
  box-shadow: inset 0 -0.54em 0 rgba(255,255,255,0.52);
}
.rhema-flow-mark.flow-medium {
  box-shadow: inset 0 -0.48em 0 rgba(255,255,255,0.36);
}
.rhema-flow-mark.flow-low {
  box-shadow: inset 0 -0.36em 0 rgba(255,255,255,0.26);
  border-bottom: 1px dashed currentColor;
}
.rhema-flow-mark.flow-command { background: rgba(255,184,107,0.34); text-decoration-color: rgba(196,93,0,0.5); }
.rhema-flow-mark.flow-reason { background: rgba(141,215,255,0.34); }
.rhema-flow-mark.flow-conclusion { background: rgba(199,240,109,0.34); }
.rhema-flow-mark.flow-contrast { background: rgba(255,145,172,0.34); }
.rhema-flow-mark.flow-purpose { background: rgba(195,163,255,0.34); }
.rhema-flow-mark.flow-condition { background: rgba(126,227,197,0.34); }
.rhema-flow-mark.flow-emphasis { background: rgba(255,226,122,0.38); }
.rhema-flow-chip.shake { animation: rhema-hl-shake 0.4s ease; }

/* ── Grammar example modal ── */
.rhema-grammar-modal {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.45);
  z-index: 1060;
  display: flex;
  align-items: flex-end;
  padding: 0 0 0px;
}
.rhema-grammar-modal.hidden { display: none; }
.rhema-grammar-card {
  background: var(--card-color);
  border-radius: 24px 24px 0 0;
  padding: 24px 20px calc(0px + 20px);
  width: 100%;
  position: relative;
  max-height: 70vh;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.rhema-grammar-close {
  position: absolute;
  top: 14px;
  right: 16px;
  background: color-mix(in srgb, var(--border-color) 50%, transparent);
  border: none;
  border-radius: 50%;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  cursor: pointer;
  color: var(--font-color);
  font-weight: 700;
}
.rhema-grammar-title {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--font-color);
  margin-bottom: 14px;
  padding-right: 36px;
}
.rhema-grammar-example-sentence {
  font-size: 1rem;
  font-weight: 700;
  font-style: italic;
  color: var(--secondary-color);
  margin-bottom: 10px;
  padding: 10px 14px;
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
  border-radius: 10px;
}
.rhema-grammar-example-body {
  font-size: 0.88rem;
  line-height: 1.65;
  color: var(--font-color);
  opacity: 0.9;
}

/* ── Form ending hint ── */
.rhema-inflected-gloss {
  font-size: 1rem;
  font-weight: 700;
  font-style: italic;
  color: var(--font-color);
  padding: 0 0 12px;
}
.rhema-parse-quick {
  margin: 0 0 10px;
  padding: 12px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--secondary-color) 10%, var(--card-color));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 18%, transparent);
  box-shadow: 0 8px 18px rgba(0,0,0,0.04);
}
.rhema-parse-quick.hidden { display: none; }
.rhema-form-hint {
  font-size: 0.85rem;
  color: var(--muted-color);
  padding: 10px 0 2px;
}
.rhema-form-hint strong {
  color: var(--secondary-color);
  font-weight: 900;
}
.rhema-form-hint small {
  display: block;
  margin-top: 6px;
  line-height: 1.35;
  opacity: 0.82;
}
/* Tappable value — Tense/Voice/Mood values that open the grammar example modal */
.rhema-value-link {
  background: none;
  border: none;
  padding: 0;
  text-align: left;
  cursor: pointer;
  color: var(--secondary-color);
  text-decoration: underline;
  text-decoration-style: dotted;
  text-decoration-color: color-mix(in srgb, var(--secondary-color) 55%, transparent);
  text-underline-offset: 3px;
}

/* ── Verse picker pills ── */
.rhema-picker {
  display: flex;
  gap: 8px;
  padding: 10px 14px 12px;
  background: transparent;
  border-bottom: none;
  flex-shrink: 0;
  touch-action: none; /* swipes here must not scroll ancestors */
}

.rhema-pill {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
  min-width: 0;
  background: linear-gradient(145deg, rgba(255,255,255,0.95), color-mix(in srgb, var(--secondary-color) 4%, rgba(255,255,255,0.88)));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 15%, rgba(255,255,255,0.5));
  border-radius: 20px;
  padding: 8px 12px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--font-color);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: all 0.12s;
  white-space: nowrap;
  overflow: hidden;
  box-shadow: 0 2px 6px color-mix(in srgb, var(--secondary-color) 10%, rgba(0,0,0,0.07)), 0 1px 2px rgba(0,0,0,0.05), inset 0 1px 1px rgba(255,255,255,0.9);
}
.rhema-pill:first-child { flex: 2.2; }
.rhema-pill:nth-child(2) {
  flex: 0 0 clamp(78px, 20vw, 102px);
  min-width: 78px;
}
.rhema-pill:active {
  background: color-mix(in srgb, var(--secondary-color) 12%, rgba(255,255,255,0.9));
  box-shadow: 0 1px 3px color-mix(in srgb, var(--secondary-color) 10%, rgba(0,0,0,0.06));
  transform: scale(0.98);
}
.rhema-pill-icon { font-size: 1rem; color: var(--secondary-color); flex-shrink: 0; }
.rhema-pill-chev { font-size: 1rem; color: var(--muted-color); flex-shrink: 0; margin-left: auto; }
.rhema-pill > span:not(.rhema-pill-icon):not(.rhema-pill-chev) {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rhema-pill.hidden { display: none; }
.rhema-chapter-mode-pill { flex: 0 0 auto; padding: 0 12px; color: var(--muted-color); border-radius: 20px; }
.rhema-chapter-mode-pill.active {
  background: linear-gradient(145deg, color-mix(in srgb, var(--secondary-color) 20%, rgba(255,255,255,0.88)), color-mix(in srgb, var(--secondary-color) 12%, rgba(255,255,255,0.82)));
  color: var(--secondary-color);
  border-color: color-mix(in srgb, var(--secondary-color) 25%, rgba(255,255,255,0.5));
}
.rhema-translation-pill {
  min-width: 58px;
  justify-content: center;
  font-weight: 800;
  line-height: 1;
  overflow: hidden;
}
.rhema-translation-pill.active {
  background: var(--secondary-color);
  color: var(--btn-text-color);
  border-color: var(--secondary-color);
  box-shadow: inset 0 0 0 999px color-mix(in srgb, var(--secondary-color) 100%, transparent);
}

/* ── Full chapter rendering ── */
.rhema-verse-display.chapter-mode {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 8px 0 20px;
}
.rhema-chapter-block {
  padding: 10px 0 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--border-color) 55%, transparent);
}
.rhema-chapter-block:last-child { border-bottom: none; }
.rhema-chapter-block-target {
  background: color-mix(in srgb, var(--secondary-color) 8%, transparent);
  border-radius: 6px;
  padding: 8px 6px 12px;
}
.rhema-chapter-verse-label {
  font-size: 0.62rem;
  font-weight: 800;
  color: var(--muted-color);
  letter-spacing: 0.06em;
  margin-bottom: 6px;
  user-select: none;
}
.rhema-chapter-word-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  align-content: start;
  column-gap: 0;
  row-gap: 20px;
}
.rhema-chapter-word-grid .rhema-word:nth-child(4n+1) { border-left: none; }
.rhema-chapter-word-grid.greek-only {
  display: block;
  line-height: 2.6;
  font-size: 1.3rem;
  letter-spacing: 0.03em;
  padding: 4px 20px 0;
}
.rhema-chapter-english {
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--font-color);
  opacity: 0.85;
  padding: 0 4px;
}

.rhema-no-english {
  font-style: italic;
  opacity: 0.55;
  font-size: 0.85em;
}

/* ── Chapter mode toast ── */
.rhema-chapter-toast {
  position: absolute;
  bottom: 90px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0,0,0,0.72);
  color: #fff;
  padding: 7px 18px;
  border-radius: 20px;
  font-size: 0.82rem;
  font-weight: 600;
  z-index: 1060;
  pointer-events: none;
  white-space: nowrap;
}
.rhema-chapter-toast:not(.hidden) {
  animation: rhema-toast-fade 1.8s ease forwards;
}
.rhema-chapter-toast.hidden { display: none; }
@keyframes rhema-toast-fade {
  0%   { opacity: 1; }
  55%  { opacity: 1; }
  100% { opacity: 0; }
}

/* ── Picker overlay backdrop ── */
.rhema-picker-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.45);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  z-index: 1050;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.rhema-picker-overlay.hidden { display: none; }
/* Cross-ref book picker must be viewport-fixed (nested inside xref page, not body) */
#rxBookPickerOverlay { position: fixed; z-index: 9050; }

/* ── Picker sheet (slides from bottom) ── */
.rhema-picker-sheet {
  background: var(--card-color);
  border-radius: 22px 22px 0 0;
  border-top: 1.5px solid var(--border-color);
  padding-bottom: 0px;
  max-height: 80svh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.rhema-picker-sheet--grid {
  max-height: 62svh;
}

.rhema-picker-handle {
  width: 36px;
  height: 4px;
  background: color-mix(in srgb, var(--muted-color) 35%, transparent);
  border-radius: 2px;
  margin: 12px auto 0;
  flex-shrink: 0;
}
.rhema-picker-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px 10px;
  flex-shrink: 0;
}
.rhema-picker-title {
  flex: 1;
  min-width: 0;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--font-color);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rhema-picker-x {
  background: none;
  border: none;
  font-size: 1.1rem;
  color: var(--muted-color);
  cursor: pointer;
  padding: 2px 6px;
  -webkit-tap-highlight-color: transparent;
}

/* ── Book search bar ── */
.rhema-picker-search-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 16px 10px;
  background: var(--primary-color);
  border: 1.5px solid var(--border-color);
  border-radius: 12px;
  padding: 8px 12px;
  flex-shrink: 0;
}
.rhema-picker-search-icon { font-size: 1.1rem; color: var(--muted-color); }
.rhema-picker-search-input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  font-size: 0.9rem;
  color: var(--font-color);
}
.rhema-picker-search-input::placeholder { color: var(--muted-color); opacity: 0.7; }

/* ── Book list ── */
.rhema-book-list {
  flex: 1;
  overflow-y: auto;
  touch-action: pan-y;
  overscroll-behavior: none;
  padding-bottom: calc(28px + env(safe-area-inset-bottom, 0px));
}

.rhema-picker-back {
  width: 34px;
  height: 34px;
  border: 1px solid color-mix(in srgb, var(--border-color) 65%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, var(--card-color) 86%, transparent);
  color: var(--font-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  margin-right: 8px;
  cursor: pointer;
}
.rhema-picker-back.hidden { display: none; }
.rhema-picker-back .material-symbols-outlined {
  font-size: 1.15rem !important;
}

.rhema-book-chapter-grid {
  display: grid;
  /* auto-fill (not auto-fit) keeps empty tracks, so chapter boxes stay the
     same size whether a book has 1 chapter or 150 */
  grid-template-columns: repeat(auto-fill, minmax(54px, 1fr));
  gap: 9px;
  padding: 12px 14px 18px;
}

.rhema-book-chapter-grid .rhema-num-cell {
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.rhema-book-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 20px;
  cursor: pointer;
  border-bottom: 1px solid color-mix(in srgb, var(--border-color) 40%, transparent);
  transition: background 0.1s;
  -webkit-tap-highlight-color: transparent;
}
.rhema-book-row:active { background: var(--primary-color); }
.rhema-book-row.selected {
  background: color-mix(in srgb, var(--secondary-color) 9%, transparent);
}
.rhema-book-icon { font-size: 1.1rem; color: var(--muted-color); flex-shrink: 0; }
.rhema-book-row.selected .rhema-book-icon { color: var(--secondary-color); }
.rhema-book-name { flex: 1; font-size: 0.95rem; font-weight: 600; color: var(--font-color); }
.rhema-book-row.selected .rhema-book-name { color: var(--secondary-color); }
.rhema-book-check {
  font-size: 1.1rem;
  color: var(--secondary-color);
  visibility: hidden;
  flex-shrink: 0;
}
.rhema-book-row.selected .rhema-book-check { visibility: visible; }
.rhema-testament-sep {
  padding: 10px 20px 4px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted-color);
  border-bottom: 1px solid color-mix(in srgb, var(--border-color) 50%, transparent);
}

/* ── Chapter / Verse number grid ── */
.rhema-num-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  padding: 8px 16px calc(0px + 16px);
  overflow-y: auto;
  touch-action: pan-y;
  overscroll-behavior: none;
}
.rhema-num-cell {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--font-color);
  background: var(--primary-color);
  border: 1.5px solid var(--border-color);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.1s;
}
.rhema-num-cell:active { opacity: 0.65; }
.rhema-num-cell.selected {
  background: var(--secondary-color);
  color: var(--btn-text-color);
  border-color: var(--secondary-color);
}

/* ── Verse display ── */
/* ── Scrollable body: flex column so content-area scrolls and nav pins at bottom ── */
/* ── Reader shell ──
   The scroll body fills the whole area below the header; the picker chrome and
   verse nav OVERLAY it (position:absolute) and hide with transform/opacity only.
   The scroll container therefore never changes size when the bars hide/show —
   which is what used to make the page jump around mid-scroll. */
.rhema-reader {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.rhema-top-chrome {
  position: absolute;
  top: 0; left: 0; right: 0;
  z-index: 40;
  background: color-mix(in srgb, var(--primary-light) 94%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transform: translateY(0);
  opacity: 1;
  transition: transform 0.28s cubic-bezier(.2,.82,.18,1), opacity 0.2s ease;
  will-change: transform;
}
.rhema-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: clip; /* clip not hidden — hidden creates an X scroll container that swallows
                       horizontal touch gestures before they reach .rsx-diagram */
  touch-action: pan-x pan-y;
  overscroll-behavior: none;
  width: 100%;
  user-select: none;
  -webkit-user-select: none;
  /* Constant clearance for the overlaid bars — set from their measured heights by
     _initRhemaChromeMetrics(). Must NOT change when the bars hide (transform only),
     so the scroll geometry stays rock-solid during the show/hide animation. */
  padding-top: var(--rhema-chrome-top, 62px);
  padding-bottom: calc(var(--rhema-chrome-bottom, 0px) + 8px);
  scroll-padding-top: calc(var(--rhema-chrome-top, 62px) + 8px);
}
.rhema-body.rhema-swipe-left .rhema-content-area,
.rhema-body.rhema-swipe-right .rhema-content-area {
  animation: rhemaChapterNudge 0.34s ease;
}
.rhema-body.rhema-swipe-left .rhema-content-area { --rhema-swipe-x: -18px; }
.rhema-body.rhema-swipe-right .rhema-content-area { --rhema-swipe-x: 18px; }
@keyframes rhemaChapterNudge {
  0% { transform: translateX(var(--rhema-swipe-x)); opacity: 0.72; }
  100% { transform: translateX(0); opacity: 1; }
}

.rhema-content-area {
  min-height: 100%;
}

.rhema-bottom-wave {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 150px;
  z-index: 36;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}
.rhema-bottom-wave.show { opacity: 1; }
/* The body of water: a swell that peaks under the finger (--wave-x) and rises
   with how far you pull past the bottom (--wave-lift). The JS rAF loop updates
   both each frame, so the crest glides with the finger and holds while held. */
.rhema-bottom-wave::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: calc(34px + var(--wave-lift, 0px));
  background:
    radial-gradient(150px calc(30px + var(--wave-lift, 0px) * 1.5) at var(--wave-x, 50%) 100%,
      color-mix(in srgb, var(--secondary-color) 42%, transparent) 0%,
      color-mix(in srgb, var(--secondary-color) 26%, transparent) 44%,
      transparent 76%),
    linear-gradient(to top,
      color-mix(in srgb, var(--secondary-color) 24%, transparent),
      transparent 90%);
}
/* A brighter foam cap riding the top of the crest, also tracking the finger. */
.rhema-bottom-wave::after {
  content: "";
  position: absolute;
  left: calc(var(--wave-x, 50%) - 70px);
  bottom: calc(20px + var(--wave-lift, 0px) * 0.92);
  width: 140px;
  height: 20px;
  background: radial-gradient(70px 20px at 50% 100%,
    color-mix(in srgb, var(--secondary-color) 58%, #ffffff) 0%,
    transparent 72%);
  opacity: 0.7;
}

.rhema-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 160px;
  text-align: center;
  color: var(--muted-color);
  font-size: 0.9rem;
  pointer-events: none;
}

.rhema-verse-display {
  width: 100%;
  padding: 16px 0 20px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  align-content: start;
  column-gap: 0;
  row-gap: 20px;
}
.rhema-layer-label {
  grid-column: 1 / -1;
  justify-self: center;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--secondary-color);
  opacity: 0.75;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: -4px;
}
.rhema-verse-display.rhema-hebrew-layer,
.rhema-chapter-word-grid.rhema-hebrew-layer {
  direction: rtl;
  unicode-bidi: isolate;
}
.rhema-verse-display.rhema-hebrew-layer .rhema-layer-label,
.rhema-chapter-word-grid.rhema-hebrew-layer .rhema-layer-label {
  direction: ltr;
}
.rhema-hebrew-text {
  direction: rtl;
  font-family: "SBL Hebrew", "Ezra SIL", "Noto Sans Hebrew", serif;
  font-size: 1.22rem;
  letter-spacing: 0;
}
.rhema-hebrew-simple {
  border: 1px solid color-mix(in srgb, var(--secondary-color) 28%, var(--border-color));
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 12px;
  color: var(--font-color);
  line-height: 1.45;
}
.rhema-hebrew-simple strong,
.rhema-hebrew-root {
  font-family: "SBL Hebrew", "Ezra SIL", "Noto Sans Hebrew", serif;
  font-size: 1.2rem;
  direction: rtl;
  unicode-bidi: isolate;
}
.rhema-hebrew-simple span {
  display: block;
  margin-top: 6px;
  color: var(--muted-color);
  font-size: 0.82rem;
}
/* Greek-only mode: flowing inline text */
.rhema-verse-display.greek-only {
  display: block;
  padding: 24px 20px 20px;
  line-height: 2.6;
  font-size: 1.3rem;
  letter-spacing: 0.03em;
  color: var(--font-color);
}

.rhema-word {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  cursor: pointer;
  border-left: 1px solid color-mix(in srgb, var(--border-color) 65%, transparent);
  padding: 6px 6px 6px;
  border-radius: 0;
  transition: background 0.12s;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  text-align: center;
  min-width: 0;
}
/* First word in each row of 4 gets no left border */
.rhema-word:nth-child(4n+1) { border-left: none; }
.rhema-word:active,
.rhema-word.selected {
  background: color-mix(in srgb, var(--secondary-color) 15%, transparent);
}
.rhema-word.xref {
  background: color-mix(in srgb, var(--accent-color) 22%, transparent);
  animation: xrefPulse 0.55s ease forwards;
}
.rhema-greek-text {
  font-size: 1.15rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  line-height: 1.3;
  color: var(--font-color);
  word-break: break-word;
}
.rhema-gloss {
  font-size: 0.68rem;
  font-weight: 400;
  color: var(--muted-color);
  opacity: 0.75;
  margin-top: 4px;
  letter-spacing: 0.01em;
  /* Show the whole Rhema Lexicon gloss — wrap instead of truncating */
  white-space: normal;
  overflow-wrap: break-word;
  max-width: 100%;
  padding: 0 2px;
  text-align: center;
  line-height: 1.25;
}
/* Greek-only overrides */
.greek-only .rhema-word {
  display: inline;
  border-left: none;
  padding: 2px 2px;
  border-radius: 6px;
}
.greek-only .rhema-gloss { display: none; }
.greek-only .rhema-greek-text {
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  line-height: inherit;
  color: inherit;
  word-break: normal;
}

.rhema-english-display {
  width: 100%;
  padding: 24px 20px 20px;
  font-size: 1rem;
  line-height: 1.9;
  font-style: italic;
  color: var(--muted-color);
}

/* ── English chapter reading mode (Bible-app style) ── */
.rhema-english-display.rhema-english-reading {
  padding: 18px 18px 30px;
  font-style: normal;
  font-size: 1.06rem;
  line-height: 1.8;
  color: var(--font-color);
}
.rhema-english-chapter-title {
  margin: 4px 2px 16px;
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--font-color);
}
.rhema-english-reading .rhema-chapter-block {
  padding: 4px 8px;
  border-bottom: none;
  border-radius: 10px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.rhema-english-reading .rhema-chapter-block.rhema-chapter-block-target {
  background: color-mix(in srgb, var(--secondary-color) 9%, transparent);
}
.rhema-english-vnum {
  margin-right: 6px;
  font-size: 0.62em;
  font-weight: 800;
  color: var(--secondary-color);
  user-select: none;
}
/* Single-verse English view: same reading style as the chapter, but the
   block isn't a tappable verse selector. */
.rhema-english-single .rhema-chapter-block {
  cursor: default;
  padding: 0;
}

/* Copyright / attribution notice at the very bottom of every chapter,
   YouVersion-style — quiet, small, and set off from the last verse. */
.rhema-reader-copyright {
  margin: 22px 2px 6px;
  padding-top: 14px;
  border-top: 1px solid color-mix(in srgb, var(--font-color) 12%, transparent);
  font-size: 0.72rem;
  line-height: 1.5;
  font-weight: 500;
  color: color-mix(in srgb, var(--font-color) 55%, transparent);
  text-align: left;
}

.rhema-english-pos-highlight {
  border-radius: 4px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
  color: color-mix(in srgb, var(--font-color) 82%, currentColor);
  font-weight: 650;
  padding: 0 2px;
}

.rhema-reader-note-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 30px;
  height: 20px;
  margin-left: 6px;
  padding: 0 6px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 30%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
  color: var(--secondary-color);
  font: inherit;
  font-size: 0.68rem;
  font-weight: 800;
  vertical-align: text-top;
}
.rhema-reader-note-btn .material-symbols-outlined { font-size: 13px; }
.rhema-reader-map-btn {
  border-color: color-mix(in srgb, #2f9e6f 45%, transparent);
  background: color-mix(in srgb, #2f9e6f 14%, transparent);
  color: #1f7d54;
}
body.dark .rhema-reader-map-btn { color: #6fd6a6; }
.rhema-reader-place-btn {
  border-color: color-mix(in srgb, #c0563b 45%, transparent);
  background: color-mix(in srgb, #c0563b 14%, transparent);
  color: #b14228;
}
body.dark .rhema-reader-place-btn { color: #f0a58e; }

/* Atlas peek — quick place pin popup from a verse (reuses journey-peek shell). */
.atlas-peek-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 2px 0 12px;
}
.atlas-peek-chips button {
  border: 1px solid var(--border-color);
  border-radius: 999px;
  background: var(--card-color);
  color: var(--muted-color);
  padding: 6px 12px;
  font-weight: 800;
  font-size: 0.82rem;
  cursor: pointer;
}
.atlas-peek-chips button.active {
  border-color: var(--secondary-color);
  background: var(--secondary-color);
  color: var(--btn-text-color, #fff);
}
.atlas-peek-map {
  position: relative;
  width: 100%;
  aspect-ratio: 1.12 / 1;
  border-radius: 16px;
  overflow: hidden;
  margin: 4px 0 12px;
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
}
.atlas-peek-gl { position: absolute; inset: 0; width: 100%; height: 100%; }
.atlas-peek-map > .atlas-peek-gl.maplibregl-map {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
}
.atlas-peek-map.gl-mounting::after {
  content: 'Loading map…';
  position: absolute; inset: 0;
  display: grid; place-items: center;
  color: var(--muted-color); font-weight: 700; font-size: 0.85rem;
}
.atlas-peek-map.atlas-map-flat { display: grid; place-items: center; }
.atlas-peek-full {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 12px;
  padding: 10px 14px;
  border: 1px solid var(--secondary-color);
  border-radius: 12px;
  background: transparent;
  color: var(--secondary-color);
  font-weight: 850; font-size: 0.88rem;
  cursor: pointer;
}
.journey-peek-ref .material-symbols-outlined { font-size: 16px; vertical-align: -3px; margin-right: 3px; }
.atlas-peek-sub { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 4px 0 2px; }
.atlas-kind-tag {
  font-size: 0.72rem; font-weight: 850; letter-spacing: 0.04em; text-transform: uppercase;
  padding: 3px 9px; border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
  color: var(--secondary-color);
}
.atlas-conf-tag {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 0.72rem; font-weight: 800;
  padding: 3px 9px; border-radius: 999px;
}
.atlas-conf-tag .material-symbols-outlined { font-size: 15px; }
.atlas-conf-firm { background: color-mix(in srgb, #2f9e6f 16%, transparent); color: #1f7d54; }
.atlas-conf-mid { background: color-mix(in srgb, #3b82c0 16%, transparent); color: #2563a0; }
.atlas-conf-soft { background: color-mix(in srgb, #c08a3b 18%, transparent); color: #9a6b1e; }
body.dark .atlas-conf-firm { color: #6fd6a6; }
body.dark .atlas-conf-mid { color: #8fc2f0; }
body.dark .atlas-conf-soft { color: #e3b466; }
/* Possible-locations block for debated places */
.atlas-alts {
  margin: 10px 0;
  padding: 10px 12px;
  border-radius: 13px;
  background: color-mix(in srgb, #c08a3b 10%, var(--card-color));
  border: 1px solid color-mix(in srgb, #c08a3b 28%, transparent);
}
.atlas-alts strong {
  display: flex; align-items: center; gap: 5px;
  font-size: 0.74rem; text-transform: uppercase; letter-spacing: 0.05em;
  color: #9a6b1e; margin-bottom: 5px;
}
body.dark .atlas-alts strong { color: #e3b466; }
.atlas-alts strong .material-symbols-outlined { font-size: 16px; }
.atlas-alts ul { margin: 0; padding-left: 18px; }
.atlas-alts li { font-size: 0.9rem; line-height: 1.5; }
/* Tier dot on list rows */
.atlas-row-dot {
  display: inline-block; width: 8px; height: 8px; border-radius: 50%;
  margin-right: 5px; vertical-align: middle;
}
.atlas-row-dot.atlas-conf-firm { background: #2f9e6f; }
.atlas-row-dot.atlas-conf-mid { background: #3b82c0; }
.atlas-row-dot.atlas-conf-soft { background: #c08a3b; }
.atlas-peek-explain { margin: 8px 2px 10px; font-size: 0.86rem; color: var(--muted-color); line-height: 1.45; }
.atlas-peek-toggle, .atlas-detail-toggle { margin-bottom: 10px; }

/* Journey peek — quick map popup from a verse in the reader. */
.journey-peek-overlay {
  position: fixed;
  inset: 0;
  z-index: 4000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(8, 18, 28, 0.62);
  opacity: 0;
  transition: opacity 0.18s ease;
}
.journey-peek-overlay.open { opacity: 1; }
.journey-peek-card {
  position: relative;
  width: 100%;
  max-width: 440px;
  max-height: 86dvh;
  overflow-y: auto;
  background: var(--card-color, #fffdf7);
  color: var(--font-color, #20303f);
  border-radius: 22px;
  padding: 18px 16px 16px;
  box-shadow: 0 24px 60px rgba(8, 18, 28, 0.4);
  transform: translateY(14px);
  transition: transform 0.2s ease;
}
.journey-peek-overlay.open .journey-peek-card { transform: none; }
.journey-peek-x {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 34px;
  height: 34px;
  border: none;
  border-radius: 50%;
  background: color-mix(in srgb, var(--font-color) 10%, transparent);
  color: var(--font-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.journey-peek-title { display: block; font-size: 1.18rem; font-weight: 950; line-height: 1.1; margin-top: 2px; padding-right: 38px; }
.journey-peek-ref { display: block; color: var(--secondary-color); font-weight: 850; font-size: 0.78rem; margin: 3px 0 12px; }
.journey-peek-toggle {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin: 0 0 10px;
}
.journey-peek-toggle button {
  border: 1px solid var(--border-color);
  border-radius: 13px;
  background: color-mix(in srgb, var(--secondary-color) 6%, var(--card-color));
  color: var(--muted-color);
  padding: 9px 8px;
  font-weight: 900;
  cursor: pointer;
}
.journey-peek-toggle button.active {
  border-color: var(--secondary-color);
  background: var(--secondary-color);
  color: var(--btn-text-color);
}
/* Definite size so MapLibre initializes with a non-zero canvas (it otherwise
   stays on the schematic). Both layers fill the same aspect-ratio box. */
.journey-peek-map {
  position: relative;
  width: 100%;
  aspect-ratio: 1.05 / 1;
  border-radius: 16px;
  overflow: hidden;
}
.journey-peek-mapsvg,
.journey-peek-mapgl { position: absolute; inset: 0; border-radius: 16px; overflow: hidden; }
.journey-peek-map > .journey-peek-mapgl.maplibregl-map {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
}
.journey-peek-mapsvg svg { display: block; width: 100%; height: 100%; }
.journey-peek-mapgl { opacity: 0; pointer-events: none; transition: opacity 0.2s ease; }
.journey-peek-map.gl-ready .journey-peek-mapgl { opacity: 1; pointer-events: auto; }
.journey-peek-map.gl-mounting .journey-peek-mapgl { opacity: 0.01; }
.journey-peek-map.gl-ready .journey-peek-mapsvg { visibility: hidden; }
.journey-peek-facts {
  display: grid;
  gap: 9px;
  margin: 12px 0 14px;
}
.journey-peek-statgrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.journey-peek-statgrid > div {
  min-width: 0;
  display: grid;
  gap: 2px;
  padding: 10px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--secondary-color) 7%, transparent);
  border: 1px solid color-mix(in srgb, var(--secondary-color) 10%, var(--border-color));
}
.journey-peek-statgrid .material-symbols-outlined {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  font-size: 18px;
}
.journey-peek-statgrid strong {
  color: var(--font-color);
  font-size: 0.9rem;
  font-weight: 950;
  line-height: 1.1;
}
.journey-peek-statgrid small {
  color: var(--muted-color);
  font-size: 0.72rem;
  font-weight: 780;
  line-height: 1.2;
}
.journey-peek-step-card {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 10px;
  padding: 11px 12px;
  border-radius: 15px;
  background: color-mix(in srgb, var(--secondary-color) 10%, var(--card-color));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 16%, var(--border-color));
}
.journey-peek-step-card > .material-symbols-outlined {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--secondary-color);
  color: var(--btn-text-color);
  font-size: 18px;
}
.journey-peek-step-card strong,
.journey-peek-receipts strong,
.journey-peek-note strong {
  display: block;
  color: var(--font-color);
  font-weight: 950;
}
.journey-peek-step-card small {
  display: block;
  margin-top: 2px;
  color: var(--secondary-color);
  font-size: 0.74rem;
  font-weight: 880;
}
.journey-peek-step-card p,
.journey-peek-receipts p {
  margin: 5px 0 0;
  color: var(--muted-color);
  font-size: 0.84rem;
  line-height: 1.38;
  font-weight: 700;
}
.journey-peek-note {
  display: grid;
  gap: 3px;
  padding: 10px 12px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--secondary-color) 6%, transparent);
}
.journey-peek-note strong { color: var(--secondary-color); font-size: 0.78rem; }
.journey-peek-note span {
  color: var(--muted-color);
  font-size: 0.84rem;
  line-height: 1.38;
  font-weight: 720;
}
.journey-peek-route-seq {
  display: grid;
  gap: 3px;
  padding: 9px 12px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--secondary-color) 5%, transparent);
}
.journey-peek-route-seq strong {
  display: block;
  color: var(--secondary-color);
  font-size: 0.78rem;
  font-weight: 950;
}
.journey-peek-route-seq span {
  color: var(--muted-color);
  font-size: 0.82rem;
  line-height: 1.35;
  font-weight: 760;
}
.journey-peek-receipts {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--card-color) 84%, var(--secondary-color));
}
.journey-peek-receipts strong {
  color: var(--secondary-color);
  font-size: 0.78rem;
}
.journey-peek-step { margin: 12px 0 14px; color: var(--muted-color); line-height: 1.45; font-size: 0.9rem; }
.journey-peek-step strong { display: block; color: var(--font-color); font-weight: 900; margin-bottom: 2px; }
.journey-peek-open {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: none;
  border-radius: 14px;
  background: var(--secondary-color);
  color: var(--btn-text-color);
  font-weight: 900;
  font-size: 0.95rem;
  padding: 12px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.journey-peek-open:active { transform: scale(0.98); }
.rhema-reader-note-overlay {
  position: absolute;
  inset: 0;
  z-index: 9060;
  display: flex;
  align-items: flex-end;
  background: rgba(0,0,0,0);
  pointer-events: none;
  transition: background 0.22s ease;
}
.rhema-reader-note-overlay.open {
  background: rgba(0,0,0,0.34);
  pointer-events: auto;
}
.rhema-reader-note-card {
  width: 100%;
  max-height: min(74svh, 680px);
  overflow-y: auto;
  background: var(--card-color);
  border-radius: 22px 22px 0 0;
  border-top: 1px solid var(--border-color);
  padding: 18px 16px calc(20px + 0px);
  transform: translateY(100%);
  transition: transform 0.26s cubic-bezier(0.32, 0.72, 0, 1);
  box-shadow: 0 -18px 40px rgba(0,0,0,0.22);
}
.rhema-reader-note-overlay.open .rhema-reader-note-card { transform: translateY(0); }
.rhema-reader-note-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-right: 38px;
  color: var(--font-color);
}
.rhema-reader-note-head > .material-symbols-outlined {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--secondary-color) 13%, transparent);
  color: var(--secondary-color);
}
.rhema-reader-note-head strong { display: block; font-size: 1.05rem; }
.rhema-reader-note-head small { display: block; color: var(--muted-color); font-size: 0.78rem; margin-top: 2px; }
.rhema-reader-note-source {
  margin: 14px 0;
  padding: 12px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--primary-color) 80%, var(--card-color));
  color: var(--font-color);
  line-height: 1.55;
}
.rhema-reader-note-actions {
  display: flex;
  margin: 0 0 10px;
}
.rhema-reader-note-actions button {
  width: 100%;
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 32%, transparent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--secondary-color) 13%, var(--card-color));
  color: var(--secondary-color);
  font-weight: 850;
}
.rhema-reader-note-actions .material-symbols-outlined { font-size: 19px; }
.rhema-reader-note-groups section { margin-top: 14px; }
.rhema-reader-note-groups h4 {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 8px;
  font-size: 0.84rem;
  color: var(--secondary-color);
}
.rhema-reader-note-groups h4 .material-symbols-outlined { font-size: 18px; }
.rhema-reader-note-groups button {
  width: 100%;
  display: grid;
  gap: 4px;
  text-align: left;
  border: 1px solid color-mix(in srgb, var(--border-color) 80%, transparent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--card-color) 96%, var(--primary-color));
  color: var(--font-color);
  padding: 10px 11px;
  margin: 7px 0;
}
.rhema-reader-note-groups button strong { color: var(--secondary-color); font-size: 0.84rem; }
.rhema-reader-note-groups button span { font-size: 0.83rem; line-height: 1.45; }
.rhema-reader-note-groups button em { color: var(--muted-color); font-size: 0.72rem; font-style: normal; }
.rhema-reader-note-groups button em b {
  color: var(--secondary-color);
  font-weight: 850;
  text-transform: capitalize;
}

.rsx-english-tree .rsx-diagram { padding-bottom: 20px; }
.rsx-en-punct {
  align-self: center;
  color: var(--muted-color);
  font-weight: 800;
  padding: 0 2px;
}

/* Tap hint sits in-flow between verse display and verse nav */
.rhema-tap-hint {
  text-align: center;
  font-size: 0.65rem;
  color: var(--muted-color);
  opacity: 0.4;
  padding: 5px 0 0;
  margin: 0;
  pointer-events: none;
  letter-spacing: 0.02em;
}
.rhema-tap-hint.hidden { display: none; }

/* ── Breadcrumb trail ── */
.rhema-breadcrumb {
  display: flex;
  align-items: stretch;
  gap: 8px;
  padding: 0 14px 0 14px;
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--secondary-color) 18%, transparent);
  font-size: 0.71rem;
  flex-shrink: 0;
  /* Hard containment — never let breadcrumb content stretch the screen width */
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow: hidden;
  box-sizing: border-box;
}
.rhema-breadcrumb.hidden { display: none; }

/* scrollable trail portion — items scroll, Clear stays pinned */
.rhema-breadcrumb-scroll {
  flex: 1;
  min-width: 0;
  max-width: 100%;
  display: flex;
  align-items: center;
  gap: 2px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 6px 0 4px;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  touch-action: pan-x;
  scrollbar-width: thin;
  scrollbar-color: var(--secondary-color) transparent;
}
.rhema-breadcrumb-scroll::-webkit-scrollbar {
  height: 3px;
}
.rhema-breadcrumb-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.rhema-breadcrumb-scroll::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--secondary-color) 55%, transparent);
  border-radius: 2px;
}

.rhema-breadcrumb-item {
  color: var(--secondary-color);
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  padding: 2px 4px;
  border-radius: 6px;
  flex-shrink: 0;
}
.rhema-breadcrumb-item:active { opacity: 0.6; }
.rhema-breadcrumb-arrow {
  color: var(--muted-color);
  opacity: 0.5;
  flex-shrink: 0;
}
.rhema-breadcrumb-current {
  font-weight: 500;
  color: var(--muted-color);
  white-space: nowrap;
  padding: 2px 4px;
  flex-shrink: 0;
}
.rhema-breadcrumb-active {
  font-weight: 800;
  color: var(--secondary-color) !important;
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  border-radius: 6px;
}
.rhema-breadcrumb-clear {
  flex-shrink: 0;
  align-self: center;
  background: none;
  border: 1px solid color-mix(in srgb, var(--border-color) 80%, transparent);
  border-radius: 8px;
  padding: 3px 8px;
  font-size: 0.67rem;
  color: var(--muted-color);
  cursor: pointer;
}

/* ── Verse nav bar — direct flex child of overlay, always at physical screen bottom ── */
/* ── Floating prev/next arrows for study-sandbox Rhema ── */
.rhema-sandbox-arrows {
  position: fixed;
  left: 0; right: 0;
  bottom: calc(56px + env(safe-area-inset-bottom, 0px) + 12px);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 16px;
  pointer-events: none;
  z-index: 1050; /* above rhema modal (1000), below study tab bar (1100) */
  opacity: 0;
  transform: translateY(18px);
  visibility: hidden;
  transition: opacity 0.22s ease, transform 0.24s cubic-bezier(.2,.82,.18,1), visibility 0s linear 0.24s;
}
.rhema-sandbox-arrows.visible {
  opacity: 1;
  transform: translateY(0);
  visibility: visible;
  transition-delay: 0s;
}
.rhema-sandbox-nav-btn {
  pointer-events: all;
  background: linear-gradient(145deg, var(--secondary-color), color-mix(in srgb, var(--secondary-color) 80%, #000));
  border: none;
  border-radius: 50%;
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; color: var(--btn-text-color);
  box-shadow: 0 2px 10px color-mix(in srgb, var(--secondary-color) 35%, rgba(0,0,0,0.14));
  -webkit-tap-highlight-color: transparent;
  transition: all 0.12s;
  flex-shrink: 0;
}
.rhema-sandbox-nav-btn:active {
  transform: scale(0.92);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--secondary-color) 20%, rgba(0,0,0,0.1));
}
.rhema-sandbox-nav-btn .material-symbols-outlined { font-size: 1.35rem; }

.rhema-verse-nav {
  /* Overlays the bottom of the reader (see .rhema-reader note) — hiding it is
     transform-only so the scroll area never resizes underneath a scroll gesture */
  position: absolute;
  left: 0; right: 0; bottom: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 14px calc(0px + 10px);
  background: transparent;
  border-top: none;
  touch-action: none;
  user-select: none;
  opacity: 1;
  transform: translateY(0);
  transition: opacity 0.2s ease, transform 0.28s cubic-bezier(.2,.82,.18,1);
  will-change: transform;
}
.rhema-verse-nav-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: linear-gradient(145deg, rgba(255,255,255,0.94), color-mix(in srgb, var(--secondary-color) 5%, rgba(255,255,255,0.88)));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 15%, rgba(255,255,255,0.5));
  border-radius: 28px;
  padding: 8px 8px;
  box-shadow: 0 4px 20px color-mix(in srgb, var(--secondary-color) 12%, rgba(0,0,0,0.08)), 0 2px 6px rgba(0,0,0,0.05), inset 0 1px 1px rgba(255,255,255,0.9);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}
.rhema-verse-nav.hidden { display: none; }
#rhemaModal.picker-open .rhema-verse-nav { visibility: hidden; pointer-events: none; }
#rhemaModal.rhema-chrome-hidden .rhema-top-chrome {
  opacity: 0;
  transform: translateY(-102%); /* fully off — transform only, no layout change */
  pointer-events: none;
}
#rhemaModal.rhema-chrome-hidden .rhema-verse-nav {
  opacity: 0;
  transform: translateY(calc(100% + 18px));
  pointer-events: none;
}
#rhemaModal.rhema-chrome-hidden .rhema-sandbox-arrows.visible {
  opacity: 0;
  transform: translateY(18px);
  pointer-events: none;
  visibility: hidden;
}
.rhema-nav-btn {
  background: linear-gradient(145deg, var(--secondary-color), color-mix(in srgb, var(--secondary-color) 80%, #000));
  border: none;
  border-radius: 50%;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--btn-text-color);
  -webkit-tap-highlight-color: transparent;
  transition: all 0.12s;
  flex-shrink: 0;
  box-shadow: 0 2px 8px color-mix(in srgb, var(--secondary-color) 35%, rgba(0,0,0,0.12));
}
.rhema-nav-btn:active {
  transform: scale(0.92);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--secondary-color) 20%, rgba(0,0,0,0.1));
}
.rhema-nav-btn .material-symbols-outlined { font-size: 1.35rem; }
.rhema-verse-ref {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--font-color);
  opacity: 0.88;
  text-align: center;
  flex: 1;
  padding: 0 8px;
  line-height: 1.3;
}

/* ── Dark mode: the reader chrome's raised white glass goes dark. Dark themes
   brighten --secondary-color/--font-color for dark surfaces, so on the white
   glass pills (book picker, version, swap, tools, verse nav) the light text
   vanished — cyan and other bright themes were the worst. ── */
body.dark .rhema-back-btn.icon-btn,
body.dark .rhema-swap-btn,
body.dark .rhema-tool-btn,
body.dark .rhema-pill,
body.dark .rhema-verse-nav-row {
  background: linear-gradient(145deg, rgba(38,46,58,0.94), color-mix(in srgb, var(--secondary-color) 10%, rgba(26,32,42,0.9)));
  border-color: color-mix(in srgb, var(--secondary-color) 30%, rgba(255,255,255,0.08));
  box-shadow: 0 2px 8px rgba(0,0,0,0.35), inset 0 1px 1px rgba(255,255,255,0.07);
}
body.dark .rhema-back-btn.icon-btn:active,
body.dark .rhema-swap-btn:active,
body.dark .rhema-tool-btn:active,
body.dark .rhema-pill:active {
  background: color-mix(in srgb, var(--secondary-color) 18%, rgba(26,32,42,0.92));
}
body.dark .rhema-tool-btn.has-active {
  background: linear-gradient(145deg, color-mix(in srgb, var(--secondary-color) 26%, rgba(26,32,42,0.92)), color-mix(in srgb, var(--secondary-color) 14%, rgba(26,32,42,0.88)));
  border-color: color-mix(in srgb, var(--secondary-color) 45%, rgba(255,255,255,0.1));
}
body.dark .rhema-chapter-mode-pill.active {
  background: linear-gradient(145deg, color-mix(in srgb, var(--secondary-color) 30%, rgba(26,32,42,0.92)), color-mix(in srgb, var(--secondary-color) 18%, rgba(26,32,42,0.88)));
  color: var(--secondary-color);
  border-color: color-mix(in srgb, var(--secondary-color) 40%, transparent);
}

@keyframes xrefPulse {
  0%   { background: color-mix(in srgb, var(--accent-color) 55%, transparent); }
  100% { background: color-mix(in srgb, var(--accent-color) 22%, transparent); }
}

/* ── Tappable occ rows ── */
.rhema-occ-row.tappable {
  cursor: pointer;
  border-radius: 8px;
  margin: 0 -8px;
  padding: 7px 8px;
  transition: background 0.12s;
}
.rhema-occ-row.tappable:active {
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
}

/* ── Cross-ref verse list ── */
.rhema-xref-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.rhema-xref-back-btn {
  background: none;
  border: 1.5px solid var(--border-color);
  border-radius: 10px;
  padding: 5px 12px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--font-color);
  cursor: pointer;
  flex-shrink: 0;
  -webkit-tap-highlight-color: transparent;
}
.rhema-xref-back-btn:active { opacity: 0.6; }
.rhema-xref-title {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--font-color);
  flex: 1;
}
.rhema-xref-english-btn {
  flex-shrink: 0;
  background: none;
  border: 1.5px solid var(--border-color);
  border-radius: 10px;
  padding: 5px 10px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--secondary-color);
  cursor: pointer;
  letter-spacing: 0.04em;
  transition: all 0.15s;
  -webkit-tap-highlight-color: transparent;
}
.rhema-xref-english-btn.active {
  background: var(--secondary-color);
  border-color: var(--secondary-color);
  color: var(--btn-text-color);
}
.rhema-xref-verse-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 6px;
  border-radius: 10px;
  cursor: pointer;
  border-bottom: 1px solid color-mix(in srgb, var(--border-color) 40%, transparent);
  transition: background 0.12s;
}
.rhema-xref-verse-row:active {
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
}
.rhema-xref-verse-ref {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--secondary-color);
  min-width: 48px;
  flex-shrink: 0;
  padding-top: 1px;
}
.rhema-xref-verse-text {
  font-size: 0.82rem;
  color: var(--muted-color);
  line-height: 1.55;
}
.xref-match {
  color: var(--font-color);
  font-weight: 700;
}

/* ── Bottom sheet ── */
.rhema-sheet-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(8, 18, 28, 0.44);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s;
  z-index: 1050;
}
.rhema-sheet-backdrop.visible {
  opacity: 1;
  pointer-events: all;
}

.rhema-sheet {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: #ffffff;
  border-radius: 22px 22px 0 0;
  box-shadow: 0 -6px 40px rgba(0,0,0,0.18);
  border-top: 1.5px solid var(--border-color);
  z-index: 1051;
  transform: translateY(100%);
  visibility: hidden;
  will-change: transform;
  transition: transform 0.28s cubic-bezier(0.32, 0, 0.67, 0),
              visibility 0s linear 0.28s;
  min-height: 60svh;
  max-height: 82svh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding-bottom: 0px;
}
.rhema-sheet.open {
  transform: translateY(0);
  visibility: visible;
  transition: transform 0.32s cubic-bezier(0.34, 1.2, 0.64, 1),
              visibility 0s linear 0s;
}
body.dark .rhema-sheet { background: #1f2937; }
body.sepia .rhema-sheet { background: #fffcf2; }

.rhema-sheet-handle {
  width: 40px;
  height: 4px;
  background: color-mix(in srgb, var(--muted-color) 40%, transparent);
  border-radius: 2px;
  margin: 12px auto 8px;
  flex-shrink: 0;
  cursor: grab;
  touch-action: none;
}

.rhema-sheet-top {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 4px 52px 0 22px;
  flex-shrink: 0;
}
.rhema-sheet-surface {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--secondary-color);
  letter-spacing: 0.03em;
  line-height: 1.1;
}
.rhema-sheet-strongs {
  font-size: 0.75rem;
  color: var(--muted-color);
  font-weight: 600;
  letter-spacing: 0.05em;
}
.rhema-copy-word-btn {
  margin-left: auto;
  align-self: center;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--muted-color);
  padding: 5px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s, background 0.15s;
}
.rhema-copy-word-btn:hover { color: var(--font-color); background: var(--border-color); }
.rhema-copy-word-btn:active { background: var(--secondary-color); color: var(--btn-text-color); }
.rhema-copy-word-btn .material-symbols-outlined { font-size: 18px; }
.rhema-sheet-lemma {
  padding: 3px 22px 10px;
  font-size: 0.85rem;
  color: var(--muted-color);
  flex-shrink: 0;
  font-style: italic;
}

/* Tabs */
.rhema-sheet-tabs {
  display: flex;
  border-bottom: 1.5px solid var(--border-color);
  padding: 0 18px;
  flex-shrink: 0;
}
.rhema-tab {
  flex: 1;
  background: none;
  border: none;
  border-bottom: 2.5px solid transparent;
  margin-bottom: -1.5px;
  padding: 10px 4px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--muted-color);
  cursor: pointer;
  transition: all 0.15s;
  letter-spacing: 0.02em;
}
.rhema-tab.active {
  color: var(--secondary-color);
  border-bottom-color: var(--secondary-color);
}

.rhema-tab-content {
  flex: 1;
  overflow-y: auto;
  padding: 16px 22px 24px;
  overscroll-behavior: contain;
}

/* ── Parsing tab ── */
.rhema-parsing-grid { display: flex; flex-direction: column; }
.rhema-parse-row {
  display: grid;
  grid-template-columns: 100px 1fr;
  align-items: start;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--border-color) 50%, transparent);
}
.rhema-parse-label {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--muted-color);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding-top: 2px;
}
.rhema-parse-value {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--font-color);
}
.rhema-parse-value.rhema-value-link {
  color: var(--secondary-color);
}
.rhema-parse-desc {
  font-size: 0.75rem;
  color: var(--muted-color);
  margin-top: 2px;
  font-style: italic;
}

/* ── Definition tab ── */
.rhema-def-section { margin-bottom: 16px; }
.rhema-def-label {
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted-color);
  margin-bottom: 5px;
}
.rhema-def-text {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--font-color);
}
.rhema-def-quick { margin-bottom: 14px; }
.rhema-def-quick-text {
  font-size: 1rem;
  line-height: 1.45;
  color: var(--font-color);
}
.rhema-def-quick-text strong { font-weight: 800; }
.rhema-current-form-gloss {
  margin-top: 8px;
  padding: 8px 10px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
  color: var(--muted-color);
  font-size: 0.8rem;
  line-height: 1.4;
}
.rhema-current-form-gloss strong {
  color: var(--font-color);
}
.rhema-source-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.rhema-source-chips button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  max-width: 100%;
  min-height: 28px;
  padding: 4px 8px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 18%, var(--border-color));
  border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 6%, transparent);
  color: var(--secondary-color);
  font: inherit;
  font-size: 0.7rem;
  font-weight: 850;
  cursor: pointer;
}
