  font-size: 0.88rem;
  color: var(--font-color);
}
.rhema-range-head small {
  font-size: 0.7rem;
  color: var(--muted-color);
  font-weight: 700;
}
.rhema-range-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}
.rhema-range-chip-row span {
  padding: 5px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 13%, var(--card-color));
  color: var(--secondary-color);
