}
.rhema-range-ref {
  display: block;
  margin-bottom: 5px;
  color: var(--secondary-color);
  font-size: 0.72rem;
  font-weight: 900;
}
.rhema-range-verse {
  display: block;
  color: var(--font-color);
  font-size: 0.86rem;
  line-height: 1.55;
}
.rhema-range-english,
.rhema-range-translation-list {
  display: block;
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid color-mix(in srgb, var(--border-color) 65%, transparent);
  color: var(--muted-color);
  font-size: 0.78rem;
  line-height: 1.45;
}
.rhema-range-translation-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.rhema-range-translation-row {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: start;
  gap: 7px;
}
.rhema-range-translation-row em {
  padding: 2px 5px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
  color: var(--secondary-color);
  font-style: normal;
  font-size: 0.65rem;
  font-weight: 900;
}
.rhema-range-translation-row strong {
  color: var(--font-color);
  font-size: 0.72rem;
  font-weight: 900;
}
.rhema-range-translation-row strong.rhema-range-no-hit {
  color: var(--muted-color);
  font-style: italic;
  font-weight: 700;
}
.rhema-range-translation-row > span {
  min-width: 0;
}
.rhema-range-english-hit {
  border-radius: 5px;
  background: color-mix(in srgb, var(--secondary-color) 18%, transparent);
  color: var(--secondary-color);
  padding: 1px 3px;
  font-weight: 900;
}
.rhema-range-hit {
  background: color-mix(in srgb, var(--secondary-color) 22%, transparent);
  color: var(--secondary-color);
  border-radius: 5px;
  padding: 1px 3px;
  font-weight: 900;
}
.rhema-range-muted {
  margin: 0;
  color: var(--muted-color);
  font-size: 0.8rem;
  line-height: 1.45;
}
/* Deep lexicon — corpus-measured range of meaning */
.rhema-deep-block {
  margin-bottom: 12px;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: 12px;
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
}
.rhema-deep-loading {
  color: var(--muted-color);
  font-size: 0.78rem;
  font-style: italic;
}
.rhema-deep-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}
.rhema-deep-head strong { font-size: 0.82rem; }
.rhema-deep-conf {
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 0.64rem;
  font-weight: 800;
  white-space: nowrap;
}
.rhema-deep-conf-high     { background: color-mix(in srgb, #2e9e5b 18%, var(--card-color)); color: #2e9e5b; }
.rhema-deep-conf-good     { background: color-mix(in srgb, var(--secondary-color) 16%, var(--card-color)); color: var(--secondary-color); }
.rhema-deep-conf-moderate { background: color-mix(in srgb, #d98a26 18%, var(--card-color)); color: #d98a26; }
.rhema-deep-conf-low,
.rhema-deep-conf-none     { background: color-mix(in srgb, var(--muted-color) 16%, var(--card-color)); color: var(--muted-color); }
.rhema-deep-senses {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 10px;
}
.rhema-deep-sense-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.rhema-deep-gloss { font-weight: 800; font-size: 0.92rem; }
.rhema-deep-count {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--muted-color);
  white-space: nowrap;
}
.rhema-deep-bar {
