.rhema-deep-note {
  font-size: 0.72rem;
  color: var(--muted-color);
  line-height: 1.45;
  margin-bottom: 6px;
}
.rhema-deep-patterns {
  margin: 10px 0;
  padding: 10px 12px;
  border: 1px dashed var(--border-color);
  border-radius: 12px;
}
.rhema-deep-patterns-head {
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted-color);
  margin-bottom: 8px;
}
.rhema-deep-pattern { margin-bottom: 10px; }
.rhema-deep-pattern:last-of-type { margin-bottom: 6px; }
.rhema-deep-pattern-top {
