}
.rhema-deep-pattern-comp em {
  font-style: normal;
  font-weight: 700;
  color: var(--secondary-color);
}
.rhema-deep-why-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  margin: 4px 0;
  padding: 7px 10px;
  border: 1px solid var(--border-color);
  border-radius: 10px;
  background: var(--card-color);
