}
.rhema-deep-why-btn .material-symbols-outlined { font-size: 1rem; }
.rhema-deep-why-arrow { margin-left: auto; transition: transform 0.18s ease; }
.rhema-deep-why-btn.open .rhema-deep-why-arrow { transform: rotate(180deg); }
.rhema-deep-why {
  padding: 8px 10px;
  border-left: 3px solid color-mix(in srgb, var(--secondary-color) 45%, transparent);
  margin: 6px 0;
}
