.rhema-deep-why p {
  margin: 0 0 8px;
  font-size: 0.78rem;
  line-height: 1.5;
}
.rhema-deep-why p:last-child { margin-bottom: 0; }
.rhema-deep-foot {
  margin-top: 4px;
  font-size: 0.66rem;
