}
.rhema-occ-total span {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--secondary-color);
}
.rhema-occ-list { display: flex; flex-direction: column; }
.rhema-occ-row {
  display: flex;
  justify-content: space-between;
