/* ══ Home / Profile / Community — app padding fix + app-header visibility ════ */

/* Remove all .app padding when nav screens are active so they fill edge-to-edge */
body .app:has(#homeScreen.screen.active),
body .app:has(#profilePage.screen.active),
body .app:has(#communityPage.screen.active),
body .app:has(#merciesPage.screen.active),
body .app:has(#habitsPage.screen.active) {
  padding: 0 !important;
  overflow: hidden;
  height: 100vh;
  height: 100dvh;
}

/* Hide the app-header on nav screens (each screen has its own header) */
body .app:has(#homeScreen.screen.active) .app-header,
body .app:has(#profilePage.screen.active) .app-header,
body .app:has(#communityPage.screen.active) .app-header,
body .app:has(#merciesPage.screen.active) .app-header,
body .app:has(#habitsPage.screen.active) .app-header {
  display: none !important;
}

/* Remove stale margin-top overrides */
body .app:has(#homeScreen.screen.active) #homeScreen,
body .app:has(#profilePage.screen.active) #profilePage,
body .app:has(#communityPage.screen.active) #communityPage,
body .app:has(#merciesPage.screen.active) #merciesPage,
body .app:has(#habitsPage.screen.active) #habitsPage {
  margin-top: 0 !important;
}

#homeScreen.screen.active {
  height: 100vh;
  height: 100dvh;
  overflow: hidden !important;
}

/* Community and profile pages fill full height */
#communityPage.screen.active,
#profilePage.screen.active {
  display: flex; flex-direction: column;
  height: 100vh; height: 100dvh; overflow: hidden;
  background: var(--primary-color) !important;
  border-radius: 0 !important; box-shadow: none !important;
  border: none !important; padding: 0 !important;
  position: relative;
}

/* ══ Settings screen redesign ════════════════════════════════════════════════ */

#settingsScreen.screen.active {
  background: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border: none !important;
  padding: 0 !important;
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  overflow: hidden;
  touch-action: pan-y;
}

/* Remove app padding when settings is active */
body .app:has(#settingsScreen.screen.active) {
  padding-left: 0 !important;
  padding-right: 0 !important;
  padding-top: 0 !important;
}

/* Settings nav bar stays at top */
#settingsScreen .nav-bar {
  flex-shrink: 0;
}

/* Scrollable body */
.sett-scroll {
  flex: 1 1 0;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  overscroll-behavior: contain;
  padding: 12px 16px calc(0px + 32px);
  display: flex;
  flex-direction: column;
  gap: 0;
  /* Hide the scrollbar so no track/strip shows on the right edge */
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}
.sett-scroll::-webkit-scrollbar,
.sett-scroll::-webkit-scrollbar-track,
.sett-scroll::-webkit-scrollbar-thumb,
.sett-scroll::-webkit-scrollbar-corner {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
  background: transparent !important;
}

/* Section label */
.sett-section-label {
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted-color);
  opacity: 0.7;
  margin: 20px 4px 8px;
}
.sett-section-label:first-child { margin-top: 8px; }

.sett-section-desc {
  font-size: 0.82rem;
  color: var(--muted-color);
  margin: -4px 4px 8px;
  line-height: 1.4;
}

/* Card container */
.sett-card {
  background: var(--card-color);
  border: 1px solid var(--border-color);
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* Separator */
.sett-sep {
  height: 1px;
  background: var(--border-color);
  opacity: 0.5;
  margin: 0 16px;
  flex-shrink: 0;
}

/* Row */
.sett-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: pan-y;
  transition: background 0.12s;
  color: var(--font-color);
}
.sett-row:active { background: color-mix(in srgb, var(--border-color) 50%, transparent); }

.sett-row-icon-wrap {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.sett-row-icon-wrap .material-symbols-outlined {
  font-size: 1.3rem !important;
  color: var(--secondary-color) !important;
}

.sett-row-text { flex: 1; display: flex; flex-direction: column; gap: 1px; }
.sett-row-name { font-size: 0.95rem; font-weight: 700; color: var(--font-color); }
.sett-row-sub  { font-size: 0.78rem; color: var(--muted-color); }

.sett-row-chev {
  font-size: 1.25rem !important;
  color: var(--muted-color) !important;
  opacity: 0.45;
  flex-shrink: 0;
}

/* Danger row */
.sett-icon-danger { background: color-mix(in srgb, #ef4444 10%, transparent) !important; }
.sett-icon-danger .material-symbols-outlined { color: #ef4444 !important; }
.sett-name-danger { color: #ef4444 !important; }

/* Theme rows */
.sett-theme-card { overflow: visible; }  /* let sett-sep extend slightly */
.sett-theme-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: pan-y;
  transition: background 0.12s;
}
.sett-theme-row:active { background: color-mix(in srgb, var(--border-color) 50%, transparent); }

.sett-theme-swatch {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex-shrink: 0;
  border: 2px solid transparent;
  display: block;
}

.sett-theme-check {
  font-size: 1.2rem !important;
  color: var(--secondary-color) !important;
  margin-left: auto;
  display: none !important;
  flex-shrink: 0;
}
.theme-preset.selected .sett-theme-check { display: block !important; }

body.high-contrast-theme #settingsScreen #highContrastToggle + .slider {
  background: var(--secondary-color);
}

body.high-contrast-theme .sett-theme-card {
  border-color: color-mix(in srgb, var(--secondary-color) 38%, var(--border-color));
}

.theme-wheel-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 14px;
}

.theme-wheel-group {
  --wheel-colors: conic-gradient(#1d4ed8, #38bdf8, #003bdb, #93c5fd, #1d4ed8);
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--border-color) 58%, transparent);
  border-radius: 16px;
  background:
    linear-gradient(135deg,
      color-mix(in srgb, var(--card-color) 92%, transparent),
      color-mix(in srgb, var(--secondary-color) 5%, var(--card-color)));
}

.theme-wheel-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 0;
}

.theme-wheel-head strong {
  max-width: 100%;
  color: var(--font-color);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: center;
  overflow-wrap: anywhere;
}

.theme-wheel-orb {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: var(--wheel-colors);
  box-shadow:
    inset 0 0 0 7px color-mix(in srgb, var(--card-color) 82%, transparent),
    0 10px 24px color-mix(in srgb, var(--secondary-color) 18%, transparent);
}

.theme-wheel-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.theme-wheel-tile {
  position: relative;
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-items: center;
  gap: 2px 8px;
  min-height: 54px;
  padding: 8px 10px 8px 8px;
  border: 1px solid color-mix(in srgb, var(--border-color) 56%, transparent);
  border-radius: 14px;
  background: color-mix(in srgb, var(--card-color) 88%, rgba(255,255,255,0.42));
  color: var(--font-color);
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  overflow: hidden;
  transition: transform 0.14s ease, border-color 0.14s ease, background 0.14s ease, box-shadow 0.14s ease;
}

.theme-wheel-tile:active {
  transform: scale(0.985);
}

.theme-wheel-tile > span:first-child {
  grid-row: 1 / 3;
  width: 26px !important;
  height: 26px !important;
  border-radius: 50% !important;
  background: var(--tile-gradient) !important;
  border: 2px solid color-mix(in srgb, white 52%, var(--border-color)) !important;
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.12), 0 5px 12px rgba(0,0,0,0.12) !important;
}

.theme-wheel-tile small {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow-wrap: normal;
  word-break: keep-all;
}

.theme-wheel-tile strong {
  min-width: 0;
  max-width: 100%;
  /* Smaller single-line name so the full word fits without breaking mid-word */
  font-size: clamp(0.56rem, 2.05vw, 0.68rem);
  line-height: 1.12;
  font-weight: 850;
  color: var(--font-color);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: keep-all;
  overflow-wrap: normal;
}

.theme-wheel-tile small {
  font-size: clamp(0.56rem, 2.05vw, 0.64rem);
  line-height: 1.05;
  color: var(--muted-color);
}

.theme-wheel-check {
  position: absolute;
  top: 5px;
  right: 5px;
  align-self: center;
  justify-self: center;
  display: none !important;
  color: var(--secondary-color) !important;
  font-size: 1.05rem !important;
  width: auto !important;
  height: auto !important;
  border: none !important;
  border-radius: 0 !important;
  background: none !important;
  box-shadow: none !important;
}

.theme-wheel-tile.selected {
  border-color: color-mix(in srgb, var(--secondary-color) 72%, var(--border-color));
  background:
    linear-gradient(135deg,
      color-mix(in srgb, var(--secondary-color) 11%, var(--card-color)),
      color-mix(in srgb, var(--accent-color) 7%, var(--card-color)));
  box-shadow: 0 10px 24px color-mix(in srgb, var(--secondary-color) 16%, transparent);
}

.theme-wheel-tile.selected .theme-wheel-check {
  display: inline-flex !important;
}

.theme-wheel-blues { --wheel-colors: conic-gradient(#003bdb, #00a7e8, #38d6ff, #001730, #2563eb, #003bdb); }
.theme-wheel-greens { --wheel-colors: conic-gradient(#047857, #00d47e, #a3e635, #14532d, #0f766e, #047857); }
.theme-wheel-reds { --wheel-colors: conic-gradient(#e0002a, #ff2a00, #ff8a00, #9f1239, #ff1744, #e0002a); }
.theme-wheel-violets { --wheel-colors: conic-gradient(#6d28d9, #d900ff, #ff2da8, #8b00ff, #00c2ff, #6d28d9); }
.theme-wheel-golds { --wheel-colors: conic-gradient(#f5d400, #ffb300, #ff6a00, #d4a011, #c8a24a, #f5d400); }
.theme-wheel-neutrals { --wheel-colors: conic-gradient(#111827, #4b5563, #f0f8ff, #8b5e34, #334155, #111827); }

body.high-contrast-theme .theme-wheel-tile.selected {
  border-width: 2px;
}

body.dark .theme-wheel-group,
body.dark .theme-wheel-tile {
  background: color-mix(in srgb, var(--card-color) 92%, #111827);
}

@media (min-width: 720px) {
  .theme-wheel-tiles {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 380px) {
  .theme-wheel-stack {
    padding: 12px;
  }

  .theme-wheel-group {
    grid-template-columns: 58px minmax(0, 1fr);
    gap: 9px;
    padding: 8px;
  }

  .theme-wheel-orb {
    width: 46px;
    height: 46px;
  }

  .theme-wheel-tile {
    grid-template-columns: 24px minmax(0, 1fr);
    min-height: 52px;
    padding: 7px 9px 7px 7px;
    gap: 2px 6px;
  }

  .theme-wheel-tile > span:first-child {
    width: 24px !important;
    height: 24px !important;
  }

  .theme-wheel-tile strong {
    font-size: 0.66rem;
  }

  .theme-wheel-tile small {
    font-size: 0.58rem;
  }
}

/* Reset old theme-preset span rules that bleed onto text/check spans in settings rows */
.sett-theme-row .sett-theme-swatch {
  width: 32px !important;
  height: 32px !important;
  box-shadow: none !important;
