/* ── Bottom Nav ──────────────────────────────────────────────────────────── */
.bottom-nav {
  position: fixed;
  left: 50%;
  right: auto;
  bottom: calc(27px + 0px);
  z-index: 900;
  display: flex;
  align-items: stretch;
  width: min(calc(100% - 28px), 470px);
  margin: 0 auto;
  padding: 8px 10px 9px;
  border: 1px solid color-mix(in srgb, var(--border-color) 58%, rgba(255,255,255,0.68));
  border-radius: 30px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--card-color) 86%, rgba(255,255,255,0.72)), color-mix(in srgb, var(--card-color) 76%, var(--primary-light))),
    rgba(255,255,255,0.66);
  box-shadow:
    0 18px 42px rgba(15, 23, 42, 0.18),
    0 4px 14px rgba(15, 23, 42, 0.08),
    inset 0 1px 0 rgba(255,255,255,0.62);
  backdrop-filter: blur(18px) saturate(1.18);
  -webkit-backdrop-filter: blur(18px) saturate(1.18);
  transform: translateX(-50%);
  transition: transform 0.25s ease, opacity 0.2s ease;
}
.bottom-nav.hidden {
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, calc(100% + 24px + 0px));
}
/* While the launch splash is still up (even mid fade-out), keep the bottom nav
   fully hidden so it never flashes in/out before the app has finished loading.
   Once the splash gets .hidden, the nav fades into its normal state. */
body:has(#appLaunchScreen:not(.hidden)) .bottom-nav {
  opacity: 0 !important;
  pointer-events: none !important;
  transform: translate(-50%, calc(100% + 24px + 0px)) !important;
}
/* While the splash is up, match the page background to the splash colour so the
   themed page colour can never show as a strip in the bottom safe area while the
   app is loading. (Matches the splash gradient's outer tone / manifest bg.) */
html:has(#appLaunchScreen:not(.hidden)),
body:has(#appLaunchScreen:not(.hidden)) {
  background: linear-gradient(180deg, var(--primary-color), var(--primary-light)) !important;
}
.bottom-nav.mercies-collapsed {
  width: 76px !important;
  height: 76px !important;
  right: 16px !important;
  left: auto !important;
  bottom: calc(18px + 0px) !important;
  padding: 0 !important;
  border-radius: 50% !important;
  transform: translateX(0) !important;
  overflow: visible;
}
.bottom-nav.mercies-collapsed .bn-item {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transform: scale(.5);
}
.bottom-nav.mercies-collapsed .bn-item[data-page="home"],
.bottom-nav.mercies-collapsed .bn-item[data-page="profile"],
.bottom-nav.mercies-collapsed .bn-item[data-page="community"] {
  display: flex;
  opacity: 1;
  pointer-events: auto;
}
.bottom-nav.mercies-collapsed .bn-item[data-page="home"] {
  z-index: 4;
  color: var(--secondary-color) !important;
  transform: scale(1);
}
.bottom-nav.mercies-collapsed .bn-item[data-page="profile"] {
  z-index: 2;
  opacity: .54;
  transform: translateX(-18px) scale(.62);
}
.bottom-nav.mercies-collapsed .bn-item[data-page="community"] {
  z-index: 2;
  opacity: .54;
  transform: translateX(24px) scale(.62);
}
.bottom-nav.mercies-collapsed .bn-item > span:not(.material-symbols-outlined),
.bottom-nav.mercies-collapsed .bn-dot,
.bottom-nav.mercies-collapsed .bn-item::after {
  display: none !important;
}
.bottom-nav.mercies-collapsed .bn-item .material-symbols-outlined {
  font-size: 1.9rem !important;
}
.bn-item {
  flex: 1; display: flex; flex-direction: column; align-items: center;
  justify-content: center; gap: 0; padding: 10px 4px;
  background: none; border: none; cursor: pointer;
  color: var(--muted-color);
  position: relative; transition: color 0.15s, transform 0.15s ease;
  isolation: isolate;
  -webkit-tap-highlight-color: transparent;
}
.bn-item > span {
  position: relative;
  z-index: 1;
}
.bn-item::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 48px;
  height: 48px;
  border-radius: 999px;
  background: var(--secondary-color);
  box-shadow: 0 4px 14px color-mix(in srgb, var(--secondary-color) 40%, transparent);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.72);
  transition: opacity 0.16s ease, transform 0.16s ease;
  z-index: 0;
}
.bn-item:active { transform: translateY(1px) scale(0.98); }
.bn-item .material-symbols-outlined {
  font-size: 1.5rem;
  font-variation-settings: 'FILL' 0, 'wght' 450, 'GRAD' 0, 'opsz' 24;
  transition: color 0.16s ease, font-variation-settings 0.16s ease, transform 0.16s ease;
}
.bn-item.active {
  color: var(--secondary-color);
}
.bn-item.active::before {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}
.bn-item.active .material-symbols-outlined {
  color: #fff;
  font-variation-settings: 'FILL' 1, 'wght' 650, 'GRAD' 0, 'opsz' 24;
}
.bn-dot,
.bn-item::after {
  position: absolute; bottom: 5px; left: 50%; transform: translateX(-50%);
  width: 5px; height: 5px; border-radius: 50%; background: var(--secondary-color);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--secondary-color) 12%, transparent);
  display: none;
}
.bn-item::after {
  content: "";
}
.bn-item.active .bn-dot { display: none; }
.bn-item.active::after { display: none; }
body.dark .bottom-nav {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--card-color) 78%, rgba(15,23,42,0.76)), color-mix(in srgb, var(--primary-light) 34%, rgba(15,23,42,0.82))),
    rgba(15,23,42,0.72);
  border-color: color-mix(in srgb, var(--border-color) 48%, rgba(255,255,255,0.14));
  box-shadow:
    0 20px 48px rgba(0,0,0,0.42),
    0 5px 16px rgba(0,0,0,0.22),
    inset 0 1px 0 rgba(255,255,255,0.08);
}
body.dark .bn-item::before {
  background: var(--secondary-color);
  box-shadow: 0 4px 14px color-mix(in srgb, var(--secondary-color) 40%, transparent);
}

/* ── Home Screen ─────────────────────────────────────────────────────────── */
/* Greeting row — greeting text left, settings icon right, at same baseline */
.home-top-row {
  position: relative;
  display: flex; align-items: flex-start; justify-content: flex-start;
  gap: 2px;
  padding: calc(env(safe-area-inset-top, 20px) + 12px) 0 0;
  margin-bottom: 6px;
}
.home-top-row .home-greeting-wrap { margin: 0; flex: 1 1 auto; min-width: 0; }
.home-top-actions { /* hugs the very top right, level with the "Good" line.
   #homeScreen zeroes the row's padding (safe area lives on .home-scroll),
   so the row's top edge IS the top of the greeting. */
  position: absolute;
  top: 0;
  right: 0;
  display: flex; align-items: flex-start; gap: 7px;
}
/* Normalize the two legacy buttons (different paddings/heights/icon sizes)
   so calendar and bell sit on exactly the same line. */
.home-top-actions .ht-btn {
  width: 38px;
  height: 38px;
  padding: 0;
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  /* Theme-matching pill background (matches the home search pill) */
  border-radius: 12px;
  background: linear-gradient(135deg,
    color-mix(in srgb, var(--card-color) 96%, #fff) 0%,
    color-mix(in srgb, var(--primary-color) 72%, var(--card-color)) 100%);
  border: 1px solid color-mix(in srgb, var(--secondary-color) 16%, rgba(255,255,255,0.72));
  box-shadow: 0 6px 16px rgba(0,0,0,0.05), inset 0 1px 0 rgba(255,255,255,0.85);
  color: var(--secondary-color);
  transition: transform 0.12s ease, box-shadow 0.2s ease;
}
.home-top-actions .ht-btn:active { transform: scale(0.94); }
.home-top-actions .ht-btn .material-symbols-outlined {
  font-size: 1.32rem;
  line-height: 1;
  color: var(--secondary-color);
}
.ht-btn {
  background: none; border: none; cursor: pointer; padding: 6px;
  color: var(--font-color); position: relative; flex-shrink: 0;
  -webkit-tap-highlight-color: transparent;
}
.ht-btn .material-symbols-outlined { font-size: 1.5rem; }
/* Badge on notification tile icon */
.hat-notif-icon { position: relative; }
.notif-badge {
  position: absolute; top: -5px; right: -5px;
  width: 13px; height: 13px;
  background: #ef4444; border-radius: 50%;
  border: 2.5px solid var(--primary-color);
  box-shadow: 0 0 0 2px rgba(239,68,68,0.3);
  animation: notif-pulse 2s ease-in-out infinite;
}
@keyframes notif-pulse {
  0%, 100% { box-shadow: 0 0 0 2px rgba(239,68,68,0.3); }
  50%       { box-shadow: 0 0 0 6px rgba(239,68,68,0); }
}
/* Scroll container — full height, topbar scrolls with content */
.home-scroll {
  overflow-y: auto; height: 100%;
  padding: 0 20px; -webkit-overflow-scrolling: touch;
  position: relative;
  isolation: isolate;
  overscroll-behavior: contain;
}
/* Fog overlays — pointer-events:none so they don't block taps */
#homeScreen {
  position: relative;
  -webkit-user-select: none;
  user-select: none;
}
.home-scroll > * {
  position: relative;
  z-index: 2;
}
.home-scroll::before,
.home-scroll::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: 0;
  transition: opacity 0.28s ease, background 0.28s ease;
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 12%, #000 86%, transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0%, #000 12%, #000 86%, transparent 100%);
}
