    linear-gradient(180deg, color-mix(in srgb, var(--primary-color) 42%, rgba(255,255,255,0.72)) 0%, color-mix(in srgb, var(--primary-color) 22%, rgba(255,255,255,0.36)) 34%, transparent 82%),
