  font-size: clamp(1.22rem, 5.4vw, 1.5rem); font-weight: 800; color: var(--font-color);
  opacity: 0.72; margin: 0; letter-spacing: 0;
  line-height: 1.08;
}
/* ── Inline Rhema search: a magnifier beside the name that spins open ── */
.home-greeting-name-row {
  display: flex; align-items: center; gap: 10px;
  min-height: 40px;
}
.home-greeting-name-row .home-greeting-name { flex-shrink: 0; }
.home-inline-search {
  flex: 1 1 auto; min-width: 0;
  display: flex; justify-content: flex-end;
}
.his-pill {
  display: flex; align-items: center;
  width: 40px; height: 40px;
  border-radius: 999px;
  background: linear-gradient(135deg,
    color-mix(in srgb, var(--card-color) 96%, #fff) 0%,
    color-mix(in srgb, var(--primary-color) 72%, var(--card-color)) 100%);
  border: 1px solid color-mix(in srgb, var(--secondary-color) 16%, rgba(255,255,255,0.72));
  box-shadow: 0 6px 16px rgba(0,0,0,0.05), inset 0 1px 0 rgba(255,255,255,0.85);
  overflow: hidden;
  transition: width 0.45s cubic-bezier(0.32, 0.72, 0.25, 1), box-shadow 0.3s;
}
.home-inline-search.open .his-pill {
  width: 100%;
  box-shadow:
    0 10px 24px rgba(0,0,0,0.07),
    0 0 0 3px color-mix(in srgb, var(--secondary-color) 12%, transparent),
    inset 0 1px 0 rgba(255,255,255,0.9);
}
.his-pill input {
  flex: 1 1 auto; min-width: 0;
  border: 0; outline: none; background: transparent;
  color: var(--font-color);
  font: inherit;
  font-size: clamp(0.78rem, 3.4vw, 0.88rem);
  font-weight: 700;
  padding: 0; /* no width while collapsed so the magnifier stays centered */
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease 0.12s;
}
.home-inline-search.open .his-pill input { opacity: 1; pointer-events: auto; padding-left: 14px; }
.home-inline-search:not(.open) .his-toggle { margin: 0 auto; }
.his-pill input::placeholder {
  color: color-mix(in srgb, var(--muted-color) 74%, transparent);
  font-weight: 600;
}
.his-toggle {
  width: 38px; height: 38px;
  flex-shrink: 0;
  margin-left: auto;
  border: 0; border-radius: 50%;
  background: transparent;
  color: var(--secondary-color);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform 0.5s cubic-bezier(0.34, 1.1, 0.4, 1);
}
.his-toggle .material-symbols-outlined { font-size: 21px; }
.home-inline-search.open .his-toggle { transform: rotate(-360deg); }
.his-toggle.his-pressing {
  animation: homeSearchPop 0.38s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes homeSearchPop {
  0% { transform: scale(1) rotate(0deg); }
  48% { transform: scale(0.84) rotate(-18deg); }
  100% { transform: scale(1) rotate(-360deg); }
}
.home-verse-wrap { margin: 8px 0 22px; }
.home-verse-inner { display: flex; align-items: flex-start; gap: 12px; }
.home-verse-icon {
  flex-shrink: 0; width: 34px; height: 34px; border-radius: 50%;
  background: var(--primary-color);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 2px 8px rgba(0,0,0,0.09); margin-top: 2px;
}
.home-verse-quote {
  font-size: 1.35rem; line-height: 1; color: var(--secondary-color);
  font-family: Georgia, 'Times New Roman', serif; font-weight: 700;
  user-select: none; margin-top: -2px;
}
.home-verse-body { flex: 1; min-width: 0; }
.home-verse-text { font-size: 0.98rem; color: var(--font-color); margin: 0 0 7px; line-height: 1.7; opacity: 0.85; }
.home-verse-ref { font-size: 0.86rem; font-weight: 600; color: var(--secondary-color); display: block; }

/* ── Home verse/snippet letter-flip animation ─────────────────────────────── */
.hv-ch { display: inline-block; }
.hv-ch--out   { animation: hv-ch-out   0.22s ease-in forwards; }
.hv-ch--in    { animation: hv-ch-in    0.44s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
.hv-ch--exit  { animation: hv-ch-exit  0.46s ease-in forwards; }
.hv-ch--enter { animation: hv-ch-enter 0.46s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
@keyframes hv-ch-out {
  to { transform: scaleY(0.05) translateY(2px); opacity: 0; }
}
@keyframes hv-ch-in {
  from { transform: scaleY(0.05) translateY(2px); opacity: 0; }
  18%  { opacity: 1; }
  to   { transform: none; opacity: 1; }
}
@keyframes hv-ch-exit {
  0%  { transform: none; opacity: 1; }
  38% { transform: scale(1.25) translateY(-8px); opacity: 0.85; }
  to  { transform: scale(0) translateY(-18px); opacity: 0; }
}
@keyframes hv-ch-enter {
  from { transform: scale(0) translateY(-14px); opacity: 0; }
  18%  { opacity: 1; }
  to   { transform: none; opacity: 1; }
}

/* Continue Reading card — the home Rhema widget */
.home-continue-card {
  position: relative; overflow: hidden;
  border-radius: 22px;
  padding: 18px 18px 14px;
  color: #fff;
  cursor: pointer;
  margin-bottom: 24px;
  background:
    radial-gradient(130% 170% at 100% 0%,
      color-mix(in srgb, var(--accent-color, var(--secondary-color)) 50%, transparent),
      transparent 56%),
    linear-gradient(135deg,
      color-mix(in srgb, var(--secondary-color) 94%, #0b1226) 0%,
      color-mix(in srgb, var(--secondary-color) 62%, #0b1226) 100%);
  box-shadow:
    0 14px 32px color-mix(in srgb, var(--secondary-color) 32%, rgba(0,0,0,0.16)),
    inset 0 1px 0 rgba(255,255,255,0.28);
  transition: transform 0.12s, box-shadow 0.12s;
}
.home-continue-card::after { /* soft page-edge sheen along the bottom */
