/* ── Profile Page ────────────────────────────────────────────────────────── */
#profilePage .nav-bar {
  background: var(--primary-color); z-index: 10; flex-shrink: 0;
  padding-top: max(10px, env(safe-area-inset-top));
  /* Pull the gear + home buttons in from the very edges of the screen */
  padding-left: 18px;
  padding-right: 18px;
  box-shadow: none;
}
#profilePage .nav-bar > div:first-child { display: flex; justify-content: flex-start; }
#profilePage .nav-bar > div:last-child { display: flex; justify-content: flex-end; }
.prof-nav-icon {
  width: 40px;
  height: 40px;
  display: inline-grid;
  place-items: center;
  border: none;
  border-radius: 12px;
  background: transparent;
  color: var(--secondary-color);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  /* No resting elevation/outline — the buttons are completely flat until pressed */
  box-shadow: none;
  filter: none;
  outline: none;
  transition: transform 0.12s ease, background 0.12s ease;
}
.prof-nav-icon:focus,
.prof-nav-icon:focus-visible {
  outline: none;
  box-shadow: none;
}
.prof-nav-icon:active {
  transform: scale(0.92);
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
}
.prof-nav-icon .material-symbols-outlined { font-size: 23px; }
/* legacy alias kept flat in case any cached markup references it */
.profile-home-btn {
  width: 40px; height: 40px; display: inline-grid; place-items: center;
  border: none; background: transparent; color: var(--secondary-color);
  border-radius: 12px; cursor: pointer; box-shadow: none;
}
.profile-home-btn .material-symbols-outlined { font-size: 23px; }
.profile-page-scroll {
  overflow-y: auto; overflow-x: hidden;
  flex: 1 1 0; min-height: 0;
  padding: 0 16px calc(0px + 80px);
  overscroll-behavior-y: contain;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  -webkit-tap-highlight-color: transparent;
  /* No reserved scrollbar gutter / visible scrollbar — that strip read as a
     "shadow" down the right edge of the profile screen. The desktop scrollbar
     theming paints a --primary-color track, so we must override it explicitly. */
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}
.profile-page-scroll::-webkit-scrollbar,
.profile-page-scroll::-webkit-scrollbar-track,
.profile-page-scroll::-webkit-scrollbar-thumb,
.profile-page-scroll::-webkit-scrollbar-corner {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
  background: transparent !important;
}
.profile-page-scroll .profile-card { box-shadow: none; border-radius: 0; background: transparent; padding: 0; max-height: none; overflow: visible; }


