.notif-sub { font-size: 0.78rem; color: var(--muted-color); margin-top: 2px; }
.notif-time { font-size: 0.7rem; color: var(--muted-color); margin-top: 2px; }
.notif-unread-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--secondary-color); flex-shrink: 0; margin-top: 6px; }
