.notif-fr-actions { display: flex; gap: 8px; margin-top: 8px; }
.notif-accept-btn, .notif-deny-btn {
  padding: 5px 16px; border-radius: 999px; font-size: 0.8rem; font-weight: 700;
  border: none; cursor: pointer; transition: opacity 0.15s;
}
.notif-accept-btn { background: var(--secondary-color); color: #fff; }
.notif-deny-btn { background: transparent; border: 1.5px solid var(--border-color); color: var(--muted-color); }
.notif-accept-btn:active, .notif-deny-btn:active { opacity: 0.7; }
.notif-x-btn {
  flex-shrink: 0;
  background: none;
  border: none;
