}
.notif-x-btn:hover { opacity: 1; background: color-mix(in srgb, var(--font-color) 10%, transparent); }
.notif-x-btn .material-symbols-outlined { font-size: 16px !important; }

/* ── Community page ───────────────────────────────────────────────────────── */
.comm-scroll {
  flex: 1; overflow-y: auto; -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}
.comm-hero {
  display: flex; align-items: center; justify-content: space-between;
  padding: calc(env(safe-area-inset-top, 0px) + 20px) 20px 14px;
  gap: 12px;
}
.comm-hero-text { flex: 1; min-width: 0; }
.comm-hero-title { font-size: 1.55rem; font-weight: 800; color: var(--text-color); margin: 0 0 2px; }
.comm-hero-sub { font-size: 0.8rem; color: var(--muted-color); margin: 0; }
.comm-friends-btn {
  position: relative;
  display: flex; align-items: center; gap: 6px;
  padding: 8px 14px 8px 12px;
  background: var(--card-color);
  border: 1.5px solid var(--border-color);
  border-radius: 999px;
  font-size: 0.82rem; font-weight: 700; color: var(--text-color);
  cursor: pointer; flex-shrink: 0;
  transition: transform 0.15s, background 0.15s;
}
.comm-friends-btn:active { transform: scale(0.95); background: var(--border-color); }
.comm-friends-btn .material-symbols-outlined { font-size: 18px; color: var(--secondary-color); }
.comm-tabs { padding: 0 16px; }
.comm-friends-badge {
  position: absolute; top: -5px; right: -5px;
  min-width: 18px; height: 18px; padding: 0 4px;
  border-radius: 999px; background: #ef4444; color: #fff;
  font-size: 0.68rem; font-weight: 900;
  display: flex; align-items: center; justify-content: center;
  border: 2px solid var(--primary-color);
  box-shadow: 0 0 0 2px rgba(239,68,68,0.3);
  animation: notif-pulse 2s ease-in-out infinite;
}
.comm-friends-badge.hidden { display: none; }

/* ── Personal Studies ──────────────────────────────────────────────────────── */

/* Home screen studies section */
.home-studies-section {
  margin: 12px 0 4px;
}
.home-studies-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2px;
  margin-bottom: 10px;
}
.hs-view-all-btn {
  font-size: 0.78rem; font-weight: 600;
  color: #4f8cff;
  background: none; border: none;
  cursor: pointer; padding: 0 4px;
}
/* ── Habit Builder home widget ── */
.home-habit-widget,
.home-journey-widget {
  position: relative;
  overflow: hidden;
  margin: 2px 0 8px;
  min-height: 80px;
  padding: 10px min(42vw, 150px) 10px 16px;
  border-radius: 20px;
  border: 1.5px solid color-mix(in srgb, var(--secondary-color) 24%, var(--border-color));
  background:
    radial-gradient(120% 150% at 100% 100%, color-mix(in srgb, var(--secondary-color) 16%, transparent), transparent 55%),
    linear-gradient(160deg, color-mix(in srgb, var(--secondary-color) 10%, var(--card-color)), var(--card-color) 72%);
  box-shadow: 0 10px 24px color-mix(in srgb, var(--secondary-color) 12%, transparent);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transform-origin: center;
  transition: transform 0.16s cubic-bezier(.2, .85, .25, 1), box-shadow 0.16s ease, filter 0.16s ease;
}
.home-journey-widget {
  margin-top: -2px;
  min-height: 80px;
  padding-right: min(47vw, 168px);
  border-color: color-mix(in srgb, var(--secondary-color) 22%, var(--border-color));
  background:
    radial-gradient(110% 130% at 100% 100%, color-mix(in srgb, var(--secondary-color) 18%, transparent), transparent 58%),
    linear-gradient(160deg, color-mix(in srgb, var(--secondary-color) 8%, var(--card-color)), var(--card-color) 74%);
}
.home-habit-widget::after,
.home-journey-widget::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, var(--card-color) 0%, color-mix(in srgb, var(--card-color) 88%, transparent) 42%, transparent 72%),
    radial-gradient(80% 95% at 88% 52%, color-mix(in srgb, var(--secondary-color) 18%, transparent), transparent 72%);
  pointer-events: none;
  z-index: 1;
}
.home-journey-widget::after {
  background:
    linear-gradient(90deg, var(--card-color) 0%, color-mix(in srgb, var(--card-color) 84%, transparent) 43%, transparent 72%),
    radial-gradient(80% 95% at 91% 58%, color-mix(in srgb, var(--secondary-color) 22%, transparent), transparent 74%);
}
.hhw-main {
  position: relative;
  z-index: 2;
}
.hjw-main {
  position: relative;
  z-index: 2;
  max-width: min(56vw, 230px);
}
.home-habit-widget:active,
.home-journey-widget:active {
  animation: home-press-pop 0.34s cubic-bezier(.2, .9, .2, 1);
  box-shadow: 0 8px 18px color-mix(in srgb, var(--secondary-color) 16%, transparent);
  filter: saturate(1.04);
}
.hhw-kicker {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 0.68rem; font-weight: 800;
  letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--secondary-color);
}
.hhw-sprout { width: 16px; height: 16px; flex-shrink: 0; }
.hjw-kicker .material-symbols-outlined {
  font-size: 17px !important;
  line-height: 1;
  color: var(--secondary-color);
}
.hhw-headline {
  margin: 6px 0 2px;
  font-size: 1.06rem; font-weight: 800;
  color: var(--font-color);
  line-height: 1.25;
}
.hhw-sub {
  margin: 0 0 10px;
  font-size: 0.78rem;
  color: var(--muted-color);
  line-height: 1.45;
}
.hhw-progress { display: flex; align-items: center; gap: 8px; }
.hhw-bar {
  flex: 1;
  height: 8px;
  border-radius: 99px;
  background: color-mix(in srgb, var(--secondary-color) 14%, var(--border-color));
  overflow: hidden;
}
.hhw-bar span {
  display: block; height: 100%;
  border-radius: 99px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--secondary-color) 70%, #fff), var(--secondary-color));
  transition: width 0.4s ease;
}
.hhw-count { font-size: 0.74rem; font-weight: 800; color: var(--secondary-color); }
.hhw-art,
.hjw-art {
  position: absolute;
  right: -44px;
  top: 0;
  bottom: 0;
  width: min(64vw, 248px);
  border-radius: 26px;
  overflow: hidden;
  background:
    radial-gradient(100% 86% at 50% 12%, rgba(255,255,255,0.72), transparent 64%),
    color-mix(in srgb, var(--secondary-color) 9%, rgba(255,255,255,0.54));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.82),
    0 12px 24px color-mix(in srgb, var(--secondary-color) 14%, transparent);
  pointer-events: none;
  z-index: 0;
  isolation: isolate; /* contain the color-tint blend to this artwork only */
}
.hjw-art {
  right: -12px;
  width: min(68vw, 272px);
  border-radius: 24px;
  background:
    radial-gradient(100% 86% at 58% 12%, rgba(255,255,255,0.66), transparent 64%),
    color-mix(in srgb, var(--secondary-color) 10%, rgba(255,255,255,0.48));
}
.hhw-art::after,
.hjw-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--card-color) 72%, transparent), transparent 36%),
    radial-gradient(80% 100% at 78% 40%, color-mix(in srgb, var(--secondary-color) 18%, transparent), transparent 72%);
  mix-blend-mode: soft-light;
  pointer-events: none;
}
.hjw-art::after {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--card-color) 66%, transparent), transparent 34%),
    radial-gradient(90% 100% at 82% 54%, color-mix(in srgb, var(--secondary-color) 24%, transparent), transparent 72%);
}
.hhw-art img,
.hjw-art img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 58% 50%;
  opacity: 0.9;
  filter: saturate(1.08) contrast(1.03);
  mix-blend-mode: normal;
}
.hjw-art img {
  object-position: 62% 26%;
  opacity: 0.9;
  filter: saturate(1.08) contrast(1.03);
}
.hjw-art-tint {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: var(--secondary-color);
  mix-blend-mode: color;
}
.hjw-arrow {
  position: absolute;
  right: 16px;
  bottom: 16px;
  z-index: 3;
  width: 42px;
  height: 42px;
  display: grid !important;
  place-items: center;
  border-radius: 999px;
  color: var(--secondary-color);
  background: color-mix(in srgb, var(--card-color) 88%, rgba(255,255,255,0.88));
  box-shadow:
    0 10px 22px color-mix(in srgb, var(--secondary-color) 14%, rgba(15,23,42,0.1)),
    inset 0 1px 0 rgba(255,255,255,0.82);
}

/* ── Studies bookshelf ── */
.hs-shelf-unit { position: relative; }
.hs-shelf-unit.hs-has-books::before { /* recessed alcove behind the books */
  content: '';
  position: absolute;
  inset: -8px -10px 13px;
  border-radius: 14px;
  background: linear-gradient(180deg,
    rgba(72, 50, 28, 0.12),
    rgba(72, 50, 28, 0.03) 38%,
    rgba(72, 50, 28, 0.15));
  box-shadow:
    inset 0 14px 22px -16px rgba(46, 30, 14, 0.65),
    inset 0 -8px 12px -10px rgba(46, 30, 14, 0.4),
    inset 8px 0 14px -12px rgba(46, 30, 14, 0.4),
    inset -8px 0 14px -12px rgba(46, 30, 14, 0.4);
  pointer-events: none;
}
.hs-shelf {
  position: relative;
  display: flex;
  align-items: flex-end;
  gap: 12px;
  padding: 14px 10px 0;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
}
.hs-shelf::-webkit-scrollbar { display: none; }
.hs-shelf-plank { /* the wooden board the books stand on */
  position: relative;
  z-index: 2;
  height: 17px;
  margin: -1px -4px 0;
  border-radius: 2px 2px 8px 8px;
  background:
    repeating-linear-gradient(92deg,
      rgba(96, 64, 30, 0.13) 0 16px,
      rgba(0, 0, 0, 0) 16px 41px),
    linear-gradient(180deg,
      #d2a76e 0%, #c0905a 26%,
      #93653a 30%, #7c5128 78%, #6b4520 100%);
  box-shadow:
    0 6px 12px rgba(60, 40, 18, 0.35),
    0 1px 2px rgba(60, 40, 18, 0.4),
    inset 0 1px 0 rgba(255, 233, 195, 0.55),
    inset 0 -1px 0 rgba(40, 24, 10, 0.45);
}
.hs-shelf-unit:not(.hs-has-books) .hs-shelf-plank { display: none; }
.hs-start-btn {
  flex: 1;
  display: flex; align-items: center; gap: 8px;
  padding: 14px 16px;
  background: var(--card-color);
  border: 1.5px dashed var(--border-color);
  border-radius: 16px;
  color: var(--muted-color);
  font-size: 0.9rem; font-weight: 600;
  cursor: pointer;
}
.hs-start-btn .material-symbols-outlined { font-size: 20px; color: var(--secondary-color); }
.hs-book {
  position: relative;
  z-index: 1;
  width: 94px;
  height: 140px;
  flex-shrink: 0;
  border-radius: 8px 10px 12px 8px;
  background: color-mix(in srgb, var(--study-color, #4f8cff) 82%, #cfe3ff);
  box-shadow:
    0 13px 12px -8px color-mix(in srgb, var(--study-color, #4f8cff) 36%, rgba(40, 26, 12, 0.55)),
    0 4px 10px color-mix(in srgb, var(--study-color, #4f8cff) 18%, transparent);
  display: flex; flex-direction: column; align-items: center;
  gap: 4px;
  padding: 22px 10px 12px;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  transform: rotate(var(--shelf-lean, 0deg));
  transform-origin: 50% 100%;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  isolation: isolate;
  overflow: visible;
}
/* Slightly varied heights so the shelf reads like real books */
.hs-book:nth-child(3n) { height: 132px; }
.hs-book:nth-child(3n+2) { height: 146px; }
.hs-book::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  z-index: -2;
  background:
    linear-gradient(var(--study-color, #4f8cff), var(--study-color, #4f8cff)),
    url("assets/icons/study-book-cover.png?v=3.0.241") center 48% / 156% auto no-repeat;
  background-blend-mode: color, normal;
  filter: saturate(1.08) contrast(1.04);
  pointer-events: none;
}
.hs-book::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background:
    linear-gradient(90deg, rgba(0,0,0,0.34) 0 12%, rgba(255,255,255,0.20) 14%, transparent 26%, rgba(255,255,255,0.16) 56%, rgba(0,0,0,0.08)),
    radial-gradient(88% 46% at 50% 8%, rgba(255,255,255,0.24), transparent 64%);
  mix-blend-mode: soft-light;
  pointer-events: none;
}
.hs-book:active { transform: translateY(-6px) rotate(var(--shelf-lean, 0deg)); }
.hs-book.jiggle { animation: hs-jiggle 0.2s ease-in-out infinite; cursor: default; }
.hs-book-ghost { opacity: 0; }
.hs-book-icon {
  font-size: 20px;
  color: color-mix(in srgb, var(--study-color, #4f8cff) 52%, #17233c);
  text-shadow: 0 1px 0 rgba(255,255,255,0.58);
  position: relative;
  z-index: 2;
}
.hs-book-title { /* gilt-ruled title panel */
  width: 100%;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 0.72rem;
  font-weight: 850;
  color: color-mix(in srgb, var(--study-color, #4f8cff) 34%, #14233c);
  text-align: center;
  line-height: 1.3;
  letter-spacing: 0.01em;
  padding: 6px 2px;
  border: 1px solid color-mix(in srgb, var(--study-color, #4f8cff) 18%, rgba(255,255,255,0.62));
  border-radius: 7px;
  background: rgba(255,255,255,0.34);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.54);
  text-shadow: 0 1px 0 rgba(255,255,255,0.5);
  overflow-wrap: anywhere;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  position: relative;
  z-index: 2;
}
.hs-book-foot {
  margin-top: auto;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  position: relative;
  z-index: 2;
}
.hs-book-meta {
  font-size: 0.55rem; font-weight: 700;
  color: color-mix(in srgb, var(--study-color, #4f8cff) 42%, #1e2d46);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-shadow: 0 1px 0 rgba(255,255,255,0.45);
}
.hs-book .hs-member-stack { min-height: 18px; margin: 0; }
.hs-book .hs-member-avatar {
  width: 18px; height: 18px;
  border-color: rgba(247, 238, 216, 0.8);
}
.hs-book .hs-member-avatar .material-symbols-outlined { font-size: 12px !important; }
.hs-book .study-card-done-dot {
  border: 1.5px solid rgba(247, 238, 216, 0.9);
  width: 10px; height: 10px;
}
.hs-add-book { /* slim ghost book waiting to be written */
  position: relative;
  z-index: 1;
  width: 46px;
  height: 126px;
  flex-shrink: 0;
  border: 1.6px dashed color-mix(in srgb, var(--secondary-color) 45%, var(--border-color));
  border-radius: 2px 7px 7px 2px;
  background: color-mix(in srgb, var(--secondary-color) 5%, transparent);
  display: flex; flex-direction: column; align-items: center;
  gap: 8px;
  padding: 13px 0 10px;
  color: var(--secondary-color);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transform: rotate(var(--shelf-lean, 0deg));
  transform-origin: 50% 100%;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.hs-add-book:active { transform: translateY(-5px) rotate(var(--shelf-lean, 0deg)); }
.hs-add-book .material-symbols-outlined { font-size: 18px; }
.hs-add-book span:last-child { /* reads down the spine */
  writing-mode: vertical-rl;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.14em;
}
/* Long titles shrink so the full study name always fits on the cover */
.hs-book-title-sm { font-size: 0.63rem !important; -webkit-line-clamp: 5 !important; }
.hs-book-title-xs { font-size: 0.55rem !important; letter-spacing: 0 !important; -webkit-line-clamp: 7 !important; }
.hs-book-info {
  position: absolute; top: 5px; right: 5px; z-index: 3;
  width: 21px; height: 21px;
  border: 0; border-radius: 50%;
  background: rgba(0, 0, 0, 0.22);
  color: rgba(247, 238, 216, 0.85);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.hs-book-info .material-symbols-outlined { font-size: 13px; }
.hs-book .study-card-done-dot { left: 8px; right: auto; }

/* ── Study Library (full-screen bookcase from Quick Actions) ── */
.study-library {
  position: fixed; inset: 0;
  z-index: 940; /* above the bottom nav (900), below the study sandbox (950) */
  background: var(--primary-color);
  display: flex; flex-direction: column;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 0.24s ease, transform 0.24s ease;
}
.study-library.open { opacity: 1; transform: translateY(0); }
.study-library.hidden { display: none; }
.sl-header {
  display: flex; align-items: center; gap: 12px;
  padding: calc(env(safe-area-inset-top, 0px) + 14px) 16px 12px;
  background: var(--card-color);
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.sl-back-btn {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--border-color);
  background: var(--primary-color);
  color: var(--font-color);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; flex-shrink: 0;
  -webkit-tap-highlight-color: transparent;
}
.sl-title-wrap { flex: 1; min-width: 0; }
.sl-title {
  margin: 0;
  font-size: 1.15rem; font-weight: 800;
  color: var(--font-color);
}
.sl-count {
  display: block;
  font-size: 0.72rem; font-weight: 600;
  color: var(--muted-color);
}
.sl-done-btn {
  border: none; background: none;
  font-size: 0.85rem; font-weight: 700;
  color: var(--secondary-color);
  cursor: pointer; padding: 6px 4px;
}
.sl-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden; /* the shelf fills one screen; only book rows scroll */
  -webkit-overflow-scrolling: touch;
  padding: 0 0 calc(0px);
  /* clean, theme-matched room behind the shelf */
  background:
    radial-gradient(130% 60% at 50% 0%, color-mix(in srgb, var(--secondary-color) 10%, transparent), transparent 62%),
    linear-gradient(180deg, var(--primary-light) 0%, var(--primary-color) 100%);
}
body.dark .sl-body {
  background:
    radial-gradient(130% 60% at 50% 0%, color-mix(in srgb, var(--secondary-color) 16%, transparent), transparent 62%),
    linear-gradient(180deg, #1f2937 0%, #111827 100%);
}

/* The bookcase is a 3D shelf illustration that fills the whole page below the
   header; study books sit on its two empty middle shelves. The image stretches
   to fill so the shelves are large enough to hold the books naturally.
   Geometry is tunable via the CSS variables below. */
.sl-bookcase {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  max-width: none;     /* fill the full width of the screen */
  margin: 0 auto;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: url("assets/icons/studies-bookshelf.png?v=3.0.238") center / 108% 104% no-repeat;
  box-shadow: none;
  isolation: isolate; /* contain the theme tint to the shelf image */
  /* shelf geometry as fractions of the image */
  --sl-inset: 8%;
  --sl-rowA-top: 31%;
  --sl-rowA-h: 18.5%;   /* book bottoms land on the middle shelf board */
  --sl-rowB-top: 52%;
  --sl-rowB-h: 18.5%;   /* book bottoms land on the lower shelf board */
}
.sl-bookcase::before,
.sl-bookcase::after { content: none !important; display: none !important; }

/* recolor the shelf image to the selected theme (keeps shading, takes hue) */
.sl-shelf-tint {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: var(--secondary-color);
  mix-blend-mode: color;
  z-index: 0;
}

.sl-shelf-row {
  position: absolute;
  left: var(--sl-inset);
  right: var(--sl-inset);
  z-index: 1;
}
.sl-shelf-row-a { top: var(--sl-rowA-top); height: var(--sl-rowA-h); }
.sl-shelf-row-b { top: var(--sl-rowB-top); height: var(--sl-rowB-h); }
.sl-img-shelf {
  height: 100%;
  display: flex;
  align-items: flex-end;       /* books rest on the shelf board */
  justify-content: flex-start;
  gap: 6px;
  padding: 0 4px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  min-height: 0;
}
.sl-img-shelf::-webkit-scrollbar { display: none; }
.sl-img-shelf .hs-book {
  flex: 0 0 auto;
  width: auto;
  height: 88%;
  aspect-ratio: 0.6 / 1;
  min-width: 0;
  margin: 0 0 3px;
}
.sl-img-shelf .hs-book:nth-child(3n),
.sl-img-shelf .hs-book:nth-child(3n+2) { height: 88%; }
.sl-img-shelf .hs-book-icon { font-size: 0.95rem; }
.sl-img-shelf .hs-book-title { font-size: 0.48rem; padding: 2px 1px; -webkit-line-clamp: 3; }
.sl-img-shelf .hs-book-foot { display: none; }
