/* ── Study book opening animation ──
   Phases driven from _animateStudyBookOpen():
   lift (book flies off the shelf to center) → open (cover swings) →
   dive (zoom into the pages) → fade-out (reveal the loaded study). */
.book-open-overlay {
  position: fixed; inset: 0;
  z-index: 7000;
  background: rgba(10, 14, 22, 0);
  perspective: 1400px;
  transition: background 0.45s ease, opacity 0.26s ease;
}
.book-open-overlay.lift { background: rgba(10, 14, 22, 0.5); }
.book-open-overlay.dive { background: var(--primary-color); }
.book-open-overlay.fade-out { opacity: 0; }
.book-fly {
  position: fixed;
  transform-style: preserve-3d;
  transition: transform 0.46s cubic-bezier(0.24, 0.9, 0.34, 1.08);
  will-change: transform;
}
.book-fly::after {
  content: "";
  position: absolute;
  left: -1px;
  top: 1px;
  bottom: 1px;
  width: 13%;
  border-radius: 8px 3px 3px 8px;
  background:
    linear-gradient(90deg,
      color-mix(in srgb, var(--study-color, #4f8cff) 62%, #24324d),
      color-mix(in srgb, var(--study-color, #4f8cff) 78%, #dce9ff) 58%,
      color-mix(in srgb, var(--study-color, #4f8cff) 50%, #17233c));
  box-shadow:
    inset -2px 0 4px rgba(0,0,0,0.18),
    2px 0 5px rgba(0,0,0,0.08);
  transform: translateZ(3px);
  pointer-events: none;
  z-index: 4;
}
.book-open-overlay.dive .book-fly {
  transition: transform 0.52s cubic-bezier(0.6, 0, 0.85, 0.4);
}
.book-page {
  position: absolute;
  inset: 2px 2px 2px 5px;
  border-radius: 8px 10px 12px 8px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--study-color, #4f8cff) 10%, rgba(0,0,0,0.10)), transparent 16%),
    repeating-linear-gradient(180deg, transparent 0 14px, rgba(120,100,60,0.10) 14px 15px),
    #fbf6ea;
  box-shadow: inset 0 0 16px rgba(0,0,0,0.08);
  opacity: 0;
  transition: opacity 0.18s ease 0.18s;
}
.book-fly.open .book-page,
.book-open-overlay.dive .book-page {
  opacity: 1;
}
.book-cover {
  position: absolute; inset: 0;
  transform-origin: left center;
  transform-style: preserve-3d;
  transition: transform 0.55s cubic-bezier(0.32, 0.72, 0.28, 1);
  z-index: 5;
}
.book-fly.open .book-cover { transform: rotateY(-150deg); }
/* During the dive the cover settles fully open and flat — the left page
   stays visible until the whole overlay fades at the end. */
.book-open-overlay.dive .book-cover { transform: rotateY(-178deg); }
.book-cover-front,
.book-cover-back {
  position: absolute; inset: 0;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.book-cover-front {
  border-radius: 8px 10px 12px 8px;
  background:
    linear-gradient(var(--study-color, #4f8cff), var(--study-color, #4f8cff)),
    url("assets/icons/study-book-cover.png?v=3.0.241") center 48% / 156% auto no-repeat,
    color-mix(in srgb, var(--study-color, #4f8cff) 82%, #cfe3ff);
  background-blend-mode: color, normal, normal;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.35),
    inset 10px 0 14px rgba(0,0,0,0.08);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 6px;
  padding: 10px;
}
.book-cover-front .material-symbols-outlined {
  font-size: 22px;
  color: color-mix(in srgb, var(--study-color, #4f8cff) 52%, #17233c);
  text-shadow: 0 1px 0 rgba(255,255,255,0.58);
  transition: opacity 0.16s ease;
}
.book-cover-title {
  width: 100%;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 0.72rem; font-weight: 700;
  color: color-mix(in srgb, var(--study-color, #4f8cff) 34%, #14233c); text-align: center; line-height: 1.3;
  padding: 6px 1px;
  border: 1px solid color-mix(in srgb, var(--study-color, #4f8cff) 18%, rgba(255,255,255,0.62));
  border-radius: 7px;
  background: rgba(255,255,255,0.34);
  text-shadow: 0 1px 0 rgba(255,255,255,0.5);
  overflow-wrap: anywhere;
  transition: opacity 0.16s ease;
}
/* Fade the cover lettering out as the cover starts swinging, so the title
   never shows clipped/mirrored along the opening edge. */
.book-fly.open .book-cover-front .material-symbols-outlined,
.book-fly.open .book-cover-title { opacity: 0; }
.book-cover-back {
  transform: rotateY(180deg);
  inset: 1px 0 1px 1px;
  border-radius: 8px 10px 12px 8px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--study-color, #4f8cff) 10%, #e9dfcd), #f4eddd);
  box-shadow: inset 8px 0 12px rgba(0,0,0,0.08);
}
.hs-delete-btn {
  position: absolute; top: -12px; right: -12px; z-index: 20;
  width: 24px; height: 24px; border-radius: 50%;
