  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-color);
  transition: border-color 0.15s, background 0.15s, color 0.15s;
}

.study-icon-btn .material-symbols-outlined { font-size: 20px; }

.study-icon-btn.selected {
