}

.study-share-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background: var(--primary-color);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  margin-bottom: 20px;
  gap: 12px;
}

.study-share-label {
  font-size: 0.9rem;
  color: var(--text-color);
  font-weight: 500;
  flex: 1;
}

.study-share-label small {
  display: block;
  font-size: 0.75rem;
