}

.study-invite-friend-btn.invited .study-invite-friend-check {
  color: var(--accent-color);
}

.study-session-btn {
  width: 100%;
  padding: 14px;
  border-radius: 16px;
  border: none;
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
  margin-bottom: 10px;
  background: var(--study-session-color, #4f8cff);
  transition: opacity 0.15s;
}

.study-session-btn:active { opacity: 0.85; }

.study-session-btn.done {
  background: #22c55e;
  cursor: default;
}

.study-session-delete-btn {
  width: 100%;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid rgba(239,68,68,0.3);
  background: transparent;
  font-size: 0.88rem;
  font-weight: 600;
  color: #ef4444;
  cursor: pointer;
}

/* ── Study Sandbox ─────────────────────────────────────────────────────────── */
.study-sandbox {
  position: fixed; inset: 0; z-index: 950;
  background: var(--primary-color);
  display: flex; flex-direction: column;
}
.study-sandbox.hidden { display: none; }

.ss-header {
  display: flex; align-items: center; gap: 10px;
  padding: calc(env(safe-area-inset-top, 44px) + 12px) 16px 12px;
  background: var(--card-color);
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.ss-back-btn {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--border-color);
  background: var(--primary-color);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; flex-shrink: 0;
}
.ss-back-btn .material-symbols-outlined { font-size: 20px; color: var(--font-color); }
.ss-title-wrap { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; }
.ss-icon { font-size: 22px; }
.ss-title { font-size: 1rem; font-weight: 700; color: var(--text-color); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ss-members {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 28%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
  color: var(--secondary-color);
  padding: 5px 9px;
  font: inherit;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
}
.ss-members::after {
  content: "›";
  font-size: 0.9rem;
  line-height: 1;
  transform: translateY(-1px);
}
.ss-members:active { transform: scale(0.97); }

.ss-tabs {
  display: flex; gap: 0;
  background: var(--card-color);
  border-top: 1px solid var(--border-color);
  flex-shrink: 0;
  padding-bottom: env(safe-area-inset-bottom, 0px);
}

/* Study tab bar — fixed at bottom, in root stacking context, always above Rhema modal */
#studyTabBar {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  z-index: 1100;
  transform: translateY(0);
  opacity: 1;
  transition: opacity 0.22s ease, transform 0.24s cubic-bezier(.2,.82,.18,1);
}
#studyTabBar.hidden { display: none; }
body.sandbox-open.rhema-chrome-hidden #studyTabBar {
  opacity: 0;
  transform: translateY(calc(100% + env(safe-area-inset-bottom, 0px)));
  pointer-events: none;
}

/* Push sandbox pane content up so nothing hides behind the fixed tab bar */
body.sandbox-open .ss-pane {
  bottom: calc(56px + env(safe-area-inset-bottom, 0px)) !important;
}

/* Shrink the Rhema modal to stop above the study tab bar — all children adapt automatically */
body.sandbox-open #rhemaModal {
  bottom: calc(56px + env(safe-area-inset-bottom, 0px));
  transition: bottom 0.24s cubic-bezier(.2,.82,.18,1);
}

body.sandbox-open.rhema-chrome-hidden #rhemaModal {
  bottom: 0;
}

body.sandbox-open #rhemaModal .rhema-picker {
  padding-top: 18px;
  padding-bottom: 14px;
}

/* Extra bottom padding so long verses can scroll clear of the floating prev/next arrows.
   Arrows sit 12px above the modal bottom and are 44px tall → need ~70px+ of clearance. */
body.sandbox-open .rhema-verse-display,
body.sandbox-open .rhema-english-display {
  padding-bottom: 80px;
}

.ss-tab {
  flex: 1; padding: 10px 4px 8px;
  background: none; border: none; border-top: 2px solid transparent;
  font-size: 0.68rem; font-weight: 600; color: var(--muted-color);
  cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 3px;
  transition: color 0.15s, border-color 0.15s;
}
.ss-tab-icon { font-size: 22px; }
.ss-tab.active { color: var(--secondary-color); border-top-color: var(--secondary-color); }

.ss-body { flex: 1; overflow: hidden; position: relative; }
.ss-pane {
  position: absolute; inset: 0;
  display: none; flex-direction: column;
  overflow: hidden;
}
.ss-pane.active { display: flex; }

/* Notes pane */
.ss-notes-list {
  flex: 1; overflow-y: auto; padding: 12px 16px;
  display: flex; flex-direction: column; gap: 10px;
  overscroll-behavior: contain;
}
.ss-note-item {
  background: var(--card-color);
  border: 1px solid var(--border-color);
  border-radius: 14px; padding: 12px 14px;
}
.ss-note-header {
  display: flex; align-items: center; gap: 6px; margin-bottom: 6px;
}
.ss-note-author { font-size: 0.78rem; font-weight: 700; color: var(--text-color); flex: 1; }
.ss-note-date { font-size: 0.72rem; color: var(--muted-color); }
.ss-note-del {
  background: none; border: none; cursor: pointer;
  color: var(--muted-color); padding: 0; line-height: 1;
}
.ss-note-del .material-symbols-outlined { font-size: 16px; }
.ss-note-body { font-size: 0.88rem; color: var(--text-color); line-height: 1.5; margin: 0; }

.ss-compose {
  display: flex; gap: 8px; align-items: flex-end;
  padding: 10px 16px calc(env(safe-area-inset-bottom,0px) + 12px);
  border-top: 1px solid var(--border-color);
  background: var(--card-color); flex-shrink: 0;
}
.ss-note-input {
  flex: 1; min-height: 44px; max-height: 120px;
  background: var(--primary-color);
  border: 1px solid var(--border-color); border-radius: 12px;
  padding: 10px 12px; font-size: 0.9rem; color: var(--text-color);
  resize: none; outline: none; overflow-y: auto;
  font-family: inherit;
  overscroll-behavior: contain;
}
.ss-send-btn {
  width: 44px; height: 44px; border-radius: 50%; border: none;
  background: var(--secondary-color); color: #fff;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; flex-shrink: 0;
}
.ss-send-btn .material-symbols-outlined { font-size: 20px; }

/* Saved Verses pane */
.ss-hint {
  font-size: 0.82rem; color: var(--muted-color);
  padding: 12px 16px 0; margin: 0;
}
.ss-subtabs {
  display: flex;
  gap: 6px;
  padding: 10px 16px 0;
  flex-shrink: 0;
}
.ss-subtab {
  flex: 1;
  height: 36px;
  border-radius: 10px;
  border: 1px solid var(--border-color);
  background: var(--card-color);
  color: var(--muted-color);
  font-size: 0.78rem;
  font-weight: 800;
  cursor: pointer;
}
.ss-subtab.active {
  border-color: color-mix(in srgb, var(--secondary-color) 42%, var(--border-color));
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
  color: var(--secondary-color);
}
.ss-verse-pane {
  display: none;
  flex: 1;
  min-height: 0;
  position: relative;
  flex-direction: column;
}
.ss-verse-pane.active { display: flex; }
.ss-verses-list { flex: 1; overflow-y: auto; padding: 8px 16px 16px; display: flex; flex-direction: column; gap: 6px; overscroll-behavior: contain; }
.ss-verse-item {
  display: flex; align-items: center; gap: 8px;
  background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 12px; padding: 10px 12px;
}
.ss-verse-ref {
  flex: 1; text-align: left; background: none; border: none;
  font-size: 0.9rem; font-weight: 600; color: var(--secondary-color); cursor: pointer;
}
.ss-verse-del {
  background: none; border: none; cursor: pointer;
  color: var(--muted-color); padding: 0;
}
.ss-verse-del .material-symbols-outlined { font-size: 18px; }
.ss-structure-item .ss-verse-ref {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ss-structure-title {
  font-size: 0.9rem;
  font-weight: 800;
  color: var(--font-color);
}
.ss-structure-meta {
  min-height: 1em;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--muted-color);
}
.ss-structured-add {
  position: absolute;
  right: 18px;
  bottom: 18px;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  border: 0;
  background: var(--secondary-color);
  color: #fff;
  display: grid;
  place-items: center;
  box-shadow: 0 10px 26px rgba(0,0,0,0.22);
  cursor: pointer;
}
.ss-structured-add .material-symbols-outlined { font-size: 1.6rem; line-height: 1; }

.ss-trails-list {
  flex: 1;
  overflow-y: auto;
  padding: 8px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overscroll-behavior: contain;
}
.ss-trail-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  gap: 8px;
  align-items: center;
  padding: 12px;
}
.ss-trail-item > button:first-child {
  min-width: 0;
  border: none;
  background: transparent;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 4px;
  cursor: pointer;
}
.ss-trail-item strong {
  color: var(--text-color);
  font-size: 0.92rem;
}
.ss-trail-item span {
  color: var(--secondary-color);
  font-size: 0.76rem;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ss-trail-item em {
  color: var(--muted-color);
  font-size: 0.72rem;
  font-style: normal;
}
.ss-trail-del {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--muted-color);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.ss-trail-del .material-symbols-outlined { font-size: 18px; }

/* Rhema pane */
.ss-rhema-pane { align-items: center; justify-content: flex-start; gap: 12px; padding: 20px 16px; }
.ss-rhema-position {
  display: flex; align-items: center; gap: 10px;
  background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 14px; padding: 14px 16px; width: 100%;
}
.ss-rhema-position .material-symbols-outlined { font-size: 22px; color: #4f8cff; }
.ss-rhema-position span:last-child { font-size: 0.95rem; font-weight: 600; color: var(--text-color); }

/* Word Log pane */
.ss-wordlog-list { flex: 1; overflow-y: auto; padding: 8px 16px 16px; display: flex; flex-direction: column; gap: 8px; overscroll-behavior: contain; }
.ss-word-item {
  background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 12px; padding: 10px 12px; position: relative;
  -webkit-tap-highlight-color: transparent;
}
.ss-word-tappable { cursor: pointer; transition: opacity 0.12s; }
.ss-word-tappable:active { opacity: 0.65; }
.ss-word-main { display: flex; align-items: baseline; gap: 8px; margin-bottom: 4px; flex-wrap: wrap; }
.ss-word-surface { font-size: 1.05rem; font-weight: 700; color: var(--font-color); letter-spacing: 0.02em; }
.ss-word-lemma { font-size: 0.78rem; color: var(--muted-color); font-style: italic; }
.ss-word-translit { font-size: 0.78rem; color: var(--muted-color); font-style: italic; }
.ss-word-strongs { font-size: 0.72rem; color: #4f8cff; font-weight: 600; }
.ss-word-def { font-size: 0.82rem; color: var(--muted-color); margin: 0; line-height: 1.4; }
.ss-word-del {
  position: absolute; top: 8px; right: 8px;
  background: none; border: none; cursor: pointer; color: var(--muted-color); padding: 0;
}
.ss-word-del .material-symbols-outlined { font-size: 16px; }

/* Add to Word Log button in Rhema word sheet */
.rhema-add-wordlog-btn {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  width: calc(100% - 32px); margin: 8px 16px 0;
  padding: 12px; border-radius: 14px; border: 1.5px solid var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 8%, transparent);
  color: var(--secondary-color);
  font-size: 0.88rem; font-weight: 700; cursor: pointer;
  transition: opacity 0.15s;
}
.rhema-add-wordlog-btn.hidden { display: none; }
.rhema-add-wordlog-btn:disabled { opacity: 0.5; cursor: default; }
.rhema-add-wordlog-btn.logged { opacity: 0.65; }

/* Word detail sheet inside study sandbox */
.ss-wd-backdrop {
  position: absolute; inset: 0; background: rgba(0,0,0,0.4);
  opacity: 0; pointer-events: none; transition: opacity 0.25s; z-index: 10;
}
.ss-wd-backdrop.visible { opacity: 1; pointer-events: all; }
.ss-wd-sheet {
  position: absolute; bottom: 0; left: 0; right: 0;
  background: var(--card-color);
  border-radius: 22px 22px 0 0;
  border-top: 1.5px solid var(--border-color);
  box-shadow: 0 -4px 30px rgba(0,0,0,0.15);
  z-index: 11;
  transform: translateY(100%);
  visibility: hidden;
  transition: transform 0.28s cubic-bezier(0.32, 0, 0.67, 0), visibility 0s linear 0.28s;
  max-height: 78svh;
  display: flex; flex-direction: column; overflow: hidden;
  padding-bottom: calc(56px + env(safe-area-inset-bottom, 0px));
}
.ss-wd-sheet.open {
  transform: translateY(0);
  visibility: visible;
  transition: transform 0.32s cubic-bezier(0.34, 1.2, 0.64, 1), visibility 0s linear 0s;
}
.ss-wd-handle {
  width: 40px; height: 4px;
  background: color-mix(in srgb, var(--muted-color) 40%, transparent);
  border-radius: 2px; margin: 12px auto 0; flex-shrink: 0;
}
.ss-wd-top {
  display: flex; align-items: center; gap: 10px;
  padding: 12px 20px 0; flex-shrink: 0;
}
.ss-wd-surface {
  font-size: 1.5rem; font-weight: 700; color: var(--font-color); letter-spacing: 0.02em;
}
.ss-wd-strongs {
  font-size: 0.82rem; font-weight: 600; color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  border-radius: 8px; padding: 2px 8px;
}
.ss-wd-lemma {
  font-size: 0.88rem; color: var(--muted-color); padding: 4px 20px 0; flex-shrink: 0;
}

/* Save Verse to Study button in Rhema sheet */
.rhema-save-to-study-btn {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  width: calc(100% - 32px); margin: 12px 16px 0;
  padding: 12px; border-radius: 14px; border: 1.5px solid #4f8cff;
  background: rgba(79,140,255,0.08); color: #4f8cff;
  font-size: 0.88rem; font-weight: 700; cursor: pointer;
}
.rhema-save-to-study-btn.hidden { display: none; }
.rhema-save-to-study-btn .material-symbols-outlined { font-size: 18px; }

/* ── Community Study Board ─────────────────────────────────────────────────── */
.study-board-list {
  flex: 1; overflow-y: auto; padding: 12px 16px;
  display: flex; flex-direction: column; gap: 8px;
  overscroll-behavior: contain;
}
.study-board-empty {
  font-size: 0.85rem; color: var(--muted-color); text-align: center; padding: 24px 0;
}
.study-board-card {
  display: flex; align-items: center; gap: 12px;
  background: var(--card-color); border: 1.5px solid var(--study-color, #4f8cff);
  border-radius: 16px; padding: 12px 14px; cursor: pointer;
  position: relative; overflow: hidden; transition: transform 0.15s;
}
.study-board-card::before {
  content: ''; position: absolute; inset: 0;
  background: var(--study-color, #4f8cff); opacity: 0.05; pointer-events: none;
}
.study-board-card:active { transform: scale(0.98); }
.sbc-icon { font-size: 24px; color: var(--study-color, #4f8cff); flex-shrink: 0; }
.sbc-info { flex: 1; min-width: 0; }
.sbc-name { display: block; font-size: 0.9rem; font-weight: 700; color: var(--text-color); }
.sbc-meta { display: block; font-size: 0.75rem; color: var(--muted-color); margin-top: 2px; }
.sbc-collab-badge {
  font-size: 0.68rem; font-weight: 700; color: #22c55e;
  background: rgba(34,197,94,0.1); border-radius: 10px;
  padding: 3px 8px; flex-shrink: 0;
}
.sbc-chev { font-size: 18px; color: var(--muted-color); flex-shrink: 0; }

/* ── Theme-aware nav back buttons ───────────────────────────────────────── */
.nav-bar .icon-btn {
  background: var(--card-color);
  border-color: var(--border-color);
  color: var(--font-color);
}
.nav-bar .icon-btn:active { opacity: 0.7; }

/* ── Study Workspace ─────────────────────────────────────────────────────── */
.ws-tab-bar {
  display: flex; gap: 0; flex-shrink: 0;
  border-bottom: 1px solid var(--border-color);
  background: var(--card-color);
}
.ws-tab {
  flex: 1; padding: 9px 4px 7px;
  background: none; border: none; border-bottom: 2px solid transparent;
  font-size: 0.6rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase;
  color: var(--muted-color); cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  transition: color 0.15s, border-color 0.15s;
}
.ws-tab .material-symbols-outlined { font-size: 19px; }
.ws-tab.active { color: var(--accent-color, #4f8cff); border-bottom-color: var(--accent-color, #4f8cff); }
.ws-tab[data-type="observations"].active    { color: #3b82f6; border-bottom-color: #3b82f6; }
.ws-tab[data-type="interpretations"].active { color: #8b5cf6; border-bottom-color: #8b5cf6; }
.ws-tab[data-type="applications"].active    { color: #10b981; border-bottom-color: #10b981; }
.ws-tab[data-type="questions"].active       { color: #f59e0b; border-bottom-color: #f59e0b; }

.ws-entries-list {
  flex: 1; overflow-y: auto; padding: 10px 14px;
  display: flex; flex-direction: column; gap: 10px;
  overscroll-behavior: contain;
}
.ws-entry {
  background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 14px; padding: 12px 14px; cursor: pointer;
  border-left: 3px solid var(--ws-entry-color, var(--border-color));
  transition: opacity 0.15s;
}
.ws-entry:active { opacity: 0.75; }
.ws-entry-head {
  display: flex; align-items: center; gap: 6px; margin-bottom: 6px;
}
.ws-entry-icon { font-size: 15px; }
.ws-entry-ref { font-size: 0.72rem; font-weight: 700; color: var(--text-color); flex: 1; }
.ws-entry-author { font-size: 0.68rem; color: var(--muted-color); }
.ws-entry-date { font-size: 0.68rem; color: var(--muted-color); }
.ws-entry-del {
  background: none; border: none; cursor: pointer;
  color: var(--muted-color); padding: 0; line-height: 1;
}
.ws-entry-del .material-symbols-outlined { font-size: 15px; }
.ws-entry-snippet {
  font-size: 0.78rem; color: var(--muted-color);
  font-style: italic; margin-bottom: 6px; line-height: 1.4;
  overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
.ws-entry-content {
  font-size: 0.88rem; color: var(--text-color); line-height: 1.55;
  white-space: pre-wrap;
}
.ws-entry-hint {
  text-align: center; padding: 28px 16px;
  color: var(--muted-color); font-size: 0.84rem; line-height: 1.5;
}
.ws-entry-hint .material-symbols-outlined {
  display: block; font-size: 32px; margin-bottom: 8px; opacity: 0.4;
}

/* ── Study Mini Wheel ────────────────────────────────────────────────────── */
.smw-overlay {
  position: fixed; inset: 0; z-index: 1600;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--secondary-color) 25%, transparent);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  opacity: 0; transition: opacity 0.2s ease;
}
.smw-overlay.hidden { display: none; }
.smw-overlay.open { opacity: 1; }
.smw-wheel { position: relative; width: 0; height: 0; }
.smw-close {
  position: absolute; transform: translate(-50%, -50%);
  width: 50px; height: 50px; border-radius: 50%;
  background: var(--card-color); border: 2px solid var(--border-color);
  color: var(--font-color); cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 4px 20px rgba(0,0,0,0.18); z-index: 2;
}
.smw-close .material-symbols-outlined { font-size: 20px; }
.smw-item {
  position: absolute; transform: translate(-50%, -50%) scale(0);
  opacity: 0; width: 76px; height: 76px; border-radius: 50%;
  background: var(--card-color); border: 2px solid;
  cursor: pointer; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 3px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.16);
  transition: transform 0.3s cubic-bezier(0.34,1.56,0.64,1), opacity 0.22s ease;
  color: var(--font-color); font-size: 0;
}
.smw-item .material-symbols-outlined { font-size: 22px; }
.smw-label { font-size: 0.55rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; opacity: 0.85; text-align: center; line-height: 1.1; max-width: 60px; }
.smw-obs   { border-color: #3b82f6; color: #3b82f6; }
.smw-interp { border-color: #8b5cf6; color: #8b5cf6; }
.smw-app   { border-color: #10b981; color: #10b981; }
.smw-q     { border-color: #f59e0b; color: #f59e0b; }

/* Items appear at compass points, radius ≈ 110px */
.smw-overlay.open .smw-item:nth-child(1) { transform: translate(-50%, calc(-50% - 112px)) scale(1); opacity: 1; transition-delay: 0s; }
.smw-overlay.open .smw-item:nth-child(2) { transform: translate(calc(-50% + 112px), -50%) scale(1); opacity: 1; transition-delay: 0.05s; }
.smw-overlay.open .smw-item:nth-child(3) { transform: translate(-50%, calc(-50% + 112px)) scale(1); opacity: 1; transition-delay: 0.1s; }
.smw-overlay.open .smw-item:nth-child(4) { transform: translate(calc(-50% - 112px), -50%) scale(1); opacity: 1; transition-delay: 0.15s; }

/* ── Study Writing Modal ─────────────────────────────────────────────────── */
.swm-modal {
  position: fixed; inset: 0; z-index: 1700;
  background: var(--primary-color);
  display: flex; flex-direction: column;
  transform: translateY(100%); opacity: 0;
  transition: transform 0.3s cubic-bezier(0.4,0,0.2,1), opacity 0.3s ease;
}
.swm-modal.hidden { display: none; }
.swm-modal.open { transform: translateY(0); opacity: 1; }
.swm-header {
  display: flex; align-items: center; gap: 12px;
  /* Full-screen sheet: keep the title row clear of the status bar / Dynamic Island */
  padding: calc(env(safe-area-inset-top, 0px) + 16px) 20px 12px;
  border-bottom: 1px solid var(--border-color); flex-shrink: 0;
}
.swm-type-chip {
  display: flex; align-items: center; gap: 6px; flex: 1;
  font-size: 0.85rem; font-weight: 700;
}
.swm-type-chip .material-symbols-outlined { font-size: 20px; }
.swm-cancel {
  background: none; border: none; cursor: pointer;
  color: var(--muted-color); padding: 4px; line-height: 1;
}
.swm-cancel .material-symbols-outlined { font-size: 22px; }
.swm-verse-card {
  margin: 12px 16px; padding: 12px 16px;
  background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 14px; flex-shrink: 0;
}
.swm-verse-ref { font-size: 0.78rem; font-weight: 700; color: var(--muted-color); margin-bottom: 4px; }
.swm-verse-text {
  font-size: 0.85rem; color: var(--text-color); line-height: 1.55;
  font-style: italic;
  overflow: hidden; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical;
}
.swm-source-label {
  display: inline-flex;
  margin-top: 8px;
  padding: 3px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  color: var(--secondary-color);
  font-size: 0.68rem;
  font-weight: 800;
}
.swm-verse-nav-row {
  display: flex; align-items: flex-start; gap: 8px; padding: 8px 16px 4px;
}
.swm-verse-arrow {
  background: none; border: none; cursor: pointer; padding: 4px;
  color: var(--secondary-color); border-radius: 8px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  -webkit-tap-highlight-color: transparent;
}
.swm-verse-arrow:active { background: var(--border-color); }
.swm-english-text {
  flex: 1; font-size: 0.82rem; line-height: 1.5; color: var(--muted-color);
  font-style: italic; text-align: center; padding: 2px 0;
}
.swm-body { flex: 1; padding: 0 16px 8px; overflow-y: auto; overscroll-behavior: contain; }
.swm-textarea {
  width: 100%; min-height: 140px; max-height: 340px;
  background: var(--card-color); border: 1.5px solid var(--border-color);
  border-radius: 16px; padding: 14px 16px;
  font-size: 0.95rem; color: var(--text-color);
  resize: none; outline: none; overflow-y: auto;
  font-family: inherit; line-height: 1.6; box-sizing: border-box;
  overscroll-behavior: contain;
}
.swm-textarea:focus { border-color: var(--accent-color, #4f8cff); }
.swm-footer {
  padding: 12px 16px calc(env(safe-area-inset-bottom,0px) + 12px);
  flex-shrink: 0;
}
.swm-save-btn {
  width: 100%; padding: 14px;
  background: var(--accent-color, #4f8cff); color: #fff;
  border: none; border-radius: 14px; font-size: 0.95rem; font-weight: 700;
  cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px;
  transition: opacity 0.15s;
}
.swm-save-btn:active { opacity: 0.8; }
.swm-save-btn .material-symbols-outlined { font-size: 20px; }

/* ── Word Library ────────────────────────────────────────────────────────── */
.wl-overlay {
  position: fixed; inset: 0; z-index: 1400;
  display: flex; flex-direction: column;
  background: var(--primary-color);
  opacity: 0; transition: opacity 0.22s ease;
}
.wl-overlay.hidden { display: none; }
.wl-overlay.open { opacity: 1; }
.wl-sheet {
  background: var(--primary-color);
  border-radius: 0;
  display: flex; flex-direction: column;
  width: 100%;
  height: 100svh;
  min-height: 100svh;
  max-height: 100svh;
  overflow: hidden;
  transform: none;
  transition: none;
}
.wl-overlay.open .wl-sheet { transform: none; }
.wl-handle {
  width: 36px; height: 4px; border-radius: 2px;
  background: color-mix(in srgb, var(--muted-color) 35%, transparent);
  margin: 12px auto 0; flex-shrink: 0;
}
.wl-header {
  display: flex; align-items: center; gap: 10px;
  padding: calc(env(safe-area-inset-top, 0px) + 14px) 20px 10px;
  flex-shrink: 0;
  background: var(--primary-color);
}
.wl-header-icon { font-size: 22px; color: var(--accent-color, #4f8cff); }
.wl-title { flex: 1; font-size: 1rem; font-weight: 800; color: var(--text-color); }
.wl-close { background: none; border: none; cursor: pointer; color: var(--muted-color); padding: 4px; }
.wl-close .material-symbols-outlined { font-size: 22px; }
.wl-search-row {
  display: flex; align-items: center; gap: 8px;
  padding: 4px 16px 10px;
  flex-shrink: 0;
  background: var(--primary-color);
}
.wl-search-icon { font-size: 20px; color: var(--muted-color); flex-shrink: 0; }
.wl-search-input {
  flex: 1; height: 40px; background: var(--card-color);
  border: 1.5px solid var(--border-color); border-radius: 12px;
  padding: 0 12px; font-size: 0.95rem; color: var(--text-color); outline: none;
  font-family: inherit;
}
.wl-search-input:focus { border-color: var(--accent-color, #4f8cff); }
.wl-kbd-toggle {
  width: 40px; height: 40px; border-radius: 12px; border: 1.5px solid var(--border-color);
  background: var(--card-color); cursor: pointer; display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; transition: background 0.15s, border-color 0.15s;
}
.wl-kbd-toggle.active { background: var(--accent-color, #4f8cff); border-color: var(--accent-color, #4f8cff); }
.wl-kbd-icon { font-size: 1.1rem; font-weight: 700; color: var(--text-color); }
.wl-kbd-toggle.active .wl-kbd-icon { color: #fff; }
.wl-keyboard {
  flex-shrink: 0; padding: 0 12px 10px;
  display: grid; grid-template-columns: repeat(10, 1fr); gap: 4px;
}
.wl-keyboard.hidden { display: none; }
.wl-key {
  padding: 8px 0; background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 8px; font-size: 0.95rem; cursor: pointer; color: var(--text-color);
  transition: background 0.1s;
}
.wl-key:active { background: var(--accent-color, #4f8cff); color: #fff; }
.wl-key-bs {
  grid-column: span 2; font-size: 0.75rem;
  padding: 8px 0; background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 8px; cursor: pointer; color: var(--muted-color);
  transition: background 0.1s;
}
.wl-key-bs:active { background: color-mix(in srgb, var(--muted-color) 20%, transparent); }

/* ── Workspace Greek keyboard ─────────────────────────────────────────────── */
.ws-kbd-toggle {
  background: none; border: 1px solid var(--border-color); cursor: pointer;
  width: 40px; height: 40px; display: flex; align-items: center; justify-content: center;
  border-radius: 10px; flex-shrink: 0;
  color: var(--muted-color); transition: background 0.15s, color 0.15s;
}
.ws-kbd-toggle.active { background: var(--secondary-color); color: #fff; border-color: var(--secondary-color); }
.ws-kbd-icon { font-size: 1.2rem; font-weight: 700; font-family: 'Noto Serif', serif; }
.ws-greek-keyboard {
  display: grid; grid-template-columns: repeat(10, 1fr); gap: 6px;
  padding: 10px 14px 12px;
  background: var(--card-color); border-top: 1px solid var(--border-color);
}
.ws-greek-keyboard .wl-key {
  padding: 13px 0;
  font-size: 1.15rem;
  min-height: 52px;
}
.ws-greek-keyboard .wl-key-bs {
  grid-column: span 6;
  padding: 13px 0;
  font-size: 0.9rem;
  min-height: 52px;
}

.wl-info-btn {
  background: none; border: none; cursor: pointer;
  width: 34px; height: 34px; display: flex; align-items: center; justify-content: center;
  border-radius: 8px; flex-shrink: 0; color: var(--muted-color);
  transition: background 0.15s, color 0.15s;
}
.wl-info-btn:active { background: var(--border-color); }
.wl-info-btn .material-symbols-outlined { font-size: 1.25rem; }
.wl-info-body p { font-size: 0.88rem; line-height: 1.55; margin: 0 0 10px; color: var(--font-color); }
.wl-info-body h3 { font-size: 0.9rem; font-weight: 700; margin: 14px 0 4px; color: var(--secondary-color); }

/* WL info modal needs higher z-index than the WL overlay (z-index: 1400) */
#wlInfoModal { z-index: 1500; }

/* Study board sheet extras */
.sbs-desc { font-size: 0.85rem; opacity: 0.75; line-height: 1.5; text-align: center; margin: 4px 0 10px; }
.sbs-members-btn {
  display: flex; align-items: center; gap: 6px; justify-content: center;
  background: var(--card-color); border: 1px solid var(--border-color);
  border-radius: 20px; padding: 8px 18px; margin: 0 auto 14px;
  font-size: 0.88rem; font-weight: 600; color: var(--font-color);
  cursor: pointer; transition: background 0.15s;
}
.sbs-members-btn:active { background: var(--border-color); }
.sbs-members-btn .material-symbols-outlined { font-size: 1.1rem; color: var(--secondary-color); }

/* Study members list */
.study-members-list { display: flex; flex-direction: column; gap: 10px; }
.study-members-invite {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-color);
}
.study-members-add-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 12px;
  border-radius: 14px;
  border: 1.5px solid color-mix(in srgb, var(--secondary-color) 35%, var(--border-color));
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
  color: var(--secondary-color);
  font-weight: 800;
  cursor: pointer;
  margin-bottom: 10px;
}
.study-members-add-btn .material-symbols-outlined { font-size: 20px; }
.study-member-row {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px; background: var(--card-color);
  border-radius: 10px; font-size: 0.9rem; font-weight: 500;
}
.study-member-row .material-symbols-outlined { font-size: 1.3rem; color: var(--secondary-color); }
.study-member-creator-tag {
  margin-left: auto; font-size: 0.72rem; font-weight: 700;
  color: var(--secondary-color); background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  padding: 2px 8px; border-radius: 20px;
}

/* Studies info button */
.hs-info-btn {
  background: none; border: none; cursor: pointer; padding: 2px;
  color: var(--muted-color); display: flex; align-items: center;
}
.hs-info-btn .material-symbols-outlined { font-size: 1rem; }

.wl-results {
  flex: 1; min-height: 0; overflow-y: auto; padding: 4px 0 calc(env(safe-area-inset-bottom,0px) + 18px);
  overscroll-behavior: contain;
  background: var(--primary-color);
}
.wl-hint {
  padding: 32px 20px; text-align: center; color: var(--muted-color); font-size: 0.85rem; line-height: 1.5;
}
.wl-section-label {
  padding: 8px 20px 4px; font-size: 0.68rem; font-weight: 800; letter-spacing: 0.06em;
  text-transform: uppercase; color: var(--muted-color);
}
.wl-result-item {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 20px; border-bottom: 1px solid var(--border-color);
  cursor: pointer; transition: background 0.1s;
}
.wl-result-item:active { background: var(--card-color); }
.wl-result-lemma { font-size: 1.05rem; font-weight: 700; color: var(--text-color); flex-shrink: 0; min-width: 0; }
.wl-result-translit { font-size: 0.78rem; color: var(--muted-color); font-style: italic; flex-shrink: 0; }
.wl-result-brief { flex: 1; font-size: 0.82rem; color: var(--muted-color); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.wl-result-count { font-size: 0.72rem; color: var(--muted-color); flex-shrink: 0; }
.wl-result-form { background: color-mix(in srgb, var(--accent-color, #4f8cff) 8%, transparent); }
.wl-result-form-tag {
  font-size: 0.58rem; font-weight: 800; letter-spacing: 0.05em; text-transform: uppercase;
  color: var(--accent-color, #4f8cff); background: color-mix(in srgb, var(--accent-color, #4f8cff) 14%, transparent);
  border-radius: 999px; padding: 3px 7px; flex-shrink: 0;
  white-space: nowrap;
}

.rhema-wl-back {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 12px 46px 0 16px;
  padding: 8px 12px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 30%, var(--border-color));
  border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
  color: var(--secondary-color);
  font-weight: 800;
  font-size: 0.78rem;
  cursor: pointer;
}

.rhema-wl-back .material-symbols-outlined {
  font-size: 17px;
}

/* ── Workspace compose verse bar ────────────────────────────────────────────── */
.ws-compose-verse {
  flex-shrink: 0; background: var(--card-color);
  border-top: 1px solid var(--border-color); padding: 8px 16px 6px;
}
.ws-compose-verse-nav {
  display: flex; align-items: center; gap: 4px;
}
.ws-verse-arrow {
  background: none; border: none; cursor: pointer;
  color: var(--muted-color); padding: 2px; line-height: 1;
  display: flex; align-items: center; justify-content: center;
  transition: color 0.15s;
}
.ws-verse-arrow:active { color: var(--accent-color, #4f8cff); }
.ws-verse-arrow .material-symbols-outlined { font-size: 20px; }
.ws-compose-ref {
  flex: 1; text-align: center; font-size: 0.8rem; font-weight: 700; color: var(--text-color);
}
.ws-compose-english {
  font-size: 0.78rem; color: var(--muted-color); line-height: 1.5; font-style: italic;
  margin-top: 4px;
  overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
.ss-compose { border-top: none; }

/* ===== ESTIMATED LESSON TIMES ===== */

/* Time estimates inside lesson block headers */
.block-time {
  font-size: 0.68rem;
  font-weight: 500;
  color: var(--muted-color);
  opacity: 0.8;
  white-space: nowrap;
  flex-shrink: 0;
  margin-left: auto;
  margin-right: 6px;
}

/* Time estimates in lesson menu buttons */
.lesson-est-time {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 0.72rem;
  font-weight: 600;
  white-space: nowrap;
}

.lesson-est-time .material-symbols-outlined {
  font-size: 13px;
}

/* ===== GREEK VERBS LESSON TRACKS ===== */

.basic-verb-lesson {
  display: none;
  padding: 0 0 40px;
}

.basic-verb-lesson.active {
  display: block;
}

.adv-verb-lesson {
  display: none;
  padding: 0 0 40px;
}

.adv-verb-lesson.active {
  display: block;
}

/* Verb lesson screens inherit block styling from the shared lesson-block rules */
#basicVerbsLearnMenu .lesson-module,
#advVerbsLearnMenu .lesson-module {
  max-width: 680px;
  margin: 0 auto;
  padding: 16px 16px 40px;
}

#basicVerbsLearnMenu .lesson-lead,
#advVerbsLearnMenu .lesson-lead {
  font-size: 1rem;
  line-height: 1.65;
  margin-bottom: 18px;
  padding: 0 16px;
  color: var(--text-color);
  opacity: 0.88;
}

/* Quiz unlock area */
.verb-quiz-area {
  background: var(--card-bg);
  border: 1.5px solid var(--border-color);
  border-radius: 14px;
  padding: 18px 20px;
  margin: 20px 0 14px;
  text-align: center;
}

.verb-quiz-area .quiz-locked-msg {
  color: var(--text-muted, var(--text-color));
  opacity: 0.7;
  font-size: 0.88rem;
  margin: 0 0 8px;
}

.quiz-start-btn {
  background: var(--accent-color);
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 12px 28px;
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
  transition: opacity 0.18s;
}

.quiz-start-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.lesson-score-badge {
  display: none;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 20px;
  margin-top: 8px;
}

.lesson-score-badge.score-passed {
  background: rgba(76, 175, 80, 0.15);
  color: #2e7d32;
}

.lesson-score-badge.score-failed {
  background: rgba(244, 67, 54, 0.12);
  color: #c62828;
}

body.dark .lesson-score-badge.score-passed { color: #a5d6a7; background: rgba(76,175,80,0.2); }
body.dark .lesson-score-badge.score-failed { color: #ef9a9a; background: rgba(244,67,54,0.18); }

/* Verb Quiz Modal */
.verb-quiz-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.55);
  z-index: 1200;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s;
}

.verb-quiz-modal-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.verb-quiz-modal-card {
  background: var(--card-bg, #fff);
  border-radius: 24px 24px 0 0;
  width: 100%;
  max-width: 620px;
  min-height: 360px;
  max-height: 92vh;
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
  transform: translateY(30px);
  transition: transform 0.28s cubic-bezier(.4,0,.2,1);
}

.verb-quiz-modal-overlay.open .verb-quiz-modal-card {
  transform: translateY(0);
}

.verb-quiz-modal-topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px 10px;
  border-bottom: 1px solid var(--border-color);
}

.verb-quiz-modal-topbar .vqm-back {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-color);
  display: flex;
  align-items: center;
  padding: 4px;
}

.verb-quiz-modal-progress {
  flex: 1;
  height: 6px;
  background: var(--border-color);
  border-radius: 3px;
  overflow: hidden;
}

.verb-quiz-modal-fill {
  height: 100%;
  background: var(--accent-color);
  border-radius: 3px;
  transition: width 0.3s ease;
  width: 0%;
}

.verb-quiz-modal-counter {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-muted, var(--text-color));
  opacity: 0.7;
  min-width: 38px;
  text-align: right;
}

.verb-quiz-modal-body {
  padding: 22px 20px 24px;
  overflow-y: auto;
  flex: 1;
  overscroll-behavior: contain;
}

.verb-quiz-modal-body.quiz-modal-body-animate {
  animation: qmbSlideIn 0.2s ease;
}

@keyframes qmbSlideIn {
  from { opacity: 0; transform: translateX(18px); }
  to   { opacity: 1; transform: translateX(0); }
}

.quiz-modal-q-text {
  font-size: 1.05rem;
  font-weight: 600;
  line-height: 1.55;
  margin-bottom: 20px;
  color: var(--text-color);
}

.quiz-modal-opts {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 18px;
}

.quiz-modal-opt {
  background: var(--card-bg);
  border: 1.5px solid var(--border-color);
  border-radius: 12px;
  padding: 13px 16px;
  font-size: 0.92rem;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  color: var(--text-color);
}

.quiz-modal-opt:hover:not(:disabled) {
  border-color: var(--accent-color);
  background: rgba(var(--accent-rgb, 100,100,200), 0.06);
}

.quiz-modal-opt.qm-selected {
  border-color: var(--accent-color);
  background: rgba(var(--accent-rgb, 100,100,200), 0.1);
  font-weight: 600;
}

.quiz-modal-opt:disabled {
  cursor: not-allowed;
  opacity: 0.65;
}

.verb-quiz-modal-result {
  padding: 28px 24px;
  text-align: center;
  overflow-y: auto;
  flex: 1;
  overscroll-behavior: contain;
}

.verb-quiz-modal-result.hidden { display: none; }
.verb-quiz-modal-body.hidden   { display: none; }

.quiz-result-icon {
  font-size: 2.8rem;
  margin-bottom: 10px;
}

.quiz-see-results-btn {
  margin-top: 18px;
  width: 100%;
}

.quiz-answer-review {
  text-align: left;
  max-height: 55vh;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.quiz-answer-row {
  border-bottom: 1px solid var(--border-color);
  padding: 10px 0;
}

.quiz-answer-q {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.quiz-answer-wrong { color: #d32f2f; font-size: 0.85rem; margin: 2px 0; }
.quiz-answer-correct { color: #2e7d32; font-size: 0.85rem; margin: 2px 0; }

body.dark .quiz-answer-wrong { color: #ef9a9a; }
body.dark .quiz-answer-correct { color: #a5d6a7; }

/* Verb Lesson Complete Modal */
.verb-lesson-complete-modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1300;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s;
}

.verb-lesson-complete-modal.active {
  opacity: 1;
  pointer-events: all;
}

.verb-lesson-complete-card {
  background: var(--card-bg, #fff);
  border-radius: 20px;
  padding: 32px 28px 24px;
  max-width: 360px;
  width: 90%;
  text-align: center;
  box-shadow: 0 8px 40px rgba(0,0,0,0.18);
}

.verb-lesson-complete-card .lesson-complete-icon {
  font-size: 2.4rem;
  margin-bottom: 10px;
}

.verb-lesson-complete-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 0 8px;
}

.verb-lesson-complete-card p {
  font-size: 0.92rem;
  opacity: 0.8;
  margin-bottom: 20px;
}

/* Verb Info Modals */
.verb-info-modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1100;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s;
}

.verb-info-modal.open {
  opacity: 1;
  pointer-events: all;
}

.verb-info-card {
  background: var(--card-bg, #fff);
  border-radius: 20px;
  padding: 28px 24px 24px;
  max-width: 400px;
  width: 90%;
  box-shadow: 0 8px 40px rgba(0,0,0,0.18);
}

.verb-info-card h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin: 0 0 12px;
}

.verb-info-card p,
.verb-info-card li {
  font-size: 0.92rem;
  line-height: 1.6;
  opacity: 0.88;
}

/* Mobile full-width verb lessons */
@media (max-width: 760px) {
  body .app:has(#basicVerbsLearnMenu.screen.active .basic-verb-lesson.active),
  body .app:has(#advVerbsLearnMenu.screen.active .adv-verb-lesson.active) {
    padding-left: 8px !important;
    padding-right: 8px !important;
  }

  body #basicVerbsLearnMenu.screen.active:has(.basic-verb-lesson.active),
  body #advVerbsLearnMenu.screen.active:has(.adv-verb-lesson.active) {
    padding-left: 0 !important;
    padding-right: 0 !important;
  }

  body #basicVerbsLearnMenu .basic-verb-lesson.active,
  body #basicVerbsLearnMenu .basic-verb-lesson.active .lesson-module,
  body #advVerbsLearnMenu .adv-verb-lesson.active,
  body #advVerbsLearnMenu .adv-verb-lesson.active .lesson-module {
    width: 100% !important;
    max-width: none !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
  }

  body #basicVerbsLearnMenu .basic-verb-lesson.active .lesson-block,
  body #basicVerbsLearnMenu .basic-verb-lesson.active .lesson-lead,
  body #advVerbsLearnMenu .adv-verb-lesson.active .lesson-block,
  body #advVerbsLearnMenu .adv-verb-lesson.active .lesson-lead,
  body #advVerbsLearnMenu .adv-verb-lesson.active .knowledge-check {
    width: 100% !important;
    max-width: none !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    box-sizing: border-box;
  }

  body #basicVerbsLearnMenu.screen.active:has(.basic-verb-lesson.active) .nav-bar,
  body #advVerbsLearnMenu.screen.active:has(.adv-verb-lesson.active) .nav-bar {
    padding: 0 10px;
  }
}

/* =========================================================
   LESSON EXPERIENCE REDESIGN v2.7.11
   Shared behavior stays intact; this only skins lesson pages.
========================================================= */

#newLearnMenu .learn-lesson.active,
#basicVerbsLearnMenu .basic-verb-lesson.active,
#advancedLearnMenu .adv-learn-lesson.active,
#advVerbsLearnMenu .adv-verb-lesson.active {
  --lesson-accent: var(--secondary-color);
  --lesson-accent-soft: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  --lesson-accent-faint: color-mix(in srgb, var(--secondary-color) 6%, var(--card-color));
  --lesson-line: color-mix(in srgb, var(--secondary-color) 24%, var(--border-color));
  padding-bottom: 46px;
}

#advancedLearnMenu .adv-learn-lesson.active,
#advVerbsLearnMenu .adv-verb-lesson.active {
  --lesson-accent-soft: color-mix(in srgb, var(--secondary-color) 18%, transparent);
  --lesson-accent-faint: color-mix(in srgb, var(--secondary-color) 9%, var(--card-color));
  --lesson-line: color-mix(in srgb, var(--secondary-color) 34%, var(--border-color));
}

#newLearnMenu .learn-lesson.active .lesson-module,
#basicVerbsLearnMenu .basic-verb-lesson.active .lesson-module,
#advancedLearnMenu .adv-learn-lesson.active .lesson-module,
#advVerbsLearnMenu .adv-verb-lesson.active .lesson-module {
  width: min(100%, 760px);
  max-width: 760px;
  margin: 0 auto;
  padding: 14px 14px 46px !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
