/* Mercies */
#merciesPage {
  background:
    radial-gradient(circle at 8% 18%, color-mix(in srgb, var(--secondary-color) 10%, transparent), transparent 30%),
    linear-gradient(180deg, color-mix(in srgb, var(--primary-light) 92%, white), color-mix(in srgb, var(--primary-light) 78%, white)) !important;
  min-height: 100dvh !important;
  height: 100dvh !important;
  /* No top padding — the sticky tab bar owns the safe-area / Dynamic Island space. */
  padding: 0 18px calc(140px + 0px) !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: var(--font-color) !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  box-sizing: border-box;
}
.mercies-scroll { width: min(100%, 520px); max-width: 520px; margin: 0 auto; display: grid; gap: 18px; padding-bottom: calc(140px + 0px); overflow-x: hidden; box-sizing: border-box; }

/* ── Praises page tab bar (Praises / Disciple Group) ─────────────────────────
   Full-width sticky header pinned under the Dynamic Island. It owns the safe
   area and matches the Praises background so the page reads continuously to the
   very top, while the feed scrolls beneath it. */
.praises-tabbar {
  position: sticky;
  top: 0;
  z-index: 12;
  /* Break out of the page's 18px side padding to span edge-to-edge */
  margin: 0 -18px;
  padding: calc(env(safe-area-inset-top, 0px) + 9px) 0 9px;
  background: color-mix(in srgb, var(--primary-light) 92%, white);
  border-bottom: 1px solid color-mix(in srgb, var(--secondary-color) 9%, transparent);
  box-sizing: border-box;
  /* Shadow only appears once the feed scrolls under it */
  transition: box-shadow 0.22s ease, border-color 0.22s ease;
}
.praises-tabbar.scrolled {
  border-bottom-color: transparent;
  box-shadow: 0 8px 18px rgba(0,0,0,0.09);
}
/* Tabs centered with a max width so they don't stretch on large screens */
.praises-tabbar-inner {
  display: flex;
  gap: 8px;
  width: min(100%, 560px);
  margin: 0 auto;
  padding: 0 18px;
  box-sizing: border-box;
}
.praises-tab {
  flex: 1;
  display: flex; align-items: center; justify-content: center; gap: 6px;
  padding: 10px 8px;
  border: none;
  border-radius: 12px;
  background: color-mix(in srgb, var(--secondary-color) 7%, transparent);
  color: var(--muted-color);
  font-family: inherit;
  font-weight: 800;
  font-size: 0.9rem;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.2s ease, color 0.2s ease, box-shadow 0.2s ease, transform 0.12s ease;
}
.praises-tab .material-symbols-outlined { font-size: 1.15rem; }
.praises-tab.active {
  background: var(--secondary-color);
  color: var(--btn-text-color);
  box-shadow: 0 4px 12px color-mix(in srgb, var(--secondary-color) 32%, transparent);
}
.praises-tab:not(.active):active { transform: scale(0.97); }

