.bottom-nav {
  left: 50% !important;
  right: auto !important;
  bottom: calc(21px + 0px) !important;
  width: min(calc(100% - 34px), 440px) !important;
  height: 58px;
  align-items: center !important;
  padding: 5px 9px 6px !important;
  border-radius: 999px !important;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 14%, rgba(255,255,255,0.72)) !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.78), rgba(255,255,255,0.56)),
    color-mix(in srgb, var(--card-color) 72%, rgba(255,255,255,0.68)) !important;
  box-shadow:
    0 22px 46px rgba(15, 23, 42, 0.18),
    0 8px 18px rgba(15, 23, 42, 0.09),
    inset 0 1px 0 rgba(255,255,255,0.8) !important;
  backdrop-filter: blur(22px) saturate(1.18);
  -webkit-backdrop-filter: blur(22px) saturate(1.18);
  overflow: visible;
  isolation: isolate;
}

.bottom-nav::before {
  content: "";
  position: absolute;
  top: -9px;
  left: calc((100% - 18px) / 10);
  width: calc((100% - 18px) / 5);
  height: 34px;
  border-radius: 999px 999px 20px 20px;
  background:
    radial-gradient(120% 96% at 50% 0%, color-mix(in srgb, var(--secondary-color) 13%, rgba(255,255,255,0.84)), rgba(255,255,255,0.5) 72%),
    color-mix(in srgb, var(--card-color) 72%, rgba(255,255,255,0.74));
  border: 1px solid color-mix(in srgb, var(--secondary-color) 13%, rgba(255,255,255,0.62));
  border-bottom-color: transparent;
  box-shadow:
    0 -2px 10px color-mix(in srgb, var(--secondary-color) 10%, transparent),
    inset 0 1px 0 rgba(255,255,255,0.76);
  transform: translateX(0);
  transition: transform 0.24s cubic-bezier(.2,.8,.2,1), opacity 0.18s ease;
  z-index: 0;
  opacity: 0;
  pointer-events: none;
}

.bottom-nav:has(.bn-item:nth-child(1).active)::before { transform: translateX(0); opacity: 1; }
.bottom-nav:has(.bn-item:nth-child(2).active)::before { transform: translateX(100%); opacity: 1; }
.bottom-nav:has(.bn-item:nth-child(3).active)::before { transform: translateX(200%); opacity: 1; }
.bottom-nav:has(.bn-item:nth-child(4).active)::before { transform: translateX(300%); opacity: 1; }
.bottom-nav:has(.bn-item:nth-child(5).active)::before { transform: translateX(400%); opacity: 1; }

.bn-item {
