  height: 4px !important;
  background: var(--secondary-color) !important;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--secondary-color) 10%, transparent) !important;
}

body.dark .bottom-nav {
  background:
    linear-gradient(180deg, rgba(30,41,59,0.82), rgba(15,23,42,0.68)),
