  /* Study name spans full width */
  #studyCreateSheet .study-create-field:first-of-type { grid-column: 1 / -1; }

  /* Color and icon side by side */
  #studyCreateSheet .study-create-field:nth-of-type(2) { grid-column: 1; }
  #studyCreateSheet .study-create-field:nth-of-type(3) { grid-column: 2; }

  /* Description spans full width */
  #studyCreateSheet .study-create-field:nth-of-type(4) { grid-column: 1 / -1; }

  /* Share toggle and invite spans full width */
  #studyCreateSheet .study-share-toggle { grid-column: 1 / -1; }
  #studyCreateSheet #studyInviteFriendsSection { grid-column: 1 / -1; }

  /* Buttons spans full width */
  #studyCreateSheet .main-btn { grid-column: 1 / -1; }
  #studyCreateSheet .text-btn { grid-column: 1 / -1; }

  #studyCreateSheet .study-icon-grid {
    grid-template-columns: repeat(4, 1fr);
