  #profilePage .xp-section {
    grid-column: 2;
    padding: 22px 24px;
    border-radius: 18px;
    border: 1px solid color-mix(in srgb, var(--border-color) 68%, transparent);
    background: color-mix(in srgb, var(--card-color) 88%, rgba(255,255,255,0.7));
