    grid-column: 2;
    border-radius: 18px;
    margin-bottom: 16px;
  }

  #profilePage .profile-color-grid {
    grid-column: 2;
    margin-bottom: 16px;
  }

  #profilePage .prof-menu-card {
    grid-column: 2;
    border-radius: 18px;
    border: 1px solid color-mix(in srgb, var(--border-color) 68%, transparent);
    background: color-mix(in srgb, var(--card-color) 88%, rgba(255,255,255,0.7));
    overflow: hidden;
    margin-bottom: 16px;
  }

  #profilePage .try-app-btn {
    grid-column: 2;
  }

  /* Sermons page */
  #sermonsPage.screen.active {
    overflow: auto;
    padding: 28px clamp(28px, 4vw, 56px) 40px;
  }

  .sermons-scroll {
    max-width: 1100px;
    margin: 0 auto;
  }

  .sermons-header {
    margin-bottom: 28px;
  }

  .sermons-title {
    font-size: 2rem;
    font-weight: 950;
    color: var(--font-color);
    margin: 0 0 6px;
  }

  .sermons-sub {
    color: var(--muted-color);
    font-size: 0.92rem;
    margin: 0;
  }

  .sermons-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 18px;
  }

  .sermon-card {
    padding: 22px;
    border-radius: 20px;
    border: 1px solid color-mix(in srgb, var(--border-color) 70%, transparent);
    background: color-mix(in srgb, var(--card-color) 90%, rgba(255,255,255,0.7));
    cursor: pointer;
    text-align: left;
    transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  }

  .sermon-card:hover {
    transform: translateY(-2px);
    border-color: color-mix(in srgb, var(--secondary-color) 28%, var(--border-color));
    box-shadow: 0 12px 32px rgba(15,23,42,0.1);
  }

  .sermon-card-icon {
    width: 46px;
    height: 46px;
    border-radius: 14px;
    display: grid;
    place-items: center;
    background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
    color: var(--secondary-color);
    font-size: 24px;
    margin-bottom: 14px;
  }

  .sermon-card-title {
    display: block;
    font-size: 1.05rem;
    font-weight: 950;
    color: var(--font-color);
    margin-bottom: 5px;
