    color: var(--btn-text-color);
    font: inherit;
    font-weight: 900;
    font-size: 0.84rem;
    cursor: pointer;
    transition: opacity 0.15s ease;
  }

  .sermon-card-open-btn:hover { opacity: 0.88; }

  .sermon-card-delete-btn {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    border: 1px solid color-mix(in srgb, var(--border-color) 70%, transparent);
    background: transparent;
    color: var(--muted-color);
    display: grid;
    place-items: center;
    cursor: pointer;
    transition: background 0.15s ease;
  }

  .sermon-card-delete-btn:hover {
