/* ── Sermon Workshop overlay ───────────────────────────────────────────────── */
.sw-overlay {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: stretch;
  transition: opacity 0.28s ease, visibility 0.28s ease;
}

.sw-overlay.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.sw-overlay.open {
  opacity: 1;
  visibility: visible;
}

.sw-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.52);
  z-index: 0;
}

.sw-rhema-panel {
  position: relative;
  z-index: 1;
  flex: 1;
  min-width: 0;
  background: var(--primary-color);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-right: 1px solid color-mix(in srgb, var(--border-color) 60%, transparent);
}

.sw-rhema-panel.hidden {
  display: none;
}

.sw-panel {
  position: relative;
  z-index: 1;
  width: min(820px, 90vw);
  flex-shrink: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--primary-light);
  border-left: 1px solid color-mix(in srgb, var(--border-color) 70%, transparent);
  box-shadow: -24px 0 60px rgba(15, 23, 42, 0.18);
  transform: translateX(100%);
  transition: transform 0.32s cubic-bezier(0.4, 0, 0.2, 1);
  overflow: hidden;
  margin-left: auto;
}

.sw-overlay.open .sw-panel {
  transform: translateX(0);
}

.sw-sidebar-spacer {
  flex: 1;
}

.sw-rhema-toggle-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 22%, transparent);
  background: color-mix(in srgb, var(--secondary-color) 9%, transparent);
  color: var(--secondary-color);
  font: inherit;
  font-weight: 850;
  font-size: 0.86rem;
  cursor: pointer;
  transition: background 0.15s ease;
  margin-top: 6px;
}

.sw-rhema-toggle-btn:hover {
  background: color-mix(in srgb, var(--secondary-color) 14%, transparent);
}

.sw-rhema-toggle-btn.active {
  background: var(--secondary-color);
  color: var(--btn-text-color);
  border-color: transparent;
}

