/* ── Scrollbar theming (desktop only) ─────────────────────────────────────── */
@media (min-width: 960px) and (pointer: fine) {
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
    border-radius: 999px;
  }
  ::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--secondary-color) 38%, var(--muted-color));
    border-radius: 999px;
    border: 2px solid transparent;
    background-clip: padding-box;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: color-mix(in srgb, var(--secondary-color) 60%, var(--muted-color));
    background-clip: padding-box;
    border: 2px solid transparent;
  }
  ::-webkit-scrollbar-corner {
    background: transparent;
  }

  /* Study sandbox: must not be covered by nav rail */
  .study-sandbox {
    left: 300px !important;
    width: calc(100vw - 300px) !important;
  }

  /* Cross reference: desktop-friendly sidebar layout */
  .rhema-xref-page {
    left: 300px;
    border-left: 1px solid color-mix(in srgb, var(--border-color) 60%, transparent);
  }

  .rhema-xref-verse-row {
    padding: 11px 14px;
    border-radius: 12px;
    border-bottom: none;
    margin-bottom: 4px;
    background: color-mix(in srgb, var(--card-color) 80%, transparent);
    border: 1px solid color-mix(in srgb, var(--border-color) 44%, transparent);
    transition: background 0.12s, border-color 0.12s;
  }

  .rhema-xref-verse-row:hover {
    background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
    border-color: color-mix(in srgb, var(--secondary-color) 22%, transparent);
  }

  .rhema-xref-verse-ref {
    font-size: 0.82rem;
    min-width: 72px;
    font-weight: 800;
  }

  .rhema-xref-verse-text {
    font-size: 0.88rem;
    line-height: 1.5;
  }

  .rx-page-header {
    padding-top: 18px;
    padding-left: 24px;
    padding-right: 24px;
  }

  /* Reference pickers: ensure not behind nav on desktop */
  #rxBookPickerOverlay {
    left: 300px !important;
    width: calc(100vw - 300px) !important;
  }

  .rhema-picker-overlay {
    left: 300px;
    width: calc(100vw - 300px);
  }

  /* Desktop tool grid: 3 columns now that Lessons is removed */
  .desktop-tool-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  /* Sermon-mode back-to-workshop button in Rhema header */
  .rhema-workshop-back-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 14px 6px 10px;
    border-radius: 10px;
    border: 1.5px solid color-mix(in srgb, var(--secondary-color) 30%, var(--border-color));
    background: color-mix(in srgb, var(--secondary-color) 8%, transparent);
    color: var(--secondary-color);
    font: inherit;
    font-size: 0.82rem;
    font-weight: 850;
    cursor: pointer;
    white-space: nowrap;
    flex-shrink: 0;
  }

  .rhema-workshop-back-btn .material-symbols-outlined {
    font-size: 18px;
  }

  .rhema-workshop-back-btn.hidden {
    display: none;
  }
}

