/* ── Verse Structure Modal ────────────────────────────────────────────────────*/
.vs-modal {
  position: fixed; inset: 0;
  z-index: 1100;
  background: var(--primary-color);
  display: flex; flex-direction: column;
  transform: translateY(100%);
  transition: transform 0.32s cubic-bezier(0.32,0.72,0,1);
}
.vs-modal.vs-active { transform: translateY(0); }
.vs-modal.hidden { display: none; }

.vs-slide {
  flex: 1; display: flex; flex-direction: column;
  height: 100%; overflow: hidden;
}

/* Header */
.vs-header {
  display: flex; align-items: center; gap: 10px;
  padding: 14px 16px 10px;
  padding-top: max(14px, env(safe-area-inset-top));
  background: var(--primary-color);
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.vs-back-btn {
  width: 36px; height: 36px; border-radius: 50%;
  background: none; border: none; cursor: pointer;
  color: var(--font-color);
  display: flex; align-items: center; justify-content: center;
  -webkit-tap-highlight-color: transparent;
}
.vs-back-btn .material-symbols-outlined { font-size: 1.35rem; }
.vs-title-block { flex: 1; }
.vs-title {
  display: block; font-size: 1rem; font-weight: 800; color: var(--font-color);
  line-height: 1.15;
}
.vs-title-sub {
  display: block; font-size: 0.71rem; color: var(--muted-color); margin-top: 1px;
}
.vs-tool-btn {
  position: relative;
  width: 36px; height: 36px; border-radius: 50%;
  background: color-mix(in srgb, var(--secondary-color) 12%, transparent);
  border: 1.5px solid color-mix(in srgb, var(--secondary-color) 30%, var(--border-color));
  color: var(--secondary-color);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.15s;
  flex-shrink: 0;
}
.vs-tool-btn:active { background: color-mix(in srgb, var(--secondary-color) 22%, transparent); }
.vs-tool-btn .material-symbols-outlined { font-size: 1.2rem; }
.vs-tool-dot {
  position: absolute;
  top: 3px; right: 3px;
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--secondary-color);
  opacity: 0;
  transition: opacity 0.18s;
  pointer-events: none;
}
.vs-tool-dot.active { opacity: 1; }

/* Reference picker row */
.vs-picker {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 16px 8px;
  background: var(--primary-color);
  flex-shrink: 0;
}

/* Translation chips */
.vs-trans-row {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 16px 8px;
  overflow-x: auto; -webkit-overflow-scrolling: touch;
  scrollbar-width: none; flex-shrink: 0;
}
.vs-trans-row::-webkit-scrollbar { display: none; }
.vs-trans-chip {
  flex-shrink: 0;
  padding: 5px 14px; border-radius: 20px;
  font-size: 0.78rem; font-weight: 700; letter-spacing: 0.03em;
  background: var(--card-color);
  border: 1.5px solid var(--border-color);
  color: var(--muted-color);
  cursor: pointer;
  transition: background 0.14s, color 0.14s, border-color 0.14s;
  -webkit-tap-highlight-color: transparent;
}
.vs-trans-chip.active {
  background: var(--secondary-color);
  border-color: var(--secondary-color);
  color: #fff;
}
.vs-trans-chip:not(.active):active {
  background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color));
}
.vs-trans-chip.limited {
  opacity: 0.4;
  cursor: not-allowed;
  text-decoration: line-through;
  pointer-events: auto;
}
.vs-api-limit-banner {
  margin: 0 14px 6px;
  padding: 8px 12px;
  background: color-mix(in srgb, var(--accent-color) 14%, var(--card-color));
  border: 1px solid color-mix(in srgb, var(--accent-color) 60%, transparent);
  border-radius: 10px;
  font-size: 0.76rem;
  color: var(--font-color);
  display: flex; align-items: flex-start; gap: 7px;
  flex-shrink: 0;
  line-height: 1.4;
}
.vs-api-limit-banner .material-symbols-outlined {
  font-size: 1rem; color: var(--accent-color); flex-shrink: 0; margin-top: 1px;
}
.vs-api-limit-banner.hidden { display: none; }
.vs-limit-flash { animation: vs-limit-flash 0.5s ease; }
@keyframes vs-limit-flash {
  0%, 100% { opacity: 1; }
  40%       { opacity: 0.25; }
}

/* Body */
.vs-body {
  flex: 1; overflow-y: auto; overflow-x: hidden;
  padding: 20px 20px 16px;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-y: contain;
}
.vs-loading {
  text-align: center; color: var(--muted-color);
  font-size: 0.88rem; padding: 32px 0;
}
.vs-verse-display { width: 100%; }
.vs-verse-text {
  font-size: 1.25rem; line-height: 1.75; color: var(--font-color);
  font-weight: 400; letter-spacing: 0.01em;
}
.vs-error {
  display: flex; align-items: center; gap: 8px;
  color: var(--muted-color); font-size: 0.88rem; padding: 20px 0;
}
.vs-error .material-symbols-outlined { font-size: 1.1rem; }
.vs-verse-empty { color: var(--muted-color); font-size: 0.88rem; padding: 20px 0; }

/* Bottom verse nav */
.vs-verse-nav {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 16px;
  padding-bottom: max(10px, 0px);
  background: var(--primary-color);
  border-top: 1px solid var(--border-color);
  flex-shrink: 0;
}
.vs-nav-btn {
  width: 38px; height: 38px; border-radius: 50%;
  background: var(--card-color); border: 1.5px solid var(--border-color);
  color: var(--font-color); cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  transition: background 0.12s, border-color 0.12s;
  -webkit-tap-highlight-color: transparent;
}
.vs-nav-btn:active { background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color)); }
.vs-nav-btn.vs-nav-active {
  background: color-mix(in srgb, var(--secondary-color) 16%, var(--card-color));
  border-color: var(--secondary-color);
  color: var(--secondary-color);
}
.vs-nav-btn .material-symbols-outlined { font-size: 1.2rem; }
.vs-verse-ref {
  flex: 1; text-align: center;
  font-size: 0.82rem; font-weight: 700; color: var(--muted-color);
}

/* Book picker testament grid */
.vs-testa-grid {
  display: flex; gap: 8px;
  padding: 10px 16px 4px;
}
.vs-testa-btn {
  flex: 1;
  display: flex; align-items: center; justify-content: center; gap: 6px;
  padding: 9px 12px; border-radius: 12px;
  background: var(--card-color); border: 1.5px solid var(--border-color);
  color: var(--muted-color); font-size: 0.82rem; font-weight: 700;
  cursor: pointer; transition: all 0.14s;
  -webkit-tap-highlight-color: transparent;
}
.vs-testa-btn .material-symbols-outlined { font-size: 1rem; }
.vs-testa-btn.active {
  background: color-mix(in srgb, var(--secondary-color) 14%, var(--card-color));
  border-color: var(--secondary-color);
  color: var(--secondary-color);
}

/* Verse picker sheet sizing */
.vs-verse-picker-sheet { max-height: 85vh; overflow-y: auto; }
.vs-picker-body { padding: 0 16px 20px; }
.vs-picker-section { margin-bottom: 16px; }
.vs-picker-label {
  font-size: 0.75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.06em; color: var(--muted-color);
  margin: 12px 0 8px;
}

/* VS verse preview card (inside verse picker) */
#vsVersePreview { border-top: 1px solid var(--border-color); margin-top: 8px; }
#vsVersePreview strong {
  display: block; color: var(--secondary-color);
  font-size: 0.85rem; font-weight: 800; margin-bottom: 4px;
}

/* ── VS Wheel Overlay ──────────────────────────────────────────────────── */
.vs-slide { position: relative; }
.vs-wheel-overlay {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--secondary-color) 14%, rgba(0,0,0,0.32));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  opacity: 0;
  transition: opacity 0.22s ease;
}
.vs-wheel-overlay.open { opacity: 1; }
.vs-wheel { position: relative; width: 0; height: 0; }
.vs-wheel-center {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 48px; height: 48px;
  border-radius: 50%;
  background: var(--card-color);
  border: 2px solid var(--border-color);
  color: var(--font-color);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 4px 20px rgba(0,0,0,0.18);
  z-index: 2;
  -webkit-tap-highlight-color: transparent;
}
.vs-wheel-center .material-symbols-outlined { font-size: 20px; }
.vs-wheel-item {
  position: absolute;
  transform: translate(-50%, -50%) scale(0);
  opacity: 0;
  width: 78px; height: 78px;
  border-radius: 50%;
  background: var(--card-color);
  border: 2px solid var(--border-color);
  color: var(--font-color);
  cursor: pointer;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  gap: 3px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.14);
  transition: transform 0.3s cubic-bezier(0.34,1.56,0.64,1), opacity 0.2s ease, background 0.15s;
  -webkit-tap-highlight-color: transparent;
}
.vs-wheel-item .material-symbols-outlined { font-size: 22px; }
.vs-wheel-item .rwi-label { font-size: 0.55rem; font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase; opacity: 0.8; line-height: 1.05; }
.vs-wheel-item.active {
  background: var(--secondary-color);
  border-color: var(--secondary-color);
  color: #fff;
}
/* Diamond positions (r=90px): top=Cross-Ref, right=Highlight, bottom=Chapter, left=Structure */
.vs-wheel-overlay.open .vs-wheel-item:nth-child(1) { transform: translate(calc(-50% + 0px),   calc(-50% + -90px)) scale(1); opacity: 1; transition-delay: 0s; }
.vs-wheel-overlay.open .vs-wheel-item:nth-child(2) { transform: translate(calc(-50% + 90px),  calc(-50% + 0px))   scale(1); opacity: 1; transition-delay: 0.05s; }
.vs-wheel-overlay.open .vs-wheel-item:nth-child(3) { transform: translate(calc(-50% + 0px),   calc(-50% + 90px))  scale(1); opacity: 1; transition-delay: 0.1s; }
.vs-wheel-overlay.open .vs-wheel-item:nth-child(4) { transform: translate(calc(-50% + -90px), calc(-50% + 0px))   scale(1); opacity: 1; transition-delay: 0.15s; }

/* ── VS Range Button ───────────────────────────────────────────────────── */
.vs-range-btn {
  flex-shrink: 0;
  display: flex; align-items: center; gap: 3px;
  padding: 6px 11px 6px 13px; border-radius: 20px;
  background: var(--card-color);
  border: 1.5px solid var(--border-color);
  color: var(--font-color); font-size: 0.8rem; font-weight: 700;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
  -webkit-tap-highlight-color: transparent;
}
.vs-range-btn:active { background: color-mix(in srgb, var(--secondary-color) 12%, var(--card-color)); }
.vs-range-btn .material-symbols-outlined { font-size: 1rem; opacity: 0.55; }
.vs-range-btn.vs-range-active {
  background: color-mix(in srgb, var(--secondary-color) 14%, var(--card-color));
  border-color: var(--secondary-color);
  color: var(--secondary-color);
}

/* ── VS Range Picker Overlay ───────────────────────────────────────────── */
.vs-range-overlay {
  position: absolute; inset: 0; z-index: 1050;
  background: rgba(0,0,0,0.42);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  display: flex; align-items: flex-end; justify-content: center;
}
.vs-range-overlay.hidden { display: none; }
.vs-range-sheet {
  width: 100%; max-height: 82svh;
  background: var(--primary-color);
  border-radius: 24px 24px 0 0;
  border-top: 1.5px solid var(--border-color);
  overflow-y: auto;
  padding-bottom: 0px;
  -webkit-overflow-scrolling: touch;
}
.vs-range-hdr {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 20px 12px;
  border-bottom: 1px solid var(--border-color);
  position: sticky; top: 0; background: var(--primary-color); z-index: 1;
}
.vs-range-hdr h3 { margin: 0; font-size: 0.88rem; font-weight: 800; color: var(--font-color); }
.vs-range-close-btn {
  background: none; border: none; cursor: pointer;
  color: var(--font-color); display: flex; align-items: center; justify-content: center;
  width: 32px; height: 32px;
  -webkit-tap-highlight-color: transparent;
}
.vs-range-hint {
  font-size: 0.74rem; color: var(--muted-color);
  padding: 10px 20px 4px;
}
.vs-range-selection {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 20px 10px;
  font-size: 0.85rem; font-weight: 800; color: var(--secondary-color);
  min-height: 36px;
}
.vs-range-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
  padding: 4px 16px 16px;
}
.vs-range-grid button {
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--card-color);
  border: 1.5px solid var(--border-color);
  color: var(--font-color); font-size: 0.82rem; font-weight: 700;
  cursor: pointer; transition: all 0.12s;
  -webkit-tap-highlight-color: transparent;
}
.vs-range-grid button.range-start,
.vs-range-grid button.range-end {
  background: var(--secondary-color);
  border-color: var(--secondary-color);
  color: #fff;
}
.vs-range-grid button.range-mid {
  background: color-mix(in srgb, var(--secondary-color) 22%, var(--card-color));
  border-color: color-mix(in srgb, var(--secondary-color) 40%, var(--border-color));
  color: var(--font-color);
}
.vs-range-apply-btn {
  display: block; width: calc(100% - 32px); margin: 4px 16px 16px;
  padding: 13px; border-radius: 14px;
  background: var(--secondary-color); color: #fff;
  border: none; font-size: 0.9rem; font-weight: 800;
  cursor: pointer; -webkit-tap-highlight-color: transparent;
  transition: opacity 0.15s;
}
.vs-range-apply-btn:disabled { opacity: 0.45; cursor: default; }

/* ── VS Full Chapter View ──────────────────────────────────────────────── */
.vs-chapter-view { width: 100%; }
.vs-chapter-verse {
  display: flex; gap: 10px; align-items: baseline;
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--border-color) 50%, transparent);
}
.vs-chapter-verse:last-child { border-bottom: none; }
.vs-verse-num {
  flex-shrink: 0;
  font-size: 0.72rem; font-weight: 800;
  color: var(--secondary-color);
  min-width: 22px; text-align: right;
  line-height: 1.75;
  margin-top: 2px;
}
.vs-verse-text-inline {
  font-size: 1.1rem; line-height: 1.75; color: var(--font-color); font-weight: 400;
}

/* ── VS Structure Workspace ──────────────────────────────────────────────── */
.vs-struct-modal {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  z-index: 9990;
  display: none;
  flex-direction: column;
  background: var(--primary-color);
  will-change: transform;
  transition: transform 0.32s cubic-bezier(0.32,0.72,0,1);
  transform: translateY(100%);
}
.vs-struct-modal.open { transform: translateY(0); }

.vs-struct-header {
  display: flex; align-items: center; gap: 8px;
  padding: 14px 16px 10px;
  padding-top: max(14px, env(safe-area-inset-top));
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
  background: var(--primary-color);
}
.vs-struct-back {
  width: 36px; height: 36px; border-radius: 50%; border: 0;
  display: flex; align-items: center; justify-content: center;
  background: transparent; color: var(--font-color); cursor: pointer;
}
.vs-struct-title {
  flex: 1; font-size: 1rem; font-weight: 700; color: var(--font-color);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.vs-struct-toolbar {
  display: flex; align-items: center; gap: 6px;
}
.vs-struct-tool-btn {
  width: 36px; height: 36px; border-radius: 50%; border: 0;
  display: flex; align-items: center; justify-content: center;
  background: transparent; color: var(--font-color); cursor: pointer;
  font-size: 1.2rem;
}
.vs-struct-tool-btn:active { background: color-mix(in srgb, var(--secondary-color) 15%, transparent); }
.vs-struct-tool-btn.active { color: var(--secondary-color); }
.vs-struct-tool-btn:disabled { opacity: 0.35; pointer-events: none; }

.vs-struct-edit-bar {
  display: none; align-items: center; justify-content: center; gap: 10px;
  padding: 8px 16px;
  background: color-mix(in srgb, var(--secondary-color) 8%, var(--card-color));
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.vs-struct-edit-bar.visible { display: flex; }
.vs-struct-edit-label {
  font-size: 0.75rem; font-weight: 700; color: var(--secondary-color);
  text-transform: uppercase; letter-spacing: 0.06em;
}

.vs-struct-canvas-wrap {
  flex: 1; overflow: auto; position: relative;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding-bottom: 0px;
  background: var(--primary-color);
}
.vs-struct-canvas {
  position: relative;
  width: 2200px; height: 2000px;
  touch-action: pan-x pan-y;
  background: var(--primary-color);
}
.vs-struct-canvas.edit-mode { touch-action: pan-x pan-y; }

.vs-struct-seg {
  position: absolute;
  display: flex; flex-wrap: wrap; gap: 4px; align-items: center;
  padding: 10px 14px;
  background: transparent;
  border: none;
  border-radius: 10px;
  box-shadow: none;
  cursor: default;
  user-select: none;
  -webkit-user-select: none;
  max-width: min(760px, calc(100vw - 48px));
  transition: transform 0.18s cubic-bezier(0.34,1.56,0.64,1), box-shadow 0.18s ease, opacity 0.15s;
  will-change: transform;
}
.vs-struct-seg.edit-mode {
  cursor: grab;
  background: transparent;
  border: none;
}
.vs-struct-seg.dragging {
  cursor: grabbing;
  opacity: 0.92;
  z-index: 100;
  transform: scale(1.05);
  box-shadow: 0 12px 36px rgba(0,0,0,0.22), 0 2px 8px rgba(0,0,0,0.1);
}
.vs-struct-word {
  font-size: 1.3rem; font-weight: 500; color: var(--font-color);
  padding: 3px 6px; border-radius: 6px;
  cursor: default;
  transition: background 0.1s;
}
.vs-struct-verse-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  margin-right: 4px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--secondary-color) 14%, transparent);
  color: var(--secondary-color);
  font-size: 0.82rem;
  font-weight: 900;
  line-height: 1;
  flex: 0 0 auto;
}
.vs-struct-seg.edit-mode .vs-struct-word {
  cursor: pointer;
}
.vs-struct-seg.edit-mode .vs-struct-word:hover {
  background: color-mix(in srgb, var(--secondary-color) 15%, transparent);
  color: var(--secondary-color);
}
.vs-struct-word.long-press-active {
  background: color-mix(in srgb, var(--secondary-color) 22%, transparent);
  color: var(--secondary-color);
  animation: vs-lp-pulse 0.35s ease forwards;
}
.vs-struct-word-splitting-hidden {
  visibility: hidden;
}
@keyframes vs-lp-pulse {
  0%   { transform: scale(1);    opacity: 1; }
  40%  { transform: scale(0.92); opacity: 0.6; }
  100% { transform: scale(1.08); opacity: 1; }
}

/* Struct picker modal */
.vs-struct-picker-modal {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0; z-index: 9985;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(0,0,0,0.45);
  opacity: 0; pointer-events: none;
  transition: opacity 0.22s;
}
.vs-struct-picker-modal.open { opacity: 1; pointer-events: all; }
.vs-struct-picker-sheet {
  width: 100%; max-width: 480px;
  background: var(--card-color);
  border-radius: 20px 20px 0 0;
  padding: 20px 20px calc(32px + 0px);
  transform: translateY(30px);
  transition: transform 0.22s cubic-bezier(0.32,0.72,0,1);
}
.vs-struct-picker-modal.open .vs-struct-picker-sheet { transform: translateY(0); }

.vs-struct-picker-title {
  font-size: 1rem; font-weight: 700; color: var(--font-color);
  margin: 0 0 16px;
}
.vs-struct-picker-row {
  display: flex; gap: 10px; margin-bottom: 12px; align-items: center;
}
.vs-struct-picker-label {
  font-size: 0.8rem; font-weight: 700; color: var(--muted-color);
  min-width: 52px;
}
.vs-struct-picker-sel {
  flex: 1; height: 40px; border-radius: 10px;
  border: 1.5px solid var(--border-color);
  background: var(--card-color); color: var(--font-color);
  font-size: 0.9rem; padding: 0 10px;
}
.vs-struct-picker-open-btn {
  width: 100%; height: 48px; border-radius: 14px; border: 0;
  background: var(--secondary-color); color: #fff;
  font-size: 1rem; font-weight: 800; cursor: pointer;
  margin-top: 8px;
}
.vs-struct-picker-open-btn:active { opacity: 0.85; }

.vs-struct-name-input {
  width: 100%; height: 44px; border-radius: 12px;
  border: 1.5px solid var(--border-color);
  background: var(--card-color); color: var(--font-color);
  font-size: 0.95rem; padding: 0 12px;
  box-sizing: border-box; margin-bottom: 12px;
  outline: none;
}
.vs-struct-name-input:focus {
  border-color: var(--secondary-color);
}
.vs-struct-name-input::placeholder { color: var(--muted-color); }

/* Struct info sheet */
.vs-struct-info-modal {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0; z-index: 9995;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(0,0,0,0.45);
  opacity: 0; pointer-events: none;
  transition: opacity 0.22s;
}
.vs-struct-info-modal.open { opacity: 1; pointer-events: all; }
.vs-struct-info-sheet {
  width: 100%; max-width: 480px;
  background: var(--card-color);
  border-radius: 20px 20px 0 0;
  padding: 20px 20px 40px;
  transform: translateY(30px);
  transition: transform 0.22s;
}
.vs-struct-info-modal.open .vs-struct-info-sheet { transform: translateY(0); }
.vs-struct-info-sheet h3 {
  margin: 0 0 12px; font-size: 1rem; font-weight: 800; color: var(--font-color);
}
.vs-struct-info-sheet p {
  margin: 0 0 10px; font-size: 0.88rem; line-height: 1.6; color: var(--muted-color);
}

/* ── VS Saved Structures Browser ─────────────────────────────────────────── */
.vs-struct-browser-modal {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0; z-index: 9985;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(0,0,0,0.45);
  opacity: 0; pointer-events: none;
  transition: opacity 0.22s;
}
.vs-struct-browser-modal.open { opacity: 1; pointer-events: all; }
.vs-struct-browser-sheet {
  width: 100%; max-width: 480px;
  background: var(--card-color);
  border-radius: 20px 20px 0 0;
  padding: 0 0 calc(40px + 0px);
  max-height: 78vh;
  display: flex; flex-direction: column;
  transform: translateY(30px);
  transition: transform 0.22s cubic-bezier(0.32,0.72,0,1);
}
.vs-struct-browser-modal.open .vs-struct-browser-sheet { transform: translateY(0); }
.vs-struct-browser-hdr {
  display: flex; align-items: center; gap: 10px;
  padding: 16px 16px 12px;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.vs-struct-browser-hdr-icon {
  width: 28px; height: 28px;
  display: grid; place-items: center;
  font-size: 1.4rem; line-height: 1; color: var(--secondary-color);
}
.vs-struct-browser-hdr-title {
  flex: 1; font-size: 1rem; font-weight: 800; color: var(--font-color);
}
.vs-struct-browser-close {
  width: 32px; height: 32px; border-radius: 50%; border: 0;
  display: grid; place-items: center;
  background: transparent; color: var(--muted-color); cursor: pointer;
  font-size: 1.1rem;
}
.vs-struct-browser-close .material-symbols-outlined {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  line-height: 1;
}
.vs-struct-browser-list {
  flex: 1; overflow-y: auto; padding: 8px 12px;
}
.vs-struct-browser-empty {
  padding: 32px 20px;
  text-align: center;
  color: var(--muted-color);
  font-size: 0.9rem;
  line-height: 1.6;
}
.vs-struct-browser-item {
  display: flex; align-items: center; gap: 12px;
  width: 100%; padding: 12px 10px;
  background: transparent;
  border: 0; border-radius: 12px;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s;
}
.vs-struct-browser-item:active { background: color-mix(in srgb, var(--secondary-color) 10%, transparent); }
.vs-struct-browser-item-icon {
  width: 40px; height: 40px; border-radius: 10px; flex-shrink: 0;
  background: color-mix(in srgb, var(--secondary-color) 14%, var(--primary-color));
  display: inline-grid;
  place-items: center;
  padding: 0;
  color: var(--secondary-color);
  font-size: 1.35rem;
  line-height: 1;
  text-align: center;
}
.vs-struct-browser-item-icon .material-symbols-outlined {
  display: block;
  font-size: 1.35rem;
  line-height: 1;
  transform: translateY(2px);
}
.vs-struct-browser-item-copy {
  flex: 1; min-width: 0;
}
.vs-struct-browser-item-ref {
  font-size: 0.95rem; font-weight: 700; color: var(--font-color);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.vs-struct-browser-item-meta {
  font-size: 0.75rem; color: var(--muted-color); margin-top: 2px;
}
.vs-struct-browser-item-arrow {
  width: 24px; height: 24px;
  display: grid; place-items: center;
  color: var(--muted-color); font-size: 1.1rem; line-height: 1; flex-shrink: 0;
}
.vs-struct-browser-delete {
  width: 34px; height: 34px; border-radius: 50%; flex-shrink: 0;
  display: inline-grid; place-items: center;
  color: #dc2626;
  background: color-mix(in srgb, #dc2626 8%, transparent);
  cursor: pointer;
}
.vs-struct-browser-delete .material-symbols-outlined {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  font-size: 1.1rem;
  line-height: 1;
}
.vs-struct-browser-delete:active {
  background: color-mix(in srgb, #dc2626 18%, transparent);
}

/* File cabinet button in VS header */
.vs-cabinet-btn {
  position: relative;
  width: 38px; height: 38px; border-radius: 50%; border: 0;
  display: flex; align-items: center; justify-content: center;
  background: transparent;
  color: var(--font-color);
  cursor: pointer;
  transition: background 0.15s;
}
.vs-cabinet-btn:active { background: color-mix(in srgb, var(--secondary-color) 22%, transparent); }
.vs-cabinet-btn .material-symbols-outlined { font-size: 1.2rem; }
.vs-cabinet-badge {
  position: absolute; top: 4px; right: 4px;
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--secondary-color);
  display: none;
}
.vs-cabinet-badge.visible { display: block; }

.vs-struct-study-save-modal {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0; z-index: 9996;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(0,0,0,0.45);
  opacity: 0; pointer-events: none;
  transition: opacity 0.22s;
}
.vs-struct-study-save-modal.open { opacity: 1; pointer-events: all; }
.vs-struct-study-save-sheet {
  width: 100%; max-width: 480px;
  background: var(--card-color);
  border-radius: 20px 20px 0 0;
  padding: 0 0 calc(20px + 0px);
  max-height: 78vh;
  display: flex; flex-direction: column;
  transform: translateY(30px);
  transition: transform 0.22s cubic-bezier(0.32,0.72,0,1);
}
.vs-struct-study-save-modal.open .vs-struct-study-save-sheet { transform: translateY(0); }
.vs-struct-study-save-list {
  flex: 1;
  overflow-y: auto;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.vs-struct-study-choice {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: 12px;
  background: var(--primary-color);
}
.vs-struct-study-choice input { width: 18px; height: 18px; flex-shrink: 0; }
.vs-struct-study-choice-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
  font-size: 1.2rem;
  line-height: 1;
  flex-shrink: 0;
}
.vs-struct-study-choice-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.vs-struct-study-choice-copy strong {
