/* ═══════════════════════════════════════════════════════════════════════════
   CALENDAR EVENTS FEATURE
   ═══════════════════════════════════════════════════════════════════════════ */

.home-calendar-btn {
  position: relative;
  width: 36px;
  height: 40px;
  border-radius: 50%;
  background: transparent;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: inherit;
  margin-right: -2px;
}
.home-calendar-btn + .home-bell-btn { margin-left: 0; }
.home-calendar-btn .material-symbols-outlined { font-size: 26px; }

.cal-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.55);
  z-index: 1200;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  backdrop-filter: blur(2px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.24s ease;
}
.cal-modal-overlay.open {
  opacity: 1;
  pointer-events: auto;
}
.cal-modal-sheet {
  background: var(--card-bg, #fff);
  border-radius: 24px 24px 0 0;
  width: 100%;
  max-width: 540px;
  height: calc(100dvh - max(54px, calc(env(safe-area-inset-top) + 38px)));
  max-height: calc(100dvh - max(12px, env(safe-area-inset-top)));
  margin-top: max(12px, env(safe-area-inset-top));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transform: translateY(105%);
  transition: transform 0.28s cubic-bezier(0.2, 0.85, 0.25, 1);
  will-change: transform;
}
.cal-modal-overlay.open .cal-modal-sheet { transform: translateY(0); }
.cal-modal-overlay.is-closing .cal-modal-sheet { transform: translateY(105%); }
.cal-form-sheet {
  height: calc(100dvh - max(42px, calc(env(safe-area-inset-top) + 30px)));
  max-height: calc(100dvh - max(12px, env(safe-area-inset-top)));
}

.cal-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 10px;
  border-bottom: 1px solid var(--border-color, rgba(0,0,0,0.08));
  flex-shrink: 0;
}
.cal-modal-title { font-size: 1rem; font-weight: 700; }
.cal-back-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: inherit;
  display: flex;
  align-items: center;
  padding: 4px;
  border-radius: 8px;
}
.cal-add-btn {
  background: var(--secondary-color, #6c63ff);
  border: none;
  border-radius: 50%;
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  cursor: pointer;
}
.cal-text-btn {
  background: none;
  border: none;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--muted-color, #888);
  cursor: pointer;
  padding: 4px 8px;
  font-family: inherit;
}
.cal-text-btn--primary { color: var(--secondary-color, #6c63ff); }
.cal-text-btn:disabled {
  opacity: 0.48;
  pointer-events: none;
}

.cal-month-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px 4px;
  flex-shrink: 0;
}
.cal-month-label { font-size: 1rem; font-weight: 700; }
.cal-nav-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: inherit;
  display: flex;
  align-items: center;
  padding: 4px;
  border-radius: 8px;
}

.cal-grid-wrap { padding: 0 12px; flex-shrink: 0; }
.cal-day-headers {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  text-align: center;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--muted-color, #888);
  padding: 4px 0 2px;
}
.cal-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
}
.cal-cell {
  background: none;
  border: none;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 5px 2px 3px;
  cursor: pointer;
  min-height: 40px;
  gap: 2px;
  color: inherit;
  transition: background 0.15s;
}
.cal-cell:active { background: rgba(108,99,255,0.12); }
.cal-cell--empty { pointer-events: none; }
.cal-cell-num { font-size: 0.85rem; font-weight: 500; }
.cal-cell--today .cal-cell-num {
  background: var(--secondary-color, #6c63ff);
  color: #fff;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}
.cal-cell--selected:not(.cal-cell--today) {
  background: rgba(108,99,255,0.12);
}
.cal-cell--selected:not(.cal-cell--today) .cal-cell-num {
  font-weight: 700;
  color: var(--secondary-color, #6c63ff);
}
.cal-event-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--secondary-color, #6c63ff);
}

.cal-events-section {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 10px 16px 24px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.cal-events-label { font-size: 0.9rem; font-weight: 700; margin-bottom: 8px; }
.cal-events-list { display: flex; flex-direction: column; gap: 8px; }
.cal-no-events {
  font-size: 0.85rem;
  color: var(--muted-color, #888);
  text-align: center;
  padding: 20px 0;
  margin: 0;
}
.cal-event-card {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--card-bg-2, rgba(0,0,0,0.04));
  border: none;
  border-radius: 14px;
  padding: 12px 14px;
  cursor: pointer;
  text-align: left;
  width: 100%;
  color: inherit;
  font-family: inherit;
  transition: background 0.15s;
}
.cal-event-card:active { background: rgba(108,99,255,0.1); }
.cal-event-time {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--secondary-color, #6c63ff);
  white-space: nowrap;
  min-width: 52px;
}
.cal-event-info { flex: 1; min-width: 0; }
.cal-event-title {
  font-size: 0.9rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cal-event-loc {
  font-size: 0.75rem;
  color: var(--muted-color, #888);
  display: flex;
  align-items: center;
  gap: 2px;
  margin-top: 2px;
}
.cal-evt-pill {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 20px;
  white-space: nowrap;
}
.cal-evt-pill--accepted { background: rgba(46,204,113,0.15); color: #27ae60; }
.cal-evt-pill--pending  { background: rgba(243,156,18,0.15);  color: #e67e22; }
.cal-evt-pill--declined { background: rgba(231,76,60,0.12);   color: #c0392b; }
.cal-evt-pill--creator  { background: rgba(108,99,255,0.12);  color: var(--secondary-color, #6c63ff); }

.cal-form-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 16px 16px calc(0px + 42px);
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.cal-field-group { display: flex; flex-direction: column; gap: 4px; }
.cal-field-group--half { flex: 1; }
.cal-field-row { display: flex; gap: 12px; }
.cal-field-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--muted-color, #888);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.cal-input {
  background: var(--card-bg-2, rgba(0,0,0,0.05));
  border: 1.5px solid transparent;
  border-radius: 12px;
  padding: 11px 14px;
  font-size: 0.9rem;
  font-family: inherit;
  color: inherit;
  width: 100%;
  box-sizing: border-box;
  transition: border-color 0.15s;
}
.cal-input:focus { outline: none; border-color: var(--secondary-color, #6c63ff); }
.cal-textarea { resize: none; min-height: 70px; }
.cal-picker-btn {
  appearance: none;
  background: var(--card-bg-2, rgba(0,0,0,0.05));
  border: 1.5px solid transparent;
  border-radius: 14px;
  padding: 11px 12px;
  min-height: 46px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted-color, #666);
  font: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  text-align: left;
  cursor: pointer;
  width: 100%;
}
.cal-picker-btn .material-symbols-outlined {
  font-size: 19px;
  color: var(--secondary-color, #6c63ff);
}
.cal-picker-btn.is-set {
  color: var(--text-color, #222);
  background: color-mix(in srgb, var(--secondary-color, #6c63ff) 10%, var(--card-bg, #fff));
  border-color: color-mix(in srgb, var(--secondary-color, #6c63ff) 22%, transparent);
}
.cal-section-label {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--muted-color, #888);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-top: 4px;
}
.cal-hint { font-size: 0.82rem; color: var(--muted-color, #888); margin: 4px 0; }

.event-invite-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(136px, 1fr));
  gap: 8px;
  padding-bottom: 18px;
}
.event-invite-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 2px;
}
.event-invite-header .cal-section-label {
  margin: 0;
}
.event-select-all-btn {
  border: 1.5px solid color-mix(in srgb, var(--secondary-color, #6c63ff) 22%, transparent);
  background: color-mix(in srgb, var(--secondary-color, #6c63ff) 8%, transparent);
  color: var(--secondary-color, #6c63ff);
  border-radius: 999px;
  padding: 6px 11px;
  font: inherit;
  font-size: 0.76rem;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
}
.event-select-all-btn:disabled {
  opacity: 0.45;
  cursor: default;
}
.event-invite-friend-btn {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  background: var(--card-bg-2, rgba(0,0,0,0.04));
  border: 1.5px solid transparent;
  border-radius: 14px;
  padding: 9px 10px;
  cursor: pointer;
  text-align: left;
  width: 100%;
  color: inherit;
  font-family: inherit;
  transition: all 0.15s;
}
.event-invite-friend-btn.invited {
  background: rgba(108,99,255,0.1);
  border-color: var(--secondary-color, #6c63ff);
}
.eif-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  background: color-mix(in srgb, var(--secondary-color, #6c63ff) 14%, transparent);
  color: var(--secondary-color, #6c63ff);
  font-size: 0.78rem;
  font-weight: 900;
}
.eif-name {
  min-width: 0;
  flex: 1;
  font-size: 0.86rem;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.eif-check { font-size: 20px; color: var(--muted-color, #aaa); flex: 0 0 auto; }
.event-invite-friend-btn.invited .eif-check { color: var(--secondary-color, #6c63ff); }

.event-reminders-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(142px, 1fr));
  gap: 7px;
  padding: 10px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--secondary-color, #6c63ff) 7%, var(--card-bg-2, rgba(0,0,0,0.04)));
  border: 1px solid color-mix(in srgb, var(--secondary-color, #6c63ff) 16%, transparent);
}
.event-reminder-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 10px;
  cursor: pointer;
  font-size: 0.88rem;
  font-weight: 500;
  transition: background 0.12s;
}
.event-reminder-row:hover { background: var(--card-bg-2, rgba(0,0,0,0.04)); }
.event-reminder-cb { width: 18px; height: 18px; accent-color: var(--secondary-color, #6c63ff); cursor: pointer; }

.evt-detail-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.evt-detail-header { display: flex; align-items: flex-start; gap: 10px; justify-content: space-between; }
.evt-detail-title { font-size: 1.2rem; font-weight: 800; margin: 0; flex: 1; }
.evt-edit-btn {
  background: var(--card-bg-2, rgba(0,0,0,0.06));
  border: none;
  border-radius: 10px;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: inherit;
  flex-shrink: 0;
}
.evt-meta { display: flex; flex-direction: column; gap: 6px; }
.evt-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.88rem;
  color: var(--muted-color, #666);
}
.evt-meta-row .material-symbols-outlined { font-size: 18px; }
.evt-desc { font-size: 0.88rem; line-height: 1.5; margin: 0; }
.evt-section-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted-color, #888);
  margin-bottom: 6px;
}
.evt-attendees { display: flex; flex-direction: column; gap: 2px; }
.evt-attendees-btn {
  width: 100%;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 10px;
  background: var(--card-bg-2, rgba(0,0,0,0.05));
  border: 1px solid var(--border-color, rgba(0,0,0,0.08));
  border-radius: 14px;
  color: var(--font-color);
  cursor: pointer;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 800;
  padding: 12px 14px;
  text-align: left;
}
.evt-attendees-btn .material-symbols-outlined { color: var(--secondary-color); font-size: 21px; }
.evt-attendees-btn small {
  color: var(--muted-color);
  font-size: 0.76rem;
  font-weight: 750;
  white-space: nowrap;
}
.evt-attendees-summary {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 14px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
}
.evt-attendees-summary strong { font-size: 1rem; }
.evt-attendees-summary span { color: var(--muted-color); font-size: 0.82rem; font-weight: 750; }
.evt-attendee-group { display: flex; flex-direction: column; gap: 2px; }
.evt-attendee {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  font-size: 0.88rem;
  font-weight: 500;
}
.evt-attendee small { margin-left: auto; color: var(--muted-color); font-size: 0.74rem; font-weight: 750; }
.evt-att-icon { font-size: 18px; }
.evt-attendee--creator .evt-att-icon { color: var(--secondary-color); }
.evt-attendee--accepted .evt-att-icon { color: #27ae60; }
.evt-attendee--declined .evt-att-icon { color: #c0392b; }
.evt-attendee--pending  .evt-att-icon { color: #e67e22; }
.evt-attendee-empty {
  color: var(--muted-color);
  font-size: 0.84rem;
  padding: 8px 0;
}

.evt-add-cal-row { display: flex; gap: 8px; }
.evt-add-cal-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: var(--card-bg-2, rgba(0,0,0,0.05));
  border: none;
  border-radius: 12px;
  padding: 10px 12px;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  color: inherit;
  text-decoration: none;
  font-family: inherit;
  transition: background 0.15s;
}
.evt-add-cal-btn:active { background: rgba(108,99,255,0.1); }
.evt-add-cal-btn .material-symbols-outlined { font-size: 18px; }
.evt-google-synced {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border-radius: 14px;
  padding: 10px 12px;
  background: rgba(46,204,113,0.12);
  color: #27ae60;
  font-size: 0.84rem;
  font-weight: 800;
}
.evt-google-synced .material-symbols-outlined { font-size: 18px; }

.evt-rsvp-section { display: flex; flex-direction: column; gap: 10px; }
.evt-rsvp-btns { display: flex; gap: 10px; }
.evt-rsvp-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: none;
  border-radius: 14px;
  padding: 12px;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.15s;
}
.evt-rsvp-btn--accept { background: rgba(46,204,113,0.15); color: #27ae60; }
.evt-rsvp-btn--decline { background: rgba(231,76,60,0.1); color: #c0392b; }
.evt-cancel-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: none;
  border: 1.5px solid rgba(231,76,60,0.3);
  border-radius: 14px;
  padding: 12px;
  font-size: 0.88rem;
  font-weight: 600;
  color: #c0392b;
  cursor: pointer;
  font-family: inherit;
  margin-top: 4px;
}

.cal-sync-overlay { align-items: center; }
.cal-sync-card {
  background: var(--card-bg, #fff);
  border-radius: 24px;
  max-width: 360px;
  width: calc(100% - 40px);
  padding: 28px 24px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  position: relative;
  transform: translateY(18px) scale(0.96);
  opacity: 0;
  transition: transform 0.24s ease, opacity 0.24s ease;
}
.cal-modal-overlay.open .cal-sync-card {
  transform: translateY(0) scale(1);
  opacity: 1;
}
.cal-commit-overlay { align-items: center; }
.cal-commit-card {
  background: var(--card-bg, #fff);
  border-radius: 24px;
  max-width: 390px;
  width: calc(100% - 36px);
  padding: 28px 22px 22px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  position: relative;
  transform: translateY(18px) scale(0.96);
  opacity: 0;
  transition: transform 0.24s ease, opacity 0.24s ease;
}
.cal-modal-overlay.open .cal-commit-card {
  transform: translateY(0) scale(1);
  opacity: 1;
}
.event-commit-list {
  width: 100%;
  display: grid;
  gap: 8px;
  max-height: 220px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.event-commit-item,
.event-commit-open,
.event-commit-empty {
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 14px;
  background: var(--card-bg-2, rgba(0,0,0,0.05));
  padding: 10px 12px;
  text-align: left;
  font-size: 0.86rem;
}
.event-commit-time {
  min-width: 62px;
  color: var(--secondary-color, #6c63ff);
  font-weight: 900;
  white-space: nowrap;
}
.event-commit-title {
  min-width: 0;
  flex: 1;
  font-weight: 750;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.event-commit-open {
  color: #27ae60;
  font-weight: 800;
  justify-content: center;
}
.event-commit-open .material-symbols-outlined { font-size: 20px; }
.event-commit-empty {
  color: var(--muted-color, #666);
  justify-content: center;
  line-height: 1.35;
}
.event-commit-actions {
  width: 100%;
  display: flex;
  gap: 10px;
}
.cal-sync-dismiss-btn {
  position: absolute;
  top: 14px;
  right: 14px;
  background: var(--card-bg-2, rgba(0,0,0,0.06));
  border: none;
  border-radius: 50%;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--muted-color, #888);
}
.cal-sync-icon-wrap {
  background: rgba(108,99,255,0.1);
  width: 64px;
  height: 64px;
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 4px;
}
.cal-sync-icon-wrap .material-symbols-outlined {
  font-size: 34px;
  color: var(--secondary-color, #6c63ff);
}
.cal-sync-title { font-size: 1.05rem; font-weight: 800; margin: 0; }
.cal-sync-body {
  font-size: 0.85rem;
  line-height: 1.5;
  color: var(--muted-color, #666);
  margin: 0;
}
.cal-sync-btns { width: 100%; }
.cal-sync-later-btn {
  background: none;
  border: none;
  font-size: 0.85rem;
  color: var(--muted-color, #888);
  cursor: pointer;
  padding: 8px;
  font-family: inherit;
}

.cal-picker-overlay {
  z-index: 1250;
  background: rgba(0,0,0,0.34);
}
.cal-picker-sheet {
  width: 100%;
  max-width: 440px;
  height: min(46dvh, 390px);
  min-height: 318px;
  max-height: calc(100dvh - max(18px, env(safe-area-inset-top)));
  margin-top: max(18px, env(safe-area-inset-top));
  background: var(--card-bg, #fff);
  border-radius: 24px 24px 0 0;
  overflow: hidden;
  box-shadow: 0 -16px 44px rgba(0,0,0,0.2);
  transform: translateY(105%);
  transition: transform 0.28s cubic-bezier(0.2, 0.85, 0.25, 1);
}
.cal-modal-overlay.open .cal-picker-sheet { transform: translateY(0); }
.cal-modal-overlay.is-closing .cal-picker-sheet { transform: translateY(105%); }
.cal-picker-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 10px;
  border-bottom: 1px solid var(--border-color, rgba(0,0,0,0.08));
}
.cal-picker-body {
  padding: 12px 16px calc(16px + 0px);
  height: calc(100% - 55px);
  box-sizing: border-box;
}
.cal-picker-monthbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.cal-picker-monthbar strong {
  font-size: 1rem;
  font-weight: 900;
}
.cal-picker-weekdays,
.cal-picker-date-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 5px;
}
.cal-picker-weekdays {
  color: var(--muted-color, #888);
  font-size: 0.68rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: 5px;
}
.cal-picker-day {
  aspect-ratio: 1;
  min-height: 36px;
  border: none;
  border-radius: 12px;
  background: var(--card-bg-2, rgba(0,0,0,0.04));
