  font-size: 0.9rem;
  font-weight: 950;
}
.mem-progress-block-head .material-symbols-outlined {
  width: 28px;
  height: 28px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
  font-size: 1.05rem;
}
.mem-chip-list,
.mem-phrase-list,
.mem-mode-stats,
.mem-recent-checks {
  display: grid;
  gap: 7px;
  margin-top: 10px;
}
.mem-chip-list {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.mem-chip-list span,
.mem-phrase-list span,
.mem-mode-stats div,
.mem-recent-checks div {
  min-width: 0;
  border-radius: 14px;
  padding: 9px 10px;
  background: color-mix(in srgb, var(--secondary-color) 7%, transparent);
  color: var(--font-color);
  font-size: 0.82rem;
  font-weight: 850;
  overflow-wrap: anywhere;
}
.mem-chip-list small,
.mem-phrase-list small {
  color: var(--secondary-color);
  font-weight: 950;
}
.mem-mode-stats div,
.mem-recent-checks div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.mem-mode-stats span,
.mem-recent-checks span {
  color: var(--muted-color);
  font-size: 0.76rem;
  font-weight: 850;
  text-align: right;
}
.mem-library-tabs {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr 1fr;
  gap: 7px;
  margin: 0 0 12px;
  padding: 4px;
  border-radius: 18px;
  background: color-mix(in srgb, var(--secondary-color) 8%, transparent);
}
.mem-library-tabs button {
  min-height: 38px;
  border: 0;
  border-radius: 13px;
  background: transparent;
  color: var(--muted-color);
  font-size: 0.76rem;
  font-weight: 950;
}
.mem-library-tabs button.active {
  background: var(--card-color);
  color: var(--secondary-color);
  box-shadow: 0 6px 14px rgba(0,0,0,0.06);
}
.mem-saved-list { display: grid; gap: 9px; }
.mem-saved-item {
  display: grid;
  grid-template-columns: 1fr 38px;
  align-items: center;
  gap: 7px;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 12%, transparent);
  background: color-mix(in srgb, var(--card-color) 70%, var(--bg-color));
  padding: 7px;
}
.mem-saved-item.active { border-color: color-mix(in srgb, var(--secondary-color) 58%, var(--border-color)); }
.mem-saved-main {
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--font-color);
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: 9px;
  align-items: center;
  text-align: left;
}
.mem-saved-main .material-symbols-outlined {
  width: 38px;
  height: 38px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 10%, transparent);
}
.mem-saved-main span:last-child { min-width: 0; display: grid; gap: 2px; }
.mem-saved-main strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.9rem;
  font-weight: 950;
}
.mem-saved-main small { color: var(--muted-color); font-size: 0.74rem; font-weight: 800; }
.mem-saved-delete {
  width: 38px;
  height: 38px;
  border: 0;
  border-radius: 13px;
  display: grid;
  place-items: center;
  color: var(--muted-color);
  background: transparent;
}

/* ── Memorization: lively tap feedback + premium entrances ──────────────────────
   Brings the workshop up to the Journey-Maps feel: every tappable element
   springs on press, the active mode/tab pops, and views rise in on open. */
.mem-hub-tabs button,
.mem-source-tabs button,
.mem-library-tabs button,
.mem-icon-btn,
.mem-secondary-btn,
.mem-primary-btn,
.mem-progress-btn,
.mem-best-chip,
.mem-mode-wheel button,
.mem-saved-main,
.mem-saved-delete {
  transition: transform 0.14s cubic-bezier(.2, .82, .18, 1),
              background 0.18s ease, border-color 0.18s ease,
              box-shadow 0.18s ease, color 0.18s ease, opacity 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}
.mem-hub-tabs button:active,
.mem-source-tabs button:active,
.mem-library-tabs button:active,
.mem-secondary-btn:active,
.mem-progress-btn:active,
.mem-saved-main:active { transform: scale(0.965); }
.mem-icon-btn:active,
.mem-saved-delete:active { transform: scale(0.9); }
.mem-mode-wheel button:active { transform: scale(0.94); }
.mem-best-chip:active { transform: scale(0.95); }

/* Primary action button: theme-glow that depresses on tap. */
.mem-primary-btn { box-shadow: 0 8px 20px color-mix(in srgb, var(--secondary-color) 24%, transparent); }
.mem-primary-btn:active { transform: scale(0.975); box-shadow: 0 3px 10px color-mix(in srgb, var(--secondary-color) 30%, transparent); }

/* Selecting a practice mode pops it. */
.mem-mode-wheel button.active { animation: memPop 0.26s cubic-bezier(.2, .82, .18, 1); }
@keyframes memPop {
  0% { transform: scale(0.92); }
  60% { transform: scale(1.045); }
  100% { transform: scale(1); }
}

/* Views and key cards rise/fade in for a lively, premium entrance. */
.mem-view:not(.hidden) { animation: memViewIn 0.34s cubic-bezier(.2, .82, .18, 1); }
@keyframes memViewIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: none; }
}
.mem-preview-card, .mem-verse-stage { animation: memCardIn 0.3s cubic-bezier(.2, .82, .18, 1); }
@keyframes memCardIn {
  from { opacity: 0; transform: translateY(6px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mem-view:not(.hidden),
  .mem-mode-wheel button.active,
  .mem-preview-card,
  .mem-verse-stage { animation: none !important; }
}
@media (min-width: 520px) {
  .mem-mode-wheel { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 360px) {
  .mem-practice-top {
    flex-direction: column;
  }
  .mem-practice-actions {
    width: 100%;
    justify-content: space-between;
  }
  .mem-chip-list {
    grid-template-columns: 1fr;
  }
}

/* =========================================================================
   READING PLAN — full-screen tool (themed to the user's selected palette)
   ========================================================================= */
#readingPlanPage.screen.active {
  display: block;
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  height: 100vh;
  height: 100dvh;
  z-index: 1000;
  overflow: hidden;
  background: var(--primary-light) !important;
  /* Strip the generic .screen.active card look (18px padding + rounded corners +
     shadow) so the page is true full-bleed, like the Journey maps. */
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
html.reading-plan-active { background: var(--primary-light) !important; }
body.reading-plan-active,
body.reading-plan-active .app {
  width: 100%;
  max-width: none !important;
  height: 100vh; height: 100dvh;
  min-height: 0;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  background: var(--primary-light) !important;
  overscroll-behavior: none;
}
body.reading-plan-active .desktop-shell-nav,
body.reading-plan-active .app-header,
body.reading-plan-active .bottom-nav,
body.reading-plan-active #bottomNav,
body.reading-plan-active #studyTabBar { display: none !important; }
/* Status-bar backer matches the reading-plan page so the top edge is one
   continuous color, not a separate bar above the topbar. */
body.reading-plan-active #statusBarBg {
  background: var(--primary-light) !important;
}

.rp-page {
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
  overflow: hidden;
  color: var(--font-color);
}
.rp-topbar {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: 46px minmax(0,1fr) 46px;
  align-items: center;
  gap: 10px;
  padding: calc(env(safe-area-inset-top, 0px) + 22px) 16px 12px;
  background: var(--primary-light);
}
.rp-icon-btn {
  width: 46px; height: 46px;
  display: grid; place-items: center;
  border-radius: 14px;
  border: 1px solid var(--border-color);
  background: var(--card-color);
  color: var(--secondary-color);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.rp-icon-btn:active { transform: scale(0.94); }
.rp-icon-ghost { border: 0; background: transparent; opacity: 0.5; pointer-events: none; }
.rp-title-stack { text-align: center; min-width: 0; }
.rp-title-stack .rp-kicker {
  display: block; font-size: 0.7rem; font-weight: 800; letter-spacing: 0.06em;
  text-transform: uppercase; color: var(--secondary-color); opacity: 0.85;
}
.rp-title-stack strong { display: block; font-size: 1.12rem; font-weight: 900; color: var(--font-color); }

.rp-tabs {
  flex: 0 0 auto;
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
  padding: 4px 16px 10px;
}
.rp-tabs button {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 11px 8px; border-radius: 14px;
  border: 1px solid var(--border-color);
  background: var(--card-color); color: var(--muted-color);
  font-weight: 800; font-size: 0.86rem; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.rp-tabs button .material-symbols-outlined { font-size: 1.15rem; }
.rp-tabs button.active {
  background: var(--secondary-color); color: var(--btn-text-color);
  border-color: var(--secondary-color);
  box-shadow: 0 8px 18px color-mix(in srgb, var(--secondary-color) 24%, transparent);
}

.rp-scroll {
  flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden;
  padding: 4px 16px calc(env(safe-area-inset-bottom, 0px) + 36px);
  -webkit-overflow-scrolling: touch;
}
.rp-view.hidden { display: none; }

.rp-welcome { color: var(--muted-color); font-size: 0.92rem; line-height: 1.45; margin: 6px 2px 16px; }
.rp-muted { color: var(--muted-color); opacity: 0.85; }

.rp-step { margin-bottom: 18px; }
.rp-step-label {
  display: flex; align-items: center; gap: 8px;
  font-weight: 850; font-size: 0.98rem; color: var(--font-color);
  margin: 0 2px 10px;
}
.rp-step-num {
  width: 22px; height: 22px; flex: 0 0 auto;
  display: grid; place-items: center;
  border-radius: 50%;
  background: var(--secondary-color); color: var(--btn-text-color);
  font-size: 0.72rem; font-weight: 900;
}
.rp-chip-row { display: flex; flex-wrap: wrap; gap: 8px; }
.rp-chip {
  display: inline-flex; flex-direction: column; align-items: flex-start;
  padding: 10px 14px; border-radius: 14px;
  border: 1.5px solid var(--border-color);
  background: var(--card-color); color: var(--font-color);
  font-weight: 800; font-size: 0.88rem; cursor: pointer; line-height: 1.1;
  transition: transform 0.1s, border-color 0.12s, background 0.12s;
  -webkit-tap-highlight-color: transparent;
}
.rp-chip:active { transform: scale(0.96); }
.rp-chip.active {
  background: color-mix(in srgb, var(--secondary-color) 14%, var(--card-color));
  border-color: var(--secondary-color);
  color: var(--secondary-color);
  box-shadow: 0 6px 14px color-mix(in srgb, var(--secondary-color) 16%, transparent);
}
.rp-chip-sub { font-size: 0.68rem; font-weight: 700; opacity: 0.7; margin-top: 3px; }

.rp-subcard {
  margin-top: 12px; padding: 12px;
  border-radius: 16px;
  border: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--secondary-color) 4%, var(--card-color));
}
.rp-mode-toggle { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-bottom: 10px; }
.rp-mode-toggle button {
  display: inline-flex; align-items: center; justify-content: center; gap: 5px;
  padding: 9px; border-radius: 11px;
  border: 1px solid var(--border-color); background: var(--card-color);
  color: var(--muted-color); font-weight: 800; font-size: 0.8rem; cursor: pointer;
}
.rp-mode-toggle button .material-symbols-outlined { font-size: 1.05rem; }
.rp-mode-toggle button.active { background: var(--secondary-color); color: var(--btn-text-color); border-color: var(--secondary-color); }
.rp-picker-open {
  width: 100%;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px; border-radius: 12px;
  border: 1.5px dashed var(--secondary-color);
  background: transparent; color: var(--secondary-color);
  font-weight: 850; font-size: 0.9rem; cursor: pointer;
}
.rp-selection-summary { margin-top: 10px; font-size: 0.86rem; color: var(--font-color); line-height: 1.4; }
.rp-textarea, .rp-name-input, .rp-date {
  width: 100%; max-width: 100%; min-width: 0; box-sizing: border-box;
  padding: 12px 14px; border-radius: 12px;
  border: 1.5px solid var(--border-color);
  background: var(--card-color); color: var(--font-color);
  font-size: 0.92rem; font-family: inherit;
  -webkit-appearance: none; appearance: none;
}
.rp-textarea { min-height: 72px; resize: vertical; }
/* Native date inputs carry an intrinsic min-width that can overflow the
   page and trigger a horizontal scroll — pin it to the container width. */
.rp-date { margin-top: 10px; display: block; }
.rp-date::-webkit-date-and-time-value { text-align: left; }

.rp-calc {
  margin: 6px 0 20px; padding: 16px;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 22%, var(--border-color));
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--secondary-color) 12%, transparent), transparent 60%),
    var(--card-color);
  box-shadow: 0 14px 30px color-mix(in srgb, var(--secondary-color) 12%, transparent);
}
.rp-calc-empty {
  display: flex; align-items: center; gap: 8px;
  color: var(--muted-color); font-size: 0.9rem; font-weight: 700;
}
.rp-calc-empty .material-symbols-outlined { color: var(--secondary-color); }
.rp-calc-warn { color: #b91c1c; }
.rp-calc-warn .material-symbols-outlined { color: #b91c1c; }
.rp-calc-hero { display: flex; align-items: center; gap: 16px; }
.rp-calc-big { text-align: center; flex: 0 0 auto; }
.rp-calc-big strong {
  display: block; font-size: 2.6rem; font-weight: 950; line-height: 1;
  color: var(--secondary-color);
}
.rp-calc-big span { font-size: 0.74rem; font-weight: 800; color: var(--muted-color); text-transform: uppercase; letter-spacing: 0.04em; }
.rp-calc-meta { display: grid; gap: 5px; font-size: 0.86rem; color: var(--font-color); }
.rp-calc-meta div { display: flex; align-items: center; gap: 7px; }
.rp-calc-meta .material-symbols-outlined { font-size: 1.05rem; color: var(--secondary-color); opacity: 0.85; }
.rp-calc-good { color: #15803d; font-weight: 800; }
.rp-calc-good .material-symbols-outlined { color: #16a34a !important; }
.rp-preview {
  margin-top: 14px; padding-top: 12px;
  border-top: 1px solid var(--border-color);
}
.rp-preview-title { font-size: 0.7rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted-color); margin-bottom: 6px; }
.rp-preview-row { font-size: 0.86rem; line-height: 1.4; margin-bottom: 3px; }
.rp-preview-row span { display: inline-block; min-width: 46px; font-weight: 850; color: var(--secondary-color); }

.rp-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 8px; }
.rp-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  padding: 14px 12px; border-radius: 14px;
  font-weight: 850; font-size: 0.9rem; cursor: pointer; border: 1.5px solid transparent;
  -webkit-tap-highlight-color: transparent;
}
.rp-btn .material-symbols-outlined { font-size: 1.15rem; }
.rp-btn:active { transform: scale(0.97); }
.rp-btn-primary { background: var(--secondary-color); color: var(--btn-text-color); box-shadow: 0 10px 22px color-mix(in srgb, var(--secondary-color) 26%, transparent); }
.rp-btn-primary:active { box-shadow: 0 4px 12px color-mix(in srgb, var(--secondary-color) 30%, transparent); }
.rp-btn-ghost { background: var(--card-color); color: var(--secondary-color); border-color: var(--secondary-color); }

/* ── Reading Plan: lively entrances to match the premium tools ──────────────── */
.rp-view:not(.hidden) { animation: rpViewIn 0.32s cubic-bezier(.2, .82, .18, 1); }
@keyframes rpViewIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: none; }
}
.rp-saved-card { transition: transform 0.14s cubic-bezier(.2, .82, .18, 1), box-shadow 0.2s ease; }
.rp-saved-card:active { transform: scale(0.99); }
.rp-tabs button {
  transition: transform 0.14s cubic-bezier(.2, .82, .18, 1),
              background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}
.rp-tabs button:active { transform: scale(0.97); }
.rp-tabs button.active { animation: memPop 0.26s cubic-bezier(.2, .82, .18, 1); }
@media (prefers-reduced-motion: reduce) {
  .rp-view:not(.hidden), .rp-tabs button.active { animation: none !important; }
}
.rp-cancel-edit {
  display: block; margin: 14px auto 0; padding: 8px 16px;
  background: none; border: 0; color: var(--muted-color);
  font-weight: 800; font-size: 0.84rem; cursor: pointer; text-decoration: underline;
}

/* saved plans */
.rp-empty { text-align: center; padding: 48px 16px; color: var(--muted-color); }
.rp-empty .material-symbols-outlined { font-size: 3rem; color: var(--secondary-color); opacity: 0.5; }
.rp-empty p { margin: 10px 0 18px; font-weight: 700; }
.rp-saved-card {
  margin-bottom: 12px; padding: 14px 16px;
  border-radius: 18px;
  border: 1px solid var(--border-color);
  background: var(--card-color);
  box-shadow: 0 8px 20px color-mix(in srgb, var(--secondary-color) 8%, transparent);
}
.rp-saved-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.rp-saved-top strong { font-size: 1.04rem; font-weight: 900; color: var(--font-color); }
.rp-badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 9px; border-radius: 999px;
  background: color-mix(in srgb, #16a34a 16%, transparent); color: #15803d;
  font-size: 0.7rem; font-weight: 850; flex: 0 0 auto;
}
.rp-badge .material-symbols-outlined { font-size: 0.9rem; }
.rp-saved-sub { color: var(--secondary-color); font-weight: 800; font-size: 0.84rem; margin-top: 2px; }
.rp-saved-stats { display: flex; flex-wrap: wrap; gap: 6px 14px; margin: 10px 0; color: var(--muted-color); font-size: 0.84rem; }
.rp-saved-stats strong { color: var(--font-color); font-size: 0.95rem; }
.rp-saved-actions { display: flex; gap: 8px; }
.rp-saved-actions button {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 9px 12px; border-radius: 11px;
  border: 1px solid var(--border-color); background: var(--card-color);
