.rp-saved-actions button .material-symbols-outlined { font-size: 1.05rem; }
.rp-saved-actions .rp-del { margin-left: auto; color: #b91c1c; border-color: color-mix(in srgb, #b91c1c 30%, var(--border-color)); }

/* book picker overlay */
.rp-picker-overlay {
  position: fixed; inset: 0; z-index: 1100;
