.rp-picker-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.rp-picker-hdr strong { font-size: 1.05rem; font-weight: 900; color: var(--font-color); }
.rp-picker-close { width: 38px; height: 38px; display: grid; place-items: center; border: 0; border-radius: 11px; background: color-mix(in srgb, var(--secondary-color) 8%, transparent); color: var(--font-color); cursor: pointer; }
.rp-quick-row { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
.rp-quick { padding: 7px 12px; border-radius: 999px; border: 1px solid var(--border-color); background: var(--card-color); color: var(--secondary-color); font-weight: 800; font-size: 0.78rem; cursor: pointer; }
.rp-quick:active { transform: scale(0.95); }
.rp-picker-search-row {
  display: flex; align-items: center; gap: 8px;
