}
.rp-picker-search-row .material-symbols-outlined { color: var(--muted-color); }
.rp-picker-search { flex: 1; border: 0; background: transparent; padding: 11px 0; font-size: 0.92rem; color: var(--font-color); outline: none; font-family: inherit; }
.rp-book-list { flex: 1; min-height: 0; overflow-y: auto; -webkit-overflow-scrolling: touch; }
.rp-book-sep { font-size: 0.7rem; font-weight: 850; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted-color); padding: 12px 4px 6px; position: sticky; top: 0; background: var(--card-solid-color, #fff); }
.rp-book-row {
  width: 100%; display: flex; align-items: center; gap: 10px;
  padding: 11px 8px; border: 0; background: transparent; cursor: pointer;
