/* ── Rhema verse marks: highlights, note icons, action sheet, note editor ──── */
/* =========================================================================
   BIBLE JOURNEYS - curated follow-along maps
   ========================================================================= */
#journeysPage.screen.active,
#atlasPage.screen.active {
  display: block;
  position: fixed;
  inset: 0;
  height: 100vh;
  height: 100dvh;
  z-index: 1000;
  overflow: hidden;
  /* Full-bleed: drop the generic .screen card frame (padding/radius/shadow) so the
     top bar and content run edge to edge instead of sitting in an inset box. */
  padding: 0;
  border-radius: 0;
  box-shadow: none;
  /* Cancel the generic .screen fade — these pages drive their own open/close/slide
     transitions. Leaving screenFade in re-fires it when a transition class is
     removed, which caused a post-open "reposition" flicker. */
  animation: none;
  background: var(--primary-light) !important;
}
/* Press-to-expand: the page grows out of the home widget's footprint. */
@keyframes journeyScreenExpand {
  from { clip-path: inset(var(--exp-t, 35%) var(--exp-r, 8%) var(--exp-b, 40%) var(--exp-l, 8%) round 22px); opacity: 0.5; }
  to   { clip-path: inset(0px 0px 0px 0px round 0px); opacity: 1; }
}
/* Collapse: the reverse, folding the page back into the widget on the way home. */
@keyframes journeyScreenCollapse {
  from { clip-path: inset(0px 0px 0px 0px round 0px); opacity: 1; }
  to   { clip-path: inset(var(--exp-t, 35%) var(--exp-r, 8%) var(--exp-b, 40%) var(--exp-l, 8%) round 22px); opacity: 0; }
}
/* Themed ring + inner glow that rides the rounded clip edge while the page grows
   or folds, so opening and closing feel deliberate and on-theme. */
#atlasPage.screen.active.screen-expanding,
#journeysPage.screen.active.screen-expanding {
  animation: journeyScreenExpand 0.46s cubic-bezier(.4, 0, .2, 1) both;
  box-shadow:
    inset 0 0 0 2px color-mix(in srgb, var(--secondary-color) 55%, transparent),
    inset 0 0 34px color-mix(in srgb, var(--secondary-color) 20%, transparent);
}
#atlasPage.screen.active.screen-collapsing,
#journeysPage.screen.active.screen-collapsing {
  animation: journeyScreenCollapse 0.40s cubic-bezier(.4, 0, .2, 1) forwards;
  z-index: 1002;
  box-shadow:
    inset 0 0 0 2px color-mix(in srgb, var(--secondary-color) 55%, transparent),
    inset 0 0 34px color-mix(in srgb, var(--secondary-color) 20%, transparent);
}
/* Slide a place detail in/out as an overlay above the Atlas list (which stays
   visible underneath, so there's no blank flash on the way back). */
@keyframes atlasDetailIn { from { transform: translateX(100%); opacity: 0.65; } to { transform: translateX(0); opacity: 1; } }
@keyframes atlasDetailOut { from { transform: translateX(0); opacity: 1; } to { transform: translateX(100%); opacity: 0.65; } }
.atlas-content { flex: 1; min-height: 0; position: relative; display: flex; flex-direction: column; }
.atlas-detailpage.detail-in,
.atlas-detailpage.detail-out {
  position: absolute;
  inset: 0;
  z-index: 5;
  background: var(--primary-light);
  box-shadow: -14px 0 30px color-mix(in srgb, var(--secondary-color) 26%, transparent);
}
.atlas-detailpage.detail-in { animation: atlasDetailIn 0.32s cubic-bezier(.4, 0, .2, 1); }
.atlas-detailpage.detail-out { animation: atlasDetailOut 0.30s cubic-bezier(.4, 0, .2, 1) forwards; }
/* Atlas tab swap (Journeys ⇄ Places). */
@keyframes atlasListInRight { from { opacity: 0; transform: translateX(16px); } to { opacity: 1; transform: none; } }
@keyframes atlasListInLeft { from { opacity: 0; transform: translateX(-16px); } to { opacity: 1; transform: none; } }
.atlas-list.swap-right { animation: atlasListInRight 0.24s cubic-bezier(.4, 0, .2, 1); }
.atlas-list.swap-left { animation: atlasListInLeft 0.24s cubic-bezier(.4, 0, .2, 1); }
@media (prefers-reduced-motion: reduce) {
  #atlasPage.screen.active.screen-expanding,
  #atlasPage.screen.active.screen-collapsing,
  #journeysPage.screen.active.screen-collapsing,
  #journeysPage.screen.active.screen-slide-in-right,
  #journeysPage.screen.active.screen-slide-out-right,
  .atlas-detailpage.detail-in,
  .atlas-detailpage.detail-out,
  .atlas-list.swap-right,
  .atlas-list.swap-left { animation: none; }
}

