/* Unified journey card: title + toggle + map + play + facts in one surface,
   matching the focused detail mockup. */
.journey-card {
  display: grid;
  gap: 14px;
  padding: 18px 14px 18px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 12%, var(--border-color));
  border-radius: 24px;
  box-shadow: 0 14px 32px color-mix(in srgb, var(--secondary-color) 11%, transparent);
}
.journey-card-head { display: grid; gap: 5px; }
.journey-card-head h2 {
  margin: 0;
  font-size: clamp(1.45rem, 6.6vw, 2.1rem);
  line-height: 1.04;
  font-weight: 950;
  letter-spacing: -0.01em;
}
.journey-card-head p {
  margin: 0;
  color: var(--muted-color);
  line-height: 1.4;
  font-size: 0.92rem;
  font-weight: 650;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.journey-map-shell {
  display: grid;
  gap: 12px;
}
/* Map box that holds the schematic SVG / real GL map plus the compass overlay. */
.journey-map-viewport {
  position: relative;
  border-radius: 18px;
  overflow: hidden;
  background:
    radial-gradient(120% 100% at 80% 0%, color-mix(in srgb, var(--secondary-color) 10%, transparent), transparent 58%),
    color-mix(in srgb, var(--secondary-color) 4%, var(--card-color));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--secondary-color) 10%, transparent);
}
.journey-compass {
  position: absolute;
  right: 12px;
  bottom: 12px;
  z-index: 6;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--card-color) 86%, transparent);
  border: 1px solid color-mix(in srgb, var(--secondary-color) 30%, transparent);
  box-shadow:
    0 6px 16px rgba(20, 28, 34, 0.18),
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
}
.journey-compass-n {
  position: absolute;
  top: 4px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.55rem;
  font-weight: 950;
  letter-spacing: 0.04em;
  color: color-mix(in srgb, var(--font-color) 76%, var(--secondary-color));
}
.journey-compass-needle {
  width: 8px;
  height: 26px;
  margin-top: 7px;
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
  background: linear-gradient(
    to bottom,
    var(--secondary-color) 0 50%,
    color-mix(in srgb, var(--muted-color) 50%, var(--card-color)) 50% 100%);
}
.journey-map-shell svg {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1.1;
  border-radius: 18px;
  overflow: hidden;
}
/* Real MapLibre map swaps in over the schematic SVG when configured + online. */
.journey-gl-map {
  display: none;
  width: 100%;
  aspect-ratio: 1 / 1.1;
  border-radius: 18px;
  overflow: hidden;
  background:
    linear-gradient(150deg, #efe0c0, color-mix(in srgb, var(--secondary-color) 7%, #d6ecf0));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 48%, transparent),
    0 10px 24px color-mix(in srgb, var(--secondary-color) 12%, transparent);
}
.journey-map-shell.gl-mounting .journey-gl-map,
.journey-map-shell.gl-ready .journey-gl-map { display: block; }
.journey-map-shell.gl-mounting svg,
.journey-map-shell.gl-ready svg { display: none; }
/* The real GL map draws its own live, north-pointing compass; hide the static
   schematic one whenever the GL map is showing so they don't double up. */
.journey-map-shell.gl-mounting .journey-compass,
.journey-map-shell.gl-ready .journey-compass { display: none; }
/* Live compass rendered inside any BibleMap (journeys + atlas/places). The rose
   counter-rotates with the map bearing so "N" always points to true north. */
.bible-map-compass {
  position: absolute;
  right: 12px;
  bottom: 12px;
  z-index: 6;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--card-color) 88%, transparent);
  border: 1px solid color-mix(in srgb, var(--secondary-color) 32%, transparent);
  box-shadow:
    0 6px 16px rgba(20, 28, 34, 0.2),
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
}
.bible-map-compass-rose {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  transition: transform 0.3s ease;
  will-change: transform;
}
.bible-map-compass-n {
  position: absolute;
  top: 3px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.56rem;
  font-weight: 950;
  letter-spacing: 0.04em;
  color: color-mix(in srgb, var(--font-color) 78%, var(--secondary-color));
}
.bible-map-compass-needle {
  width: 9px;
  height: 28px;
  margin-top: 6px;
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
  background: linear-gradient(
    to bottom,
    var(--secondary-color) 0 50%,
    color-mix(in srgb, var(--muted-color) 50%, var(--card-color)) 50% 100%);
}
/* Reset-view button: appears top-right once the user pans/zooms the map away
   from its opening framing, and flies the camera back when tapped. */
.bible-map-reset {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 7;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px 8px 10px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 30%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--card-color) 90%, transparent);
