  box-shadow: 0 6px 16px rgba(20, 28, 34, 0.18);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  -webkit-tap-highlight-color: transparent;
  opacity: 0;
  transform: translateY(-6px) scale(0.96);
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
}
.bible-map-reset.visible {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}
.bible-map-reset .material-symbols-outlined { font-size: 18px; }
.bible-map-reset:active { transform: scale(0.95); }
.bible-map-borders-note {
  position: absolute;
  top: 12px;
  left: 12px;
  right: auto;
  z-index: 6;
  max-width: min(64%, 320px);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px 6px 8px;
  border: 1px solid color-mix(in srgb, var(--secondary-color) 24%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--card-color) 88%, transparent);
  color: var(--secondary-color);
  font-size: 0.68rem;
  font-weight: 700;
  line-height: 1.25;
  box-shadow: 0 4px 12px rgba(20, 28, 34, 0.16);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity 0.22s ease, transform 0.22s ease;
}
.bible-map-borders-note.visible { opacity: 0.9; transform: none; }
.bible-map-borders-note .material-symbols-outlined { font-size: 15px; flex: 0 0 auto; }
@media (max-width: 480px) {
  .bible-map-borders-note { font-size: 0.62rem; max-width: 72%; }
}

/* Curated physical-geography labels (seas, rivers, mountains, deserts, regions).
   Font-free: styled HTML markers with a white halo so they read over any
   basemap color. Hidden until their zoom window, then fade in. */
.bmgeo {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.05;
  text-align: center;
  white-space: nowrap;
  pointer-events: none;
  user-select: none;
  opacity: 0;
  transform: translateY(2px);
  transition: opacity 0.35s ease, transform 0.35s ease;
  z-index: 4;
}
.bmgeo.visible { opacity: 1; transform: none; }
.bmgeo-name {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.01em;
  text-shadow: 0 0 3px #fff, 0 0 3px #fff, 0 0 6px #fff, 0 1px 1px rgba(255, 255, 255, 0.9);
}
.bmgeo-sub {
  font-size: 0.56rem;
  font-weight: 650;
  opacity: 0.72;
  margin-top: 1px;
  text-shadow: 0 0 3px #fff, 0 0 3px #fff, 0 0 5px #fff;
}
/* Water — cool blue, italic, gently understated */
.bmgeo-sea .bmgeo-name,
.bmgeo-lake .bmgeo-name,
.bmgeo-river .bmgeo-name { color: #15667f; font-style: italic; }
.bmgeo-sea .bmgeo-sub,
.bmgeo-lake .bmgeo-sub,
.bmgeo-river .bmgeo-sub { color: #15667f; }
.bmgeo-sea .bmgeo-name { letter-spacing: 0.08em; }
/* Mountains — earthy brown with a small peak mark */
.bmgeo-mountain .bmgeo-name { color: #7a5230; }
.bmgeo-mountain .bmgeo-name::before { content: "\25B2\00A0"; font-size: 0.72em; vertical-align: 1px; opacity: 0.85; }
.bmgeo-mountain .bmgeo-sub { color: #7a5230; }
/* Deserts — warm amber, spaced out like open country */
.bmgeo-desert .bmgeo-name { color: #a5701f; letter-spacing: 0.09em; text-transform: uppercase; font-size: 0.64rem; }
.bmgeo-desert .bmgeo-sub { color: #a5701f; }
/* Regions — quiet slate background context */
.bmgeo-region .bmgeo-name { color: #5f6672; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 750; font-size: 0.62rem; opacity: 0.82; }
.bmgeo-region .bmgeo-sub { display: none; }
/* On the parchment (ancient) map, warm the water tone so it sits on paper */
.bmgeo-ancient.bmgeo-sea .bmgeo-name,
.bmgeo-ancient.bmgeo-lake .bmgeo-name,
.bmgeo-ancient.bmgeo-river .bmgeo-name { color: #2b6b7d; }
@media (max-width: 480px) {
  .bmgeo-name { font-size: 0.66rem; }
  .bmgeo-sub { font-size: 0.52rem; }
  .bmgeo-desert .bmgeo-name { font-size: 0.58rem; }
}
