}
.journey-stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.journey-stats > div {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: 32px auto auto;
  align-items: center;
  justify-items: center;
  gap: 3px;
  padding: 10px 6px;
  text-align: center;
}
.journey-stats .material-symbols-outlined {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: var(--secondary-color);
  background: color-mix(in srgb, var(--secondary-color) 11%, transparent);
  font-size: 19px;
}
.journey-stats strong { font-weight: 950; color: var(--font-color); font-size: 0.9rem; }
.journey-stats small { color: var(--muted-color); font-weight: 750; line-height: 1.18; font-size: 0.68rem; }
.journey-steps { padding: 14px 12px; }
.journey-section-head { display: grid; gap: 2px; margin-bottom: 12px; }
.journey-section-head strong { font-size: 1.02rem; font-weight: 950; }
.journey-step {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 10px;
  padding: 12px 0;
  border-top: 1px solid var(--border-color);
}
.journey-step:first-of-type { border-top: 0; }
.journey-step-num {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--secondary-color);
  color: var(--btn-text-color);
  font-weight: 950;
  font-size: 0.82rem;
}
.journey-step strong { display: block; font-weight: 950; color: var(--font-color); }
.journey-step small {
  display: block;
  color: var(--secondary-color);
  font-weight: 850;
  font-size: 0.78rem;
  margin-top: 2px;
}
.journey-step p { margin: 6px 0 0; color: var(--muted-color); line-height: 1.45; font-size: 0.9rem; }
.journey-step { border-radius: 12px; transition: background 0.25s ease; padding-left: 6px; padding-right: 6px; margin: 0 -6px; }
.journey-step-num { transition: transform 0.25s ease, box-shadow 0.25s ease; }
.journey-step.passed .journey-step-num { opacity: 0.55; }
.journey-step.current {
  background: color-mix(in srgb, var(--secondary-color) 9%, transparent);
  border-top-color: transparent;
}
.journey-step.current + .journey-step { border-top-color: transparent; }
.journey-step.current .journey-step-num {
  transform: scale(1.12);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--secondary-color) 22%, transparent);
}
.journey-sources { padding: 14px 12px; }
.journey-source-item {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  padding: 9px 0;
  border-top: 1px solid var(--border-color);
}
.journey-source-item:first-of-type { border-top: 0; }
.journey-source-item .material-symbols-outlined {
  font-size: 18px;
  color: var(--secondary-color);
  margin-top: 1px;
}
.journey-source-item p { margin: 0; color: var(--muted-color); line-height: 1.45; font-size: 0.86rem; }
@media (prefers-reduced-motion: reduce) {
  .journey-route-line { animation: none; }
  .journey-map-point circle,
  .journey-step,
  .journey-step-num { transition: none; }
}
@media (min-width: 760px) {
  .journey-layout { display: grid; grid-template-columns: minmax(220px, 0.34fr) minmax(0, 1fr); align-items: start; }
  .journey-list {
    grid-auto-flow: row;
    grid-auto-columns: auto;
    margin: 0;
    padding: 0 2px 2px;
    overflow-x: hidden;
    overflow-y: auto;
    position: sticky;
    top: 12px;
    max-height: calc(100dvh - 132px);
  }
  .journey-list-heading { display: grid; }
  .journey-stats { grid-template-columns: repeat(3, 1fr); }
}
