  border-radius: 10px; padding: 9px 11px;
  font: inherit; font-size: 0.9rem; color: var(--font-color, #20303f);
  background: var(--primary-light, #f8fbff);
}
.rhema-bn-text.hidden, .rhema-bn-shared.hidden { display: none; }
.rhema-compare-chip-count {
  background: rgba(255, 255, 255, 0.25);
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 0.8rem;
}
.rhema-compare-overlay {
  position: absolute;
  inset: 0;
  z-index: 75;
  background: rgba(8, 18, 28, 0.5);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease;
}
.rhema-compare-overlay.open { opacity: 1; pointer-events: auto; }
.rhema-compare-card {
  width: 100%;
  max-width: 480px;
  max-height: 86%;
  margin: 0 14px;
  display: flex;
  flex-direction: column;
  /* Layered paint: the (possibly translucent) skin card color sits on a solid
     base, so the sheet is always fully opaque — no reader text bleeding through. */
  background: linear-gradient(var(--card-color, #fffdf7), var(--card-color, #fffdf7)), var(--primary-color, #fffdf7);
  color: var(--font-color, #20303f);
  border-radius: 18px;
  box-shadow: 0 18px 44px rgba(8, 18, 28, 0.3);
  overflow: hidden;
  transform: translateY(14px) scale(0.98);
  transition: transform 0.26s cubic-bezier(.2, .82, .18, 1);
}
.rhema-compare-overlay.open .rhema-compare-card { transform: translateY(0) scale(1); }
.rhema-compare-hd {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid rgba(120, 120, 120, 0.18);
}
.rhema-compare-title { font-weight: 800; font-size: 1.05rem; }
.rhema-compare-x { border: none; background: transparent; cursor: pointer; color: var(--font-color, #20303f); }
.rhema-compare-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 10px 16px 0;
}
.rhema-compare-tabs button {
  border: 1px solid rgba(120, 120, 120, 0.2);
  border-radius: 999px;
  background: rgba(120, 120, 120, 0.08);
  color: var(--font-color, #20303f);
  font-weight: 800;
  padding: 9px 12px;
  cursor: pointer;
}
.rhema-compare-tabs button.active {
  background: var(--secondary-color, #243447);
  color: #fff;
  border-color: var(--secondary-color, #243447);
}
.rhema-compare-list {
  padding: 12px 16px; overflow-y: auto; flex: 1; min-height: 0;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}
.rhema-compare-addver {
  width: 100%;
  display: flex; align-items: center; justify-content: center; gap: 6px;
  border: 1.5px dashed var(--border-color, rgba(120, 120, 120, 0.35));
  background: transparent;
  color: var(--muted-color, #6b7684);
  border-radius: 12px;
  padding: 12px;
  margin: 2px 0 4px;
  font-weight: 800; font-size: 0.88rem; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.rhema-compare-addver:active { transform: scale(0.985); }
.rhema-compare-addver .material-symbols-outlined { font-size: 19px; }
.rhema-compare-empty { color: var(--muted-color, #8a8a8a); font-size: 0.9rem; line-height: 1.5; padding: 18px 4px; text-align: center; }
.rhema-compare-item {
  border: 1px solid rgba(120, 120, 120, 0.2);
  border-radius: 12px;
  padding: 10px 12px;
  margin-bottom: 10px;
  background: rgba(120, 120, 120, 0.04);
}
.rhema-compare-item-hd { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 4px; }
.rhema-compare-ref { font-weight: 800; font-size: 0.9rem; color: var(--secondary-color, #243447); }
.rhema-compare-ctrls { display: inline-flex; gap: 2px; }
.rhema-compare-ctrls button {
  border: none; background: transparent; cursor: pointer;
  color: var(--muted-color, #8a8a8a); padding: 4px; border-radius: 6px;
  display: inline-flex; align-items: center;
}
.rhema-compare-ctrls button:disabled { opacity: 0.3; cursor: default; }
.rhema-compare-ctrls .material-symbols-outlined { font-size: 20px; }
.rhema-compare-text { font-size: 0.92rem; line-height: 1.5; }
/* Verse-number markers when a compare row shows several verses. */
.rhema-cmp-vnum {
  font-size: 0.66em; font-weight: 800;
  color: var(--secondary-color, #243447);
  opacity: 0.75;
  margin-right: 2px;
}

/* ── Book Introductions ─────────────────────────────────────────────────── */
/* The intro is an "extra chapter" before chapter 1 in the chapter grids. */
.rhema-intro-cell {
  display: inline-flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--secondary-color, #243447) 10%, transparent) !important;
  color: var(--secondary-color, #243447) !important;
}
.rhema-intro-cell .material-symbols-outlined { font-size: 20px; }
/* The inline chapter grid expanded under a book row in the Select Book list.
   Open/close motion is a JS height animation (see _biExpandEl/_biCollapseEl)
   so the rows below slide with it; the grid contents just fade in. */
.rhema-book-chapters {
  padding: 4px 2px 12px;
}
/* Scroll compensation is done manually when the expansion moves between books;
   native scroll anchoring would double-correct (Chrome anchors, Safari doesn't). */
#rhemaBookList { overflow-anchor: none; }
.rhema-book-chapters .rhema-book-chapter-grid {
  animation: biFade 0.3s ease;
  /* The grid's internal layout never changes while its wrapper's height
     animates — containment stops the browser re-laying-out 150 cells on
     every frame of the open/close motion. */
  contain: layout;
}
@keyframes biFade {
  from { opacity: 0; }
  to { opacity: 1; }
}
.rhema-book-row.open .rhema-book-icon { color: var(--secondary-color, #243447); }
/* The intro page rendered inside the reader as "chapter zero". */
.bi-page {
  max-width: 620px;
  margin: 0 auto;
  padding: 14px 4px 40px;
  text-align: left;
}
.bi-startreading {
  width: 100%;
  display: flex; align-items: center; justify-content: center; gap: 7px;
  margin-top: 20px;
  padding: 14px;
  border: none; border-radius: 14px;
  background: var(--secondary-color, #243447);
  color: #fff;
  font-weight: 800; font-size: 0.95rem; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.bi-startreading:active { transform: scale(0.99); }
.bi-startreading .material-symbols-outlined { font-size: 19px; }
.bi-kicker {
  font-size: 0.68rem; font-weight: 800;
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--muted-color, #8a8a8a);
  margin-bottom: 2px; padding-right: 44px;
}
.bi-title { margin: 0 0 12px; font-size: 1.5rem; font-weight: 900; }
.bi-facts {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
  margin-bottom: 8px;
}
.bi-facts > div {
  border: 1px solid var(--border-color, rgba(120, 120, 120, 0.2));
  border-radius: 12px; padding: 9px 11px;
  display: flex; flex-direction: column; gap: 2px;
}
.bi-facts small {
  font-size: 0.64rem; font-weight: 800; letter-spacing: 0.05em;
  text-transform: uppercase; color: var(--muted-color, #8a8a8a);
}
.bi-facts strong { font-size: 0.9rem; line-height: 1.25; }
.bi-factnote { margin: 0 2px 6px; font-size: 0.78rem; line-height: 1.45; color: var(--muted-color, #6b7684); }
.bi-section { margin-top: 14px; }
.bi-section h4 {
  margin: 0 0 6px; font-size: 0.72rem; font-weight: 800;
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--secondary-color, #243447);
}
.bi-section p { margin: 0; font-size: 0.9rem; line-height: 1.55; }
.bi-keyverse {
  width: 100%; text-align: left;
  display: flex; flex-direction: column; gap: 4px;
  margin-top: 10px; padding: 11px 12px;
  border: 1px solid color-mix(in srgb, var(--secondary-color, #243447) 22%, transparent);
  background: color-mix(in srgb, var(--secondary-color, #243447) 7%, transparent);
  border-radius: 12px; cursor: pointer;
  color: var(--font-color, #20303f);
  -webkit-tap-highlight-color: transparent;
}
.bi-keyverse:active { transform: scale(0.99); }
.bi-keyref {
  display: inline-flex; align-items: center; gap: 5px;
  font-weight: 800; font-size: 0.8rem;
  color: var(--secondary-color, #243447);
}
.bi-keyref .material-symbols-outlined { font-size: 16px; }
.bi-keytext { font-size: 0.86rem; line-height: 1.5; font-style: italic; }
.bi-outline-row {
  width: 100%;
  display: flex; align-items: center; gap: 10px;
  border: none; border-bottom: 1px solid var(--border-color, rgba(120, 120, 120, 0.14));
  background: transparent;
  padding: 10px 2px; cursor: pointer; text-align: left;
  color: var(--font-color, #20303f);
  -webkit-tap-highlight-color: transparent;
}
.bi-outline-row:last-child { border-bottom: none; }
.bi-outline-range {
  flex-shrink: 0; min-width: 52px;
  font-weight: 800; font-size: 0.78rem;
  color: var(--secondary-color, #243447);
}
.bi-outline-title { flex: 1; font-size: 0.88rem; line-height: 1.35; }
.bi-outline-row .material-symbols-outlined { font-size: 18px; color: var(--muted-color, #8a8a8a); }
.bi-debate {
  border: 1px solid var(--border-color, rgba(120, 120, 120, 0.2));
  border-radius: 12px; padding: 12px; margin-bottom: 8px;
}
.bi-debate-q { font-weight: 800; font-size: 0.9rem; margin-bottom: 3px; }
.bi-debate-s { font-size: 0.82rem; line-height: 1.45; color: var(--muted-color, #6b7684); }
.bi-debate-more {
  max-height: 0; overflow: hidden;
  transition: max-height 0.3s ease;
}
.bi-debate-more.open { max-height: 1400px; }
.bi-debate-more p {
  margin: 8px 0 0; font-size: 0.86rem; line-height: 1.55;
  border-top: 1px dashed var(--border-color, rgba(120, 120, 120, 0.25));
  padding-top: 8px;
}
.bi-debate-btn {
  display: inline-flex; align-items: center; gap: 3px;
  margin-top: 8px; padding: 5px 10px 5px 7px;
  border: none; border-radius: 999px;
  background: color-mix(in srgb, var(--secondary-color, #243447) 10%, transparent);
  color: var(--secondary-color, #243447);
  font-weight: 800; font-size: 0.76rem; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.bi-debate-btn .material-symbols-outlined { font-size: 17px; }
.rhema-compare-saved { padding: 0 16px; }
.rhema-compare-saved-row { display: flex; align-items: center; gap: 6px; margin: 6px 0; }
.rhema-compare-saved-open {
  flex: 1; display: flex; align-items: center; gap: 8px;
  border: 1px solid rgba(120, 120, 120, 0.2); background: transparent;
  border-radius: 10px; padding: 9px 11px; cursor: pointer;
  color: var(--font-color, #20303f); font-weight: 600; font-size: 0.9rem; text-align: left;
}
.rhema-compare-saved-open small { color: var(--muted-color, #8a8a8a); font-weight: 600; }
.rhema-compare-saved-del { border: none; background: transparent; cursor: pointer; color: var(--muted-color, #8a8a8a); padding: 6px; }
.rhema-compare-actions { display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid rgba(120, 120, 120, 0.18); }
.rhema-compare-clear { flex: 0 0 auto; padding: 11px 16px; border: none; border-radius: 10px; background: rgba(120, 120, 120, 0.14); color: var(--font-color, #20303f); font-weight: 700; cursor: pointer; }
.rhema-compare-save { flex: 1; padding: 11px 16px; border: none; border-radius: 10px; background: var(--secondary-color, #243447); color: #fff; font-weight: 700; cursor: pointer; }
.rhema-compare-save:disabled { opacity: 0.45; cursor: default; }

/* ── Phase 5 + Rhema compare/notes enhancements ───────────────────────────── */
/* Underline the verse being acted on, in the theme colour. */
.rhema-english-verse.rhema-verse-acting {
  text-decoration: underline;
  text-decoration-color: var(--secondary-color, #243447);
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
}
/* Version chip beside a compared verse's reference — tap to change translation. */
.rhema-compare-ver {
  display: inline-flex;
  align-items: center;
  gap: 1px;
  border: 1px solid var(--secondary-color, #243447);
  color: var(--secondary-color, #243447);
  background: transparent;
  border-radius: 999px;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 2px 6px 2px 8px;
  margin-left: 8px;
  cursor: pointer;
}
.rhema-compare-ver .material-symbols-outlined { font-size: 14px; margin-left: 1px; }
.rhema-compare-ver:active { transform: scale(0.95); }
.rhema-compare-item-hd { flex-wrap: wrap; }
.rhema-compare-item-hd .rhema-compare-ctrls { margin-left: auto; }
/* Static translation badge for the simple 3-version compare (NIV/NKJV/NASB). */
.rhema-compare-ver-static {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--secondary-color, #243447);
  color: var(--secondary-color, #243447);
  background: transparent;
  border-radius: 999px;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 2px 8px;
}
/* Reference beside the "Compare" title in the overlay header. */
.rhema-compare-ref-inline { font-weight: 800; color: var(--secondary-color, #243447); margin-left: 4px; }

/* Loading / fallback states for api.bible verses in compare. */
.rhema-compare-text.rhema-compare-loading { opacity: 0.55; font-style: italic; }
.rhema-compare-text.rhema-compare-fallback { color: var(--muted-color, #8a8a8a); }

/* Per-row translation picker (bottom sheet, built in JS). */
.rhema-cmp-ver-sheet {
  position: fixed; inset: 0;
  z-index: 1300;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(8, 18, 28, 0.44);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  opacity: 0; pointer-events: none;
  transition: opacity 0.22s ease;
}
.rhema-cmp-ver-sheet.open { opacity: 1; pointer-events: auto; }
.rhema-cmp-ver-card {
  width: 100%; max-width: 460px;
  /* Solid surface: skin card color layered over a solid base (see compare card). */
  background: linear-gradient(var(--card-color, #fff), var(--card-color, #fff)), var(--primary-color, #fff);
  border-radius: 18px 18px 0 0;
  padding: 14px 14px calc(env(safe-area-inset-bottom, 0px) + 16px);
  box-shadow: 0 -10px 34px rgba(0, 0, 0, 0.18);
  transform: translateY(100%);
  transition: transform 0.28s cubic-bezier(.2, .82, .18, 1);
  will-change: transform;
}
.rhema-cmp-ver-sheet.open .rhema-cmp-ver-card { transform: translateY(0); }
.rhema-cmp-ver-title {
  font-weight: 800; font-size: 0.78rem; letter-spacing: 0.04em; text-transform: uppercase;
  color: var(--muted-color, #8a8a8a); margin: 2px 4px 10px;
}
.rhema-cmp-ver-opt {
  width: 100%;
  display: flex; align-items: center; justify-content: space-between;
  border: 1px solid var(--border-color, rgba(120, 120, 120, 0.2));
  background: transparent;
  color: var(--font-color, #20303f);
  border-radius: 12px;
  padding: 13px 14px; margin-bottom: 8px;
  font-weight: 800; font-size: 0.96rem; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.rhema-cmp-ver-opt:active { transform: scale(0.985); }
.rhema-cmp-ver-opt.active {
  border-color: var(--secondary-color, #243447);
  background: color-mix(in srgb, var(--secondary-color, #243447) 12%, transparent);
}
.rhema-cmp-ver-opt[disabled] { opacity: 0.45; cursor: default; }
.rhema-cmp-ver-opt small { color: var(--muted-color, #8a8a8a); font-weight: 700; font-size: 0.68rem; }
.rhema-cmp-ver-opt .material-symbols-outlined { font-size: 20px; color: var(--secondary-color, #243447); }
/* Version picker: abbreviation + tags on top, full name underneath. */
.rhema-cmp-ver-opt span:first-child { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; }
.rhema-ver-note { color: var(--muted-color, #8a8a8a); font-weight: 600; font-size: 0.68rem; }
.rhema-ver-abbr { display: inline-flex; align-items: center; gap: 6px; }
.rhema-ver-tag {
  font-style: normal; font-weight: 800; font-size: 0.58rem;
  letter-spacing: 0.05em; text-transform: uppercase;
  padding: 2px 7px; border-radius: 999px;
  background: color-mix(in srgb, var(--muted-color, #8a8a8a) 16%, transparent);
  color: var(--muted-color, #6b7684);
}
.rhema-ver-tag-study {
  background: color-mix(in srgb, #b98a2e 20%, transparent);
  color: #9a7222;
}
.rhema-ver-tabs {
  display: flex; gap: 6px; margin: 0 2px 10px;
}
.rhema-ver-tab {
  flex: 1;
  border: 1px solid var(--border-color, rgba(120, 120, 120, 0.2));
  background: transparent;
  color: var(--muted-color, #6b7684);
  border-radius: 999px;
  padding: 8px 10px;
  font-weight: 800; font-size: 0.78rem; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.rhema-ver-tab.active {
  border-color: var(--secondary-color, #243447);
  background: color-mix(in srgb, var(--secondary-color, #243447) 12%, transparent);
  color: var(--font-color, #20303f);
}
.rhema-ver-card-scroll {
  max-height: 76vh; overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}
/* Right side of a version option: current-version check + download control. */
.rhema-ver-optright { display: inline-flex; align-items: center; gap: 8px; flex-shrink: 0; }
.rhema-ver-dl {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 38px; height: 34px;
  border-radius: 999px;
  padding: 0 6px;
  color: var(--muted-color, #6b7684);
  background: color-mix(in srgb, var(--muted-color, #8a8a8a) 10%, transparent);
  font-weight: 800; font-size: 0.7rem;
  text-align: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
/* Center the icon/percent reliably. When this control is the ONLY item in the
   row's right column (an unselected version, i.e. no sibling check mark), it
   becomes a lone flex child and justify-content:center packs it to the left
   instead of centering — leaving the download icon visibly off-centre while
   the selected row (which has a check beside it) looked fine. Auto inline
   margins split the min-width slack evenly in every case; text-align covers
   the percent-label state. */
.rhema-ver-dl > * { margin-inline: auto; }
.rhema-ver-dl:active { transform: scale(0.92); }
.rhema-ver-dl .material-symbols-outlined { font-size: 20px; }
.rhema-ver-dl.active {
  color: var(--secondary-color, #243447);
  background: color-mix(in srgb, var(--secondary-color, #243447) 14%, transparent);
}
.rhema-ver-dl.done {
  color: #2e7d32;
  background: color-mix(in srgb, #2e7d32 14%, transparent);
  cursor: default;
}
/* Reader banner while an API version's chapter block downloads (or quota is out). */
.rhema-reader-downloading {
  margin: 0 0 12px;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px dashed var(--border-color, rgba(120, 120, 120, 0.3));
  background: color-mix(in srgb, var(--secondary-color, #243447) 7%, transparent);
  color: var(--muted-color, #6b7684);
  font-size: 0.78rem; font-weight: 700; line-height: 1.4;
}
@media (prefers-reduced-motion: reduce) {
  .rhema-cmp-ver-sheet, .rhema-cmp-ver-card,
  .rhema-compare-overlay, .rhema-compare-card { transition: none !important; }
}
/* Three-button compare action row. */
.rhema-compare-actions { flex-wrap: wrap; }
.rhema-compare-add {
  flex: 1 1 100%;
  order: -1;
  padding: 11px 16px;
  border: 1px dashed var(--secondary-color, #243447);
  border-radius: 10px;
  background: transparent;
  color: var(--secondary-color, #243447);
  font-weight: 700;
  cursor: pointer;
}
/* English word picker chips (study word log). */
.rhema-word-chips { display: flex; flex-wrap: wrap; gap: 7px; margin: 8px 0 4px; max-height: 220px; overflow-y: auto; }
.rhema-word-chip {
  border: 1px solid rgba(120, 120, 120, 0.28);
  background: rgba(120, 120, 120, 0.06);
  border-radius: 999px;
  padding: 7px 12px;
  font-size: 0.9rem;
  color: var(--font-color, #20303f);
  cursor: pointer;
}
.rhema-word-chip:active { background: var(--secondary-color, #243447); color: #fff; }
/* Word picker grouped by verse (multi-select): one labelled section per verse. */
.rhema-wordpick-group { width: 100%; margin-bottom: 6px; }
.rhema-wordpick-grouphd {
  font-size: 0.72rem; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase;
  color: var(--secondary-color, #243447); margin: 8px 2px 2px;
}
.rhema-wordpick-group .rhema-word-chips { max-height: none; overflow: visible; margin: 4px 0; }
#rhemaWordPickChips:has(.rhema-wordpick-group) { max-height: 52vh; }
.rhema-meaning-card { max-height: 82%; overflow-y: auto; }
.rhema-meaning-body { display: grid; gap: 12px; margin-top: 8px; }
.rhema-meaning-section {
  border: 1px solid rgba(120, 120, 120, 0.18);
  border-radius: 14px;
  padding: 12px;
  background: rgba(120, 120, 120, 0.05);
}
.rhema-meaning-section h4 {
  margin: 0 0 6px;
  font-size: 0.9rem;
  color: var(--secondary-color, #243447);
}
.rhema-meaning-section p { margin: 0; line-height: 1.5; }
.rhema-meaning-section ul { margin: 6px 0 0 18px; padding: 0; line-height: 1.45; }
/* ── Bible Dictionary card (names, places, customs) ── */
.rhema-word-chip-dict {
  border-color: color-mix(in srgb, var(--secondary-color, #243447) 45%, transparent);
  background: color-mix(in srgb, var(--secondary-color, #243447) 10%, transparent);
  font-weight: 700;
}
.rhema-dict-section {
  border-color: color-mix(in srgb, var(--secondary-color, #243447) 30%, transparent);
  background: color-mix(in srgb, var(--secondary-color, #243447) 7%, transparent);
}
.rhema-dict-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}
.rhema-dict-title { font-size: 1.05rem; }
.rhema-dict-kind {
  border-radius: 999px;
  padding: 2px 9px;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  background: color-mix(in srgb, var(--secondary-color, #243447) 16%, transparent);
  color: var(--secondary-color, #243447);
}
.rhema-dict-era {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted-color, #8a8a8a);
  margin-bottom: 6px;
}
.rhema-dict-era .material-symbols-outlined { font-size: 0.95rem; }
.rhema-dict-summary { font-weight: 700; margin-bottom: 6px !important; }
.rhema-dict-refs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.rhema-dict-refs-label {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted-color, #8a8a8a);
}
.rhema-dict-ref {
  border: 1px solid color-mix(in srgb, var(--secondary-color, #243447) 35%, transparent);
  background: color-mix(in srgb, var(--secondary-color, #243447) 10%, transparent);
  color: var(--secondary-color, #243447);
  border-radius: 999px;
  padding: 5px 11px;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform 0.12s;
}
.rhema-dict-ref:active { transform: scale(0.95); }

.rhema-def-list {
  margin: 0;
  padding-left: 20px;
  display: grid;
  gap: 10px;
}
.rhema-def-list li { line-height: 1.45; }
.rhema-def-list strong {
  display: inline-flex;
  margin-right: 6px;
  color: var(--secondary-color, #243447);
  text-transform: capitalize;
}
.rhema-def-list span { display: inline; }
.rhema-def-list em {
  display: block;
  margin-top: 3px;
  color: var(--muted-color, #8a8a8a);
  font-size: 0.86rem;
}
.rhema-marks-card {
  max-height: 82%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.rhema-marks-list {
  display: grid;
  gap: 10px;
  overflow-y: auto;
  margin-top: 12px;
  padding: 2px 2px 4px;
}
.rhema-mark-row {
  width: 100%;
  border: 1px solid rgba(120, 120, 120, 0.18);
  border-radius: 14px;
  background: color-mix(in srgb, var(--mark-color, var(--secondary-color)) 7%, var(--card-color));
  color: var(--font-color, #20303f);
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr) 24px;
  align-items: center;
  gap: 10px;
  padding: 12px;
  text-align: left;
  cursor: pointer;
}
.rhema-mark-dot {
  width: 10px;
  height: 42px;
  border-radius: 999px;
  background: var(--mark-color, var(--secondary-color));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--mark-color, var(--secondary-color)) 16%, transparent);
}
.rhema-mark-copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}
.rhema-mark-copy strong {
  color: var(--secondary-color, #243447);
  font-size: 0.92rem;
}
.rhema-mark-copy span {
  color: var(--font-color, #20303f);
  font-size: 0.9rem;
  line-height: 1.45;
}
.rhema-mark-note {
  margin: 2px 0 0;
  color: var(--muted-color, #8a8a8a);
  font-size: 0.86rem;
  line-height: 1.45;
}
.rhema-full-chapter-back {
  width: calc(100% - 24px);
  margin: 12px;
  padding: 13px 16px;
  border: none;
  border-radius: 14px;
  background: var(--secondary-color, #243447);
  color: #fff;
  font-weight: 800;
  box-shadow: 0 10px 22px rgba(8, 18, 28, 0.18);
  cursor: pointer;
}

/* ============================================================
   Lively tap feedback — buttons gently press in when tapped so
   every press feels responsive and alive. Press-in matches the
   app's existing :active convention and never overflows its box.
   ============================================================ */
.main-btn,
.secondary,
.prof-menu-row,
.profile-action-card,
.journey-stat,
.rank-info-btn,
.collapse-btn,
.mercies-primary,
.mercies-secondary,
.theme-preset {
  transition:
    transform 0.13s cubic-bezier(0.34, 1.56, 0.64, 1),
    background 0.18s ease,
    box-shadow 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease;
}
.main-btn:active,
.secondary:active,
.prof-menu-row:active,
.profile-action-card:active,
.journey-stat:active,
.rank-info-btn:active,
.collapse-btn:active,
.mercies-primary:active,
.mercies-secondary:active {
  transform: scale(0.96);
}
/* Theme tiles already nudge on press — keep their swatch lively too */
.theme-preset:active {
  transform: scale(0.97);
}
@media (prefers-reduced-motion: reduce) {
  .main-btn,
  .secondary,
  .prof-menu-row,
  .profile-action-card,
  .journey-stat,
  .rank-info-btn,
  .collapse-btn,
  .mercies-primary,
  .mercies-secondary,
  .theme-preset {
    transition: background 0.18s ease, color 0.18s ease;
  }
  .main-btn:active,
  .secondary:active,
  .prof-menu-row:active,
  .profile-action-card:active,
  .journey-stat:active,
  .rank-info-btn:active,
  .collapse-btn:active,
  .mercies-primary:active,
  .mercies-secondary:active,
  .theme-preset:active {
    transform: none;
  }
}

/* ============================================================
   Kill any viewport-edge scrollbar strip. This app is a fixed
   shell (each screen scrolls inside its own container), so the
   html/body/.app should never show a scrollbar. A reserved or
   overlay scrollbar here renders as a faint lighter strip down
   the right edge of screens like Profile and Settings.
   ============================================================ */
html,
body,
.app,
#profilePage.screen.active,
#communityPage.screen.active,
#merciesPage.screen.active,
#settingsScreen.screen.active {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}
html::-webkit-scrollbar,
body::-webkit-scrollbar,
.app::-webkit-scrollbar,
#profilePage.screen.active::-webkit-scrollbar,
#communityPage.screen.active::-webkit-scrollbar,
#merciesPage.screen.active::-webkit-scrollbar,
#settingsScreen.screen.active::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
}

/* Praises collapsed nav dock: show ONLY the home button — no peeking profile or
   other icons behind it. (Overrides both the base and the max-width:760px peek
   rules, including their !important opacity.) */
.bottom-nav.mercies-collapsed .bn-item:not([data-page="home"]) {
  opacity: 0 !important;
  pointer-events: none !important;
  transform: scale(0.5) !important;
}

/* Quality motion pass: smooth screen swaps without the hard clipped handoff. */
body.screen-transitioning .app {
  position: relative;
  overflow: hidden !important;
  contain: paint;
}

body.screen-transitioning .screen.screen-entering,
body.screen-transitioning .screen.screen-leaving {
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  overflow: hidden !important;
  will-change: transform, opacity;
  backface-visibility: hidden;
}

body.screen-transitioning .screen.screen-entering { z-index: 22; }
body.screen-transitioning .screen.screen-leaving { z-index: 20; pointer-events: none; }

.screen-profile-in-enter { animation: screenProfileIn .4s cubic-bezier(.2,.82,.18,1) both; }
.screen-profile-in-leave { animation: screenHomeNudgeRight .4s cubic-bezier(.2,.82,.18,1) both; }
.screen-profile-out-enter { animation: screenHomeReturnRight .4s cubic-bezier(.2,.82,.18,1) both; }
.screen-profile-out-leave { animation: screenProfileOut .4s cubic-bezier(.2,.82,.18,1) both; }
.screen-slide-forward-enter { animation: screenSlideFromRight .38s cubic-bezier(.2,.82,.18,1) both; }
.screen-slide-forward-leave { animation: screenSlideUnderLeft .38s cubic-bezier(.2,.82,.18,1) both; }
.screen-slide-back-enter { animation: screenSlideFromLeftSoft .38s cubic-bezier(.2,.82,.18,1) both; }
.screen-slide-back-leave { animation: screenSlideToRight .38s cubic-bezier(.2,.82,.18,1) both; }
.screen-tool-open-enter { animation: screenToolOpen .42s cubic-bezier(.16,1,.3,1) both; transform-origin: 50% 82%; }
.screen-tool-open-leave { animation: screenToolDim .42s cubic-bezier(.16,1,.3,1) both; transform-origin: 50% 80%; }
.screen-tool-close-enter { animation: screenToolHomeReturn .38s cubic-bezier(.16,1,.3,1) both; transform-origin: 50% 80%; }
.screen-tool-close-leave { animation: screenToolClose .38s cubic-bezier(.16,1,.3,1) both; transform-origin: 50% 82%; }

@keyframes screenProfileIn {
  from { transform: translateX(-100%); opacity: .96; }
  to { transform: translateX(0); opacity: 1; }
}
@keyframes screenProfileOut {
  from { transform: translateX(0); opacity: 1; }
  to { transform: translateX(-100%); opacity: .96; }
}
@keyframes screenHomeNudgeRight {
  from { transform: translateX(0) scale(1); opacity: 1; }
  to { transform: translateX(18%) scale(.985); opacity: .72; }
}
@keyframes screenHomeReturnRight {
  from { transform: translateX(18%) scale(.985); opacity: .72; }
  to { transform: translateX(0) scale(1); opacity: 1; }
}
@keyframes screenSlideFromRight {
  from { transform: translateX(100%); opacity: .98; }
  to { transform: translateX(0); opacity: 1; }
}
@keyframes screenSlideUnderLeft {
  from { transform: translateX(0) scale(1); opacity: 1; }
  to { transform: translateX(-14%) scale(.99); opacity: .68; }
}
@keyframes screenSlideFromLeftSoft {
  from { transform: translateX(-14%) scale(.99); opacity: .68; }
  to { transform: translateX(0) scale(1); opacity: 1; }
}
@keyframes screenSlideToRight {
  from { transform: translateX(0); opacity: 1; }
  to { transform: translateX(100%); opacity: .96; }
}
@keyframes screenToolOpen {
  0% { transform: translateY(28px) scale(.955); opacity: 0; border-radius: 34px; }
  62% { transform: translateY(-4px) scale(1.006); opacity: 1; border-radius: 20px; }
  100% { transform: translateY(0) scale(1); opacity: 1; border-radius: 0; }
}
@keyframes screenToolDim {
  from { transform: translateY(0) scale(1); opacity: 1; }
  to { transform: translateY(-12px) scale(.985); opacity: .52; }
}
@keyframes screenToolHomeReturn {
  from { transform: translateY(-10px) scale(.985); opacity: .6; }
  to { transform: translateY(0) scale(1); opacity: 1; }
}
@keyframes screenToolClose {
  from { transform: translateY(0) scale(1); opacity: 1; }
  to { transform: translateY(32px) scale(.955); opacity: 0; }
}

#homeScreen .home-action-tile.launching,
#homeScreen .home-habit-widget.launching {
  animation: homeToolLaunch .44s cubic-bezier(.16,1,.3,1) both;
}

@keyframes homeToolLaunch {
  0% { transform: scale(1); filter: brightness(1); }
  42% { transform: translateY(-4px) scale(1.018); filter: brightness(1.03); }
  100% { transform: translateY(0) scale(1); filter: brightness(1); }
}

#rhemaModal.rhema-nav-enter #rhemaSlide {
  animation: rhemaSwipeOpen .5s cubic-bezier(.2,.82,.18,1) both;
  box-shadow: -16px 0 40px color-mix(in srgb, var(--secondary-color) 22%, transparent);
}

@keyframes rhemaSwipeOpen {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  body.screen-transitioning .screen.screen-entering,
  body.screen-transitioning .screen.screen-leaving,
  #homeScreen .home-action-tile.launching,
  #homeScreen .home-habit-widget.launching,
  #rhemaModal.rhema-nav-enter #rhemaSlide {
    animation: none !important;
  }
}

/* Habits uses the Praises-style floating Home button only. */
.bottom-nav.habits-collapsed {
  left: auto !important;
  right: calc(16px + env(safe-area-inset-right, 0px)) !important;
  bottom: calc(18px + env(safe-area-inset-bottom, 0px)) !important;
  width: 68px !important;
  height: 68px !important;
  transform: none !important;
}
.bottom-nav.habits-collapsed .bn-item:not([data-page="home"]) {
  opacity: 0 !important;
  pointer-events: none !important;
  transform: scale(0.5) !important;
}
.bottom-nav.habits-collapsed .bn-item[data-page="home"] {
  inset: 0 !important;
  height: 68px !important;
}

/* Theme-aware press feedback. */
:root {
  --theme-press-highlight: color-mix(in srgb, var(--secondary-color) 22%, transparent);
}

.icon-btn:active,
.prof-nav-icon:active,
.ht-btn:active,
.home-action-tile:active,
.home-habit-widget:active,
.prof-menu-row:active,
.profile-action-card:active,
.fr-card:active,
.friends-tab-btn:active,
.sett-row:active,
.praises-tab:active,
.comm-friends-btn:active,
.notif-tab:active,
.notif-close-btn:active {
  background-color: var(--theme-press-highlight) !important;
  border-color: color-mix(in srgb, var(--secondary-color) 42%, var(--border-color)) !important;
}

* {
  -webkit-tap-highlight-color: color-mix(in srgb, var(--secondary-color) 18%, transparent);
}

/* Optional Home Tools theme matching. */
body.tools-theme-match #homeScreen .home-action-tile {
  --qa-card-bg:
    radial-gradient(circle at 78% 10%, color-mix(in srgb, var(--secondary-color) 30%, transparent), transparent 40%),
    linear-gradient(180deg,
      color-mix(in srgb, var(--secondary-color) 26%, var(--card-color)),
      color-mix(in srgb, var(--secondary-color) 12%, var(--primary-light))) !important;
  --qa-card-border: color-mix(in srgb, var(--secondary-color) 52%, rgba(255, 255, 255, 0.68)) !important;
  --qa-card-shadow: color-mix(in srgb, var(--secondary-color) 26%, transparent) !important;
  --qa-image-shadow: color-mix(in srgb, var(--secondary-color) 28%, transparent) !important;
  --qa-title: var(--secondary-color) !important;
  --qa-subtitle: color-mix(in srgb, var(--secondary-color) 88%, var(--font-color)) !important;
  background: var(--qa-card-bg) !important;
  border-color: var(--qa-card-border) !important;
  box-shadow:
    0 16px 34px var(--qa-card-shadow),
    inset 0 1px 0 rgba(255, 255, 255, 0.74) !important;
}

body.tools-theme-match #homeScreen .home-action-tile .hat-icon {
  background:
    radial-gradient(110% 90% at 50% 8%, rgba(255,255,255,0.84), transparent 62%),
    linear-gradient(145deg,
      color-mix(in srgb, var(--secondary-color) 18%, #fff),
      color-mix(in srgb, var(--secondary-color) 28%, var(--card-color))) !important;
  border-color: color-mix(in srgb, var(--secondary-color) 42%, rgba(255,255,255,0.62)) !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.92),
    inset 0 -18px 28px color-mix(in srgb, var(--secondary-color) 16%, transparent),
    0 12px 20px color-mix(in srgb, var(--secondary-color) 16%, transparent) !important;
}

body.tools-theme-match #homeScreen .home-action-tile .hat-text strong,
body.tools-theme-match #homeScreen .home-action-tile .hat-chev {
  color: var(--secondary-color) !important;
}

body.tools-theme-match #homeScreen .home-action-tile .hat-text small {
  color: color-mix(in srgb, var(--secondary-color) 88%, var(--font-color)) !important;
}

/* Friends sheet: full mobile-width bottom sheet with a softer entrance. */
.friends-modal-overlay {
  align-items: flex-end !important;
  justify-content: stretch !important;
  padding: 0 !important;
}
.friends-modal-overlay.open .friends-modal {
  animation: friendsSheetOpen .3s cubic-bezier(.16,1,.3,1) both;
}
.friends-modal {
  width: 100vw !important;
  max-width: none !important;
  max-height: min(88svh, calc(100svh - env(safe-area-inset-top, 0px) - 18px)) !important;
  border-radius: 26px 26px 0 0 !important;
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
.fr-list {
  padding-bottom: calc(42px + env(safe-area-inset-bottom, 0px)) !important;
}

@keyframes friendsSheetOpen {
  from { transform: translateY(36px); opacity: .72; }
  to { transform: translateY(0); opacity: 1; }
}

#updateModal.open .modal-card,
#coachReplayModal.open .modal-card,
#rhemaNerdModal.open .modal-card {
  animation: profileSheetOpen .3s cubic-bezier(.16,1,.3,1) both;
}

@keyframes profileSheetOpen {
  from { transform: translateY(18px) scale(.965); opacity: 0; }
  to { transform: translateY(0) scale(1); opacity: 1; }
}

/* Reuse the exact Journey animation classes across the rest of the app shell. */
.screen.active.screen-expanding,
.study-library.open.screen-expanding {
  animation: journeyScreenExpand 0.46s cubic-bezier(.4, 0, .2, 1);
}

.screen.active.screen-slide-in-right {
  animation: journeyScreenInRight 0.34s cubic-bezier(.4, 0, .2, 1);
}

.screen.active.screen-slide-out-right {
  animation: journeyScreenOutRight 0.30s cubic-bezier(.4, 0, .2, 1) forwards;
}

.study-library.open.screen-slide-out-right {
  animation: journeyScreenOutRight 0.30s cubic-bezier(.4, 0, .2, 1) forwards;
}

.modal-overlay.open.screen-slide-in-right .modal-card,
#updateModal.open.screen-slide-in-right .modal-card,
#coachReplayModal.open.screen-slide-in-right .modal-card,
#rhemaNerdModal.open.screen-slide-in-right .modal-card {
  animation: atlasDetailIn 0.32s cubic-bezier(.4, 0, .2, 1);
}

#rhemaModal.screen-slide-in-right #rhemaSlide {
  animation: journeyScreenInRight 0.34s cubic-bezier(.4, 0, .2, 1);
}

/* Closing Rhema slides the reader back off to the right. */
@keyframes rhemaSwipeClose { from { transform: translateX(0); } to { transform: translateX(100%); } }
#rhemaModal.rhema-nav-leave #rhemaSlide {
  animation: rhemaSwipeClose 0.32s cubic-bezier(.4, 0, .2, 1) forwards;
}
@media (prefers-reduced-motion: reduce) {
  #rhemaModal.rhema-nav-leave #rhemaSlide { animation: none; }
  .screen.active.screen-expanding,
  .study-library.open.screen-expanding,
  .screen.active.screen-slide-in-right,
  .screen.active.screen-slide-out-right,
  .study-library.open.screen-slide-out-right,
  .modal-overlay.open.screen-slide-in-right .modal-card,
  #rhemaModal.screen-slide-in-right #rhemaSlide,
  #rhemaModal.rhema-nav-enter #rhemaSlide {
    animation: none !important;
  }
}

/* App-shell motion: Journey-style feel without depending on Journey screens. */
@keyframes appShellExpand {
  from {
    clip-path: inset(var(--exp-t, 35%) var(--exp-r, 8%) var(--exp-b, 40%) var(--exp-l, 8%) round 22px);
    opacity: .52;
  }
  to {
    clip-path: inset(0 0 0 0 round 0);
    opacity: 1;
  }
}

@keyframes appShellInRight {
  from { transform: translate3d(100%, 0, 0); opacity: 1; }
  to { transform: translate3d(0, 0, 0); opacity: 1; }
}

@keyframes appShellInLeft {
  from { transform: translate3d(-100%, 0, 0); opacity: 1; }
  to { transform: translate3d(0, 0, 0); opacity: 1; }
}

@keyframes appShellOutRight {
  from { transform: translate3d(0, 0, 0); opacity: 1; }
  to { transform: translate3d(100%, 0, 0); opacity: .98; }
}

@keyframes appShellOutLeft {
  from { transform: translate3d(0, 0, 0); opacity: 1; }
  to { transform: translate3d(-100%, 0, 0); opacity: .98; }
}

/* Themed backdrop during motion (no blank veil — the real screen shows through). */
body.app-screen-motion,
body.app-launch-motion {
  overflow: hidden !important;
  background: var(--primary-light, #f6fbff);
}
/* Keep the floating bottom nav from sliding/lagging mid-transition: it's revealed
   cleanly underneath the panels (which now ride above it) instead of animating. */
body.app-screen-motion .bottom-nav,
body.app-launch-motion .bottom-nav {
  transition: none !important;
}

.screen.app-screen-underlay,
.screen.active.app-screen-animating {
  display: block !important;
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  height: 100dvh !important;
  max-height: 100dvh !important;
  overflow: hidden !important;
  background: var(--primary-light, #f6fbff) !important;
  backface-visibility: hidden;
  transform: translateZ(0);
  contain: paint;
}

.screen.app-screen-underlay {
  /* The real previous screen, shown underneath the one sliding in (clean push). */
  z-index: 1000;
  opacity: 1 !important;
  pointer-events: none;
}

/* Transitioning panels ride ABOVE the bottom nav (z 900) so it never appears on
   top of a sliding screen — it's just revealed underneath as the panel moves. */
.screen.active.app-screen-animating {
  z-index: 1002;
  will-change: transform;
}

/* Themed depth on the leading edge as a screen slides over the one beneath. */
.screen.active.app-slide-in-right {
  animation: appShellInRight .42s cubic-bezier(.2,.82,.18,1) both;
  box-shadow: -14px 0 36px color-mix(in srgb, var(--secondary-color) 28%, transparent);
}

.screen.active.app-slide-in-left {
  animation: appShellInLeft .42s cubic-bezier(.2,.82,.18,1) both;
  box-shadow: 14px 0 36px color-mix(in srgb, var(--secondary-color) 28%, transparent);
}

/* Back: the leaving screen slides off, revealing the destination (home) underneath
   — the same reveal as Journey Maps' back gesture. Direction mirrors how the
   screen entered (right-entering screens exit right; Profile exits left). */
.screen.active.app-slide-out-right {
  animation: appShellOutRight .38s cubic-bezier(.4, 0, .2, 1) forwards;
  box-shadow: -14px 0 36px color-mix(in srgb, var(--secondary-color) 28%, transparent);
}
.screen.active.app-slide-out-left {
  animation: appShellOutLeft .38s cubic-bezier(.4, 0, .2, 1) forwards;
  box-shadow: 14px 0 36px color-mix(in srgb, var(--secondary-color) 28%, transparent);
}

.screen.active.app-screen-expanding,
.study-library.open.app-screen-expanding {
  animation: appShellExpand .46s cubic-bezier(.4, 0, .2, 1) both;
  background: var(--primary-light, #f6fbff) !important;
  backface-visibility: hidden;
  transform: translateZ(0);
  contain: paint;
  /* Thin themed ring only — the big blurred inner glow repainted every frame as
     the clip animated, which made heavier tool screens lag. Ring keeps the theme
     accent without the per-frame blur cost. */
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--secondary-color) 50%, transparent);
}

.screen.active.app-screen-expanding {
  display: block !important;
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  height: 100dvh !important;
  max-height: 100dvh !important;
  overflow: hidden !important;
  z-index: 1002;
}

/* Reverse of the expand: fold the screen back into the button it grew from, fading
   fully out by the end so there's no lingering "last frame" rectangle. */
@keyframes appShellCollapse {
  from { clip-path: inset(0 0 0 0 round 0); opacity: 1; }
  to   { clip-path: inset(var(--exp-t, 35%) var(--exp-r, 8%) var(--exp-b, 40%) var(--exp-l, 8%) round 22px); opacity: 0; }
}
.screen.active.app-screen-collapsing {
  display: block !important;
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  height: 100dvh !important;
  max-height: 100dvh !important;
  overflow: hidden !important;
  z-index: 1002;
  background: var(--primary-light, #f6fbff) !important;
  animation: appShellCollapse .42s cubic-bezier(.4, 0, .2, 1) forwards;
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--secondary-color) 50%, transparent);
}

/* Reverse of the Rhema slide-in: fold the reader back into the bottom-nav Rhema
   button it was launched from (same fold the Home tools close with). The clip
   animates on the modal shell; the slide inside stays put so text doesn't shift. */
#rhemaModal.rhema-collapse-leave {
  animation: appShellCollapse .42s cubic-bezier(.4, 0, .2, 1) forwards;
  background: var(--primary-light, #f6fbff);
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--secondary-color) 50%, transparent);
}
#rhemaModal.rhema-collapse-leave #rhemaSlide {
  transform: translateY(0);
  transition: none;
}

.study-library.open.app-screen-expanding {
  z-index: 941;
  /* Stay fully opaque while it clips open — the base modal's opacity fade made it
     briefly see-through, so the Home tools showed through during the expand. */
  opacity: 1 !important;
  transform: none !important;
  transition: none !important;
}

.study-library.open.app-slide-out-right {
  animation: appShellOutRight .30s cubic-bezier(.4, 0, .2, 1) forwards;
  transition: none !important;
}

/* Reverse of the expand: fold the Study Library back into its launch button. Stay
   fully opaque (no base-modal fade) so nothing shows through while it clips shut. */
.study-library.open.app-screen-collapsing {
  z-index: 941;
  opacity: 1 !important;
  transform: none !important;
  transition: none !important;
  animation: appShellCollapse .42s cubic-bezier(.4, 0, .2, 1) forwards;
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--secondary-color) 50%, transparent);
}

.modal-overlay.open.app-modal-slide-in-right .modal-card,
#updateModal.open.app-modal-slide-in-right .modal-card,
#coachReplayModal.open.app-modal-slide-in-right .modal-card,
#rhemaNerdModal.open.app-modal-slide-in-right .modal-card {
  animation: atlasDetailIn .32s cubic-bezier(.4, 0, .2, 1);
}

@media (prefers-reduced-motion: reduce) {
  #rhemaModal.rhema-collapse-leave,
  .screen.active.app-screen-expanding,
  .screen.active.app-screen-collapsing,
  .study-library.open.app-screen-expanding,
  .study-library.open.app-screen-collapsing,
  .screen.active.app-slide-in-right,
  .screen.active.app-slide-in-left,
  .screen.active.app-slide-out-right,
  .screen.active.app-slide-out-left,
  .study-library.open.app-slide-out-right,
  .modal-overlay.open.app-modal-slide-in-right .modal-card {
    animation: none !important;
  }
}

/* ══════════════════════════════════════════════════════════════════════════════
   APP STYLES (SKINS)
   A skin restyles the whole app on top of any color theme. Activated by
   data-skin on <html> (applyAppSkin in app.js); no attribute = Classic, and
   none of these rules apply.

   Architecture: one set of SHARED structural rules (page, sheets, cards, type,
   icons) reads per-skin CSS variables (--skin-*). Each skin is then just a
   token block — light values on :root[data-skin="X"], dark values on
   :root[data-skin="X"]:has(body.dark). Theme-token overrides carry !important
   because applyAppTheme() writes theme variables as inline styles on <html>;
   the structural rules carry !important because the base stylesheet paints
   body/screens with importance (e.g. ~8603, ~8920, ~25972, ~26017, ~28181).
   ══════════════════════════════════════════════════════════════════════════════ */

/* ── Skin picker (Settings → App Style) ──────────────────────────────────────── */
.skin-preset-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(108px, 1fr));
  gap: 10px;
  padding: 12px;
}
.skin-preset {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 12px 10px;
  border: 2px solid var(--border-color, #93c5fd);
  border-radius: 14px;
  background: var(--card-color, #fff);
  color: var(--font-color, #172033);
  cursor: pointer;
  font-family: inherit;
}
.skin-preset strong { font-size: 0.92rem; }
.skin-preset small { color: var(--muted-color, #475569); font-weight: 600; }
.skin-preset .skin-preview {
  width: 100%;
  height: 54px;
  border-radius: 9px;
  border: 1px solid rgba(120, 120, 120, 0.25);
  margin-bottom: 4px;
}
.skin-preset.skin-classic .skin-preview {
  background: linear-gradient(135deg, #dbeafe, #1d4ed8 55%, #f59e0b);
}
.skin-preset.skin-notebook .skin-preview {
  background-image:
    linear-gradient(90deg, transparent 0 12px, rgba(198, 90, 90, 0.55) 12px 13.5px, transparent 13.5px),
    repeating-linear-gradient(180deg, transparent 0 12px, rgba(47, 74, 124, 0.28) 12px 13px);
  background-color: #f8f2e1;
}
.skin-preset.skin-blueprint .skin-preview {
  background-image:
    repeating-linear-gradient(90deg, transparent 0 10px, rgba(255, 255, 255, 0.35) 10px 11px),
    repeating-linear-gradient(180deg, transparent 0 10px, rgba(255, 255, 255, 0.35) 10px 11px);
  background-color: #14508c;
}
.skin-preset.skin-scroll .skin-preview {
  background-image:
    radial-gradient(80% 90% at 18% 12%, rgba(120, 90, 40, 0.22), transparent 60%),
    radial-gradient(90% 80% at 85% 88%, rgba(120, 90, 40, 0.26), transparent 55%);
  background-color: #ead9b0;
}
.skin-preset.skin-chalkboard .skin-preview {
  background-image:
    radial-gradient(60% 90% at 25% 20%, rgba(255, 255, 255, 0.10), transparent 60%),
    linear-gradient(90deg, transparent 0 65%, rgba(255, 255, 255, 0.5) 65% 66.5%, transparent 66.5%);
  background-color: #33544a;
}
.skin-preset.skin-terminal .skin-preview {
  background-image:
    repeating-linear-gradient(180deg, rgba(0, 0, 0, 0.35) 0 1px, transparent 1px 3px),
    linear-gradient(90deg, rgba(34, 197, 94, 0.85) 0 26%, transparent 26%);
  background-color: #10151a;
}
.skin-preset .skin-check {
  position: absolute;
  top: 6px;
  right: 6px;
  display: none;
  color: var(--secondary-color, #1d4ed8);
  font-size: 20px;
}
.skin-preset.selected {
  border-color: var(--secondary-color, #1d4ed8);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--secondary-color, #1d4ed8) 25%, transparent);
}
.skin-preset.selected .skin-check { display: inline-flex; }

/* ── SHARED structural rules (all skins) ─────────────────────────────────────── */

/* Page behind everything. The :not()/.page-home-backdrop-none variants exist to
   out-rank the ID-strength flat body paints at ~25972 / ~26017; the <html>
   backer covers slivers the body doesn't reach. */
:root[data-skin] body,
:root[data-skin] body:not(:has(#homeScreen.screen.active)),
:root[data-skin] body.page-home-backdrop-none,
:root[data-skin] body.dark,
:root[data-skin] body.dark:not(:has(#homeScreen.screen.active)),
:root[data-skin] body.dark.page-home-backdrop-none {
  background-color: var(--skin-page-bg) !important;
  background-image: var(--skin-page-texture) !important;
}
html[data-skin],
html[data-skin]:not(:has(> body #homeScreen.screen.active)) {
  background: var(--skin-page-bg) !important;
}

/* Every page becomes a textured sheet. The ID-carrying selectors out-rank the
   per-screen opaque paints (Settings/Profile/Habits at ID strength; Memorize,
   Reading Plan, and the Learn/Translate/Test menus+screens at ~28181 / ~30049 /
   ~31432). Home stays transparent by design — the body's texture shows there. */
:root[data-skin] .screen.active,
:root[data-skin] body #settingsScreen.screen.active,
:root[data-skin] body #profilePage.screen.active,
:root[data-skin] body #habitsPage.screen.active,
:root[data-skin] body #communityPage.screen.active,
:root[data-skin] body #merciesPage.screen.active,
:root[data-skin] body #memorizationPage.screen.active,
:root[data-skin] body #readingPlanPage.screen.active,
:root[data-skin] body #threadsPage.screen.active,
:root[data-skin] body #learnMenu.screen.active,
:root[data-skin] body #learnScreen.screen.active,
:root[data-skin] body #translateMenu.screen.active,
:root[data-skin] body #translateScreen.screen.active,
:root[data-skin] body #testMenu.screen.active,
:root[data-skin] body #testScreen.screen.active,
:root[data-skin] .study-library {
  background-color: var(--skin-sheet-bg) !important;
  background-image: var(--skin-sheet-texture) !important;
}

/* Home tool tiles and lesson surfaces carry the texture themselves — they are
   opaque cards packed edge to edge that would otherwise swallow whole regions. */
:root[data-skin] .home-action-tile,
:root[data-skin] #homeScreen .main-btn.home-action:not(.rhema-featured-btn),
:root[data-skin] #newLearnMenu .learn-path-grid button,
:root[data-skin] #basicVerbsLearnMenu .learn-path-grid button,
:root[data-skin] .lesson-module,
:root[data-skin] .lesson-block,
:root[data-skin] .test-card,
:root[data-skin] .translate-card {
  background-color: var(--skin-card-bg) !important;
  background-image: var(--skin-card-texture) !important;
}

/* Type: body text plus form controls (they don't inherit) plus headings (which
   otherwise keep the serif display font). Icon spans set their own family. */
:root[data-skin] body,
:root[data-skin] button,
:root[data-skin] input,
:root[data-skin] select,
:root[data-skin] textarea,
:root[data-skin] h1,
:root[data-skin] h2,
:root[data-skin] h3 {
  font-family: var(--skin-font);
}

/* Icon set per skin (Rounded / Sharp / Outlined), falling back to Outlined. */
:root[data-skin] .material-symbols-outlined {
  font-family: var(--skin-icon-font, "Material Symbols Outlined");
}

/* Raised surfaces: per-skin border + hard offset shadow. */
:root[data-skin] .sett-card,
:root[data-skin] .main-btn,
:root[data-skin] .home-action,
:root[data-skin] .rhema-compare-item,
:root[data-skin] .modal-card {
  border: var(--skin-card-border);
  box-shadow: var(--skin-card-shadow);
}

/* Chrome bars that paint page-color read as stray bands on a textured sheet. */
:root[data-skin] #profilePage .nav-bar {
  background: transparent !important;
}
/* Dark mode paints body.dark .app opaque — let the texture through. */
:root[data-skin] body.dark .app {
  background-color: transparent !important;
}

