/* ══ THEOLOGICAL THREADS ═════════════════════════════════════════════════════════════
   Thematic verse chains. A vertical "thread" stitches verse cards together;
   knots mark read stops; a completed thread turns gold ("woven"). All colors
   ride the theme tokens so Threads works under every App Style. */

#threadsPage.screen.active {
  display: flex;
  flex-direction: column;
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  height: 100vh;
  height: 100dvh;
  z-index: 1000;
  overflow: hidden;
  background: var(--primary-light) !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
#threadsPage .gt-nav {
  flex-shrink: 0;
  padding: max(10px, env(safe-area-inset-top)) 18px 4px;
  margin: 0;
}
.gt-scroll {
  flex: 1 1 0; min-height: 0;
  overflow-y: auto; overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding: 4px 16px calc(env(safe-area-inset-bottom, 0px) + 40px);
}
.gt-lead { color: var(--muted-color); font-size: 0.95rem; line-height: 1.5; margin: 4px 2px 6px; }
.gt-summary { font-size: 0.9rem; margin: 0 2px 10px; color: var(--font-color); }
.gt-search {
  width: 100%; box-sizing: border-box;
  padding: 11px 14px; margin-bottom: 14px;
  border: 1.5px solid var(--border-color);
  border-radius: 12px;
  background: var(--card-color);
  color: var(--font-color);
  font-family: inherit; font-size: 0.95rem;
}
.gt-loading { text-align: center; color: var(--muted-color); padding: 32px 8px; }

/* Library: categories + thread cards */
.gt-cat { margin-bottom: 18px; }
.gt-cat-head { display: flex; align-items: center; gap: 10px; margin: 0 2px 8px; }
.gt-cat-icon { font-size: 1.35rem; }
.gt-cat-head strong { display: block; font-size: 1rem; }
.gt-cat-head small { color: var(--muted-color); font-size: 0.78rem; }
.gt-cat-list { display: flex; flex-direction: column; gap: 8px; }
.gt-card {
  display: flex; align-items: center; gap: 12px;
  width: 100%; box-sizing: border-box; text-align: left;
  padding: 12px 14px;
  border: 1.5px solid var(--border-color);
  border-radius: 14px;
  background: var(--card-color);
  color: var(--font-color);
  cursor: pointer;
  font-family: inherit;
  transition: border-color 0.15s, transform 0.1s;
}
.gt-card:active { transform: scale(0.985); border-color: var(--secondary-color); }
.gt-card-icon { font-size: 1.5rem; flex-shrink: 0; }
.gt-card-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.gt-card-main strong { font-size: 0.92rem; }
.gt-card-main small { color: var(--muted-color); font-size: 0.78rem; line-height: 1.35; }
.gt-card-count { flex-shrink: 0; font-size: 0.78rem; font-weight: 800; color: var(--muted-color); }

/* Stitch progress bar: dashes like thread through fabric */
.gt-stitchbar {
  display: block; height: 5px; border-radius: 3px; margin-top: 3px;
  background: color-mix(in srgb, var(--border-color) 45%, transparent);
  overflow: hidden;
}
.gt-stitchbar-fill {
  display: block; height: 100%;
  background: repeating-linear-gradient(90deg,
    var(--secondary-color) 0 7px, color-mix(in srgb, var(--secondary-color) 25%, transparent) 7px 11px);
  border-radius: 3px;
  transition: width 0.3s ease;
}
.gt-stitchbar-lg { height: 7px; margin-top: 10px; }

/* Woven (completed) — gold */
.gt-card.gt-done { border-color: #c9a227; background: color-mix(in srgb, #e7c65a 12%, var(--card-color)); }
.gt-card.gt-done .gt-card-count { color: #a8821c; }
.gt-card.gt-done .gt-stitchbar-fill,
.gt-detail-head.gt-done .gt-stitchbar-fill {
  background: repeating-linear-gradient(90deg, #d4a93a 0 7px, #f3df9b 7px 11px);
}
.gt-woven-badge {
  font-size: 0.68rem; font-weight: 800; letter-spacing: 0.05em;
  color: #a8821c; margin-left: 4px;
}

/* Detail view */
.gt-back-lib {
  display: inline-flex; align-items: center; gap: 4px;
  border: none; background: transparent; cursor: pointer;
  color: var(--secondary-color); font-weight: 700; font-family: inherit;
  font-size: 0.88rem; padding: 6px 2px 10px;
}
.gt-back-lib .material-symbols-outlined { font-size: 18px; }
.gt-detail-head {
  border: 1.5px solid var(--border-color);
  border-radius: 16px;
  background: var(--card-color);
  padding: 14px 16px;
  margin-bottom: 16px;
}
.gt-detail-head.gt-done { border-color: #c9a227; background: color-mix(in srgb, #e7c65a 14%, var(--card-color)); }
.gt-detail-title { display: flex; align-items: center; gap: 10px; }
.gt-detail-title strong { font-size: 1.05rem; display: block; }
.gt-detail-title small { color: var(--muted-color); font-size: 0.78rem; }
.gt-detail-intro { color: var(--font-color); font-size: 0.9rem; line-height: 1.55; margin: 10px 0 0; }

/* The chain: a vertical thread line stitching stops together */
.gt-chain { position: relative; padding-left: 34px; }
.gt-chain::before {
  content: '';
  position: absolute; left: 13px; top: 8px; bottom: 26px;
  width: 0;
  border-left: 2px dashed color-mix(in srgb, var(--secondary-color) 45%, transparent);
}
.gt-stop { position: relative; margin-bottom: 12px; }
.gt-knot {
  position: absolute; left: -34px; top: 12px;
  width: 28px; height: 28px;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--secondary-color) 55%, transparent);
  background: var(--card-solid-color);
  color: var(--muted-color);
  cursor: pointer;
  display: grid; place-items: center;
  z-index: 1;
  transition: background 0.15s, border-color 0.15s;
}
.gt-knot .material-symbols-outlined { font-size: 14px; }
.gt-stop.gt-read .gt-knot {
  background: #d4a93a;
  border-color: #a8821c;
  color: #fff;
}
.gt-stop-card {
  border: 1.5px solid var(--border-color);
  border-radius: 14px;
  background: var(--card-color);
  padding: 11px 13px;
  cursor: pointer;
  transition: border-color 0.15s;
}
.gt-stop-card:active { border-color: var(--secondary-color); }
.gt-stop.gt-read .gt-stop-card { border-color: color-mix(in srgb, #c9a227 55%, var(--border-color)); }
.gt-stop-ref {
  display: flex; align-items: center; justify-content: space-between;
  font-weight: 800; font-size: 0.88rem;
  color: var(--secondary-color);
}
.gt-stop-go { font-size: 18px; color: var(--muted-color); }
.gt-stop-text { font-size: 0.9rem; line-height: 1.5; margin: 6px 0 0; color: var(--font-color); }
.gt-stop-note {
  font-size: 0.8rem; line-height: 1.45; margin: 8px 0 0;
  color: var(--muted-color);
  border-top: 1px dashed color-mix(in srgb, var(--border-color) 70%, transparent);
  padding-top: 7px;
}
.gt-chain-end {
  text-align: center; color: var(--muted-color);
  font-size: 0.85rem; padding: 6px 8px 16px;
}
.gt-chain-end.gt-done {
  color: #a8821c; font-weight: 800;
  animation: gtShimmer 2.2s ease-in-out infinite;
}
@keyframes gtShimmer {
  0%, 100% { opacity: 0.75; }
  50% { opacity: 1; }
}

/* Category / thread icons are Material Symbols, inked with the theme */
.gt-cat-icon.material-symbols-outlined {
  font-size: 22px;
  color: var(--secondary-color);
}
.gt-card-icon.material-symbols-outlined {
  font-size: 24px;
  color: var(--secondary-color);
}
.gt-card.gt-done .gt-card-icon.material-symbols-outlined,
.gt-detail-head.gt-done .gt-card-icon.material-symbols-outlined { color: #a8821c; }

/* Theological Threads info modal body */
.gt-info-body { padding: 4px 2px 8px; }
.gt-info-body p { font-size: 0.9rem; line-height: 1.55; color: var(--font-color); margin: 0 0 10px; }
#gtInfoModal .rhema-note-card { max-height: 76vh; overflow-y: auto; }

/* ── Rhema book sheet: History (replaces the search bar) ─────────────────────── */
.rhema-picker-history-row {
  display: flex;
  align-items: center;
  gap: 10px;
  width: calc(100% - 32px);
  margin: 4px 16px 10px;
  padding: 11px 14px;
  border: 1.5px solid var(--border-color, #93c5fd);
  border-radius: 12px;
  background: color-mix(in srgb, var(--secondary-color, #243447) 6%, var(--card-color, #fff));
  color: var(--font-color, #20303f);
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
}
.rhema-picker-history-row .material-symbols-outlined { font-size: 20px; color: var(--secondary-color, #243447); }
.rhema-picker-history-row .rhema-history-chev { margin-left: auto; color: var(--muted-color, #8a8a8a); }
.rhema-picker-history-row.hidden { display: none; }
.rhema-history-empty {
  color: var(--muted-color, #8a8a8a);
  font-size: 0.9rem;
  line-height: 1.5;
  text-align: center;
  padding: 26px 18px;
}

/* ── "Continue to Bible Atlas" footer on maps opened from Rhema ──────────────── */
.rhema-maps-continue {
  padding: 6px 16px calc(env(safe-area-inset-bottom, 0px) + 22px);
  display: flex;
  justify-content: center;
}
.rhema-maps-continue-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  max-width: 460px;
  justify-content: center;
  padding: 13px 18px;
  border: none;
  border-radius: 14px;
  background: var(--secondary-color, #243447);
  color: var(--btn-text-color, #fff);
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 6px 18px color-mix(in srgb, var(--secondary-color, #243447) 25%, transparent);
}
.rhema-maps-continue-btn .material-symbols-outlined { font-size: 20px; }
.rhema-maps-continue-btn:active { transform: scale(0.98); }

/* ══════════════════════════════════════════════════════════════════════════
   SERMON NOTES tile — pink accent, matching its sibling tiles.
   Only overrides the shared --qa-* palette (kept at high specificity so it
   out-ranks tools-theme-match / home-theme-match / skinned modes). The base
   .home-action-tile rules read these variables, so the tile keeps the exact
   light-card anatomy (glossy icon plate, title, subtitle, chevron) of the
   other tools while reading pink.
   ══════════════════════════════════════════════════════════════════════════ */
#homeScreen .home-action-tile.quick-action-sermon,
body.tools-theme-match #homeScreen .home-action-tile.quick-action-sermon,
body.home-theme-match #homeScreen .home-action-tile.quick-action-sermon,
:root[data-skin] #homeScreen .home-action-tile.quick-action-sermon,
:root[data-skin] .home-action-tile.quick-action-sermon {
  --qa-card-bg: linear-gradient(180deg, rgba(255, 224, 238, 0.98), rgba(255, 238, 246, 0.9));
  --qa-card-border: rgba(219, 39, 119, 0.18);
  --qa-card-shadow: rgba(190, 24, 93, 0.14);
  --qa-image-shadow: rgba(190, 24, 93, 0.18);
  --qa-title: #db2777;
  --qa-subtitle: #be185d;
}
/* The Sermon Notes artwork ships as a purple badge (it has its own baked
   rounded-square background, unlike its transparent-illustration siblings), so
   it shows as a clean badge with normal blend and is hue-rotated purple → pink
   to match the tile. */
#homeScreen .home-action-tile.quick-action-sermon .qa-img {
  mix-blend-mode: normal !important;
  filter: hue-rotate(65deg) saturate(1.35) contrast(1.02)
          drop-shadow(0 10px 15px var(--qa-image-shadow)) !important;
}

#homeScreen .home-action-tile.quick-action-quiz,
body.tools-theme-match #homeScreen .home-action-tile.quick-action-quiz,
body.home-theme-match #homeScreen .home-action-tile.quick-action-quiz,
:root[data-skin] #homeScreen .home-action-tile.quick-action-quiz,
:root[data-skin] .home-action-tile.quick-action-quiz {
  --qa-card-bg:
    radial-gradient(circle at 24% 0%, rgba(255, 255, 255, 0.99), transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(233, 238, 246, 0.95));
  --qa-card-border: rgba(148, 163, 184, 0.5);
  --qa-card-shadow: rgba(71, 85, 105, 0.18);
  --qa-image-shadow: rgba(51, 65, 85, 0.24);
  --qa-title: #2f3b4d;
  --qa-subtitle: #5c6a7d;
  background: var(--qa-card-bg) !important;
  border-color: var(--qa-card-border) !important;
}

#homeScreen .home-action-tile.quick-action-quiz .hat-icon,
body.tools-theme-match #homeScreen .home-action-tile.quick-action-quiz .hat-icon,
body.home-theme-match #homeScreen .home-action-tile.quick-action-quiz .hat-icon,
:root[data-skin] #homeScreen .home-action-tile.quick-action-quiz .hat-icon,
:root[data-skin] .home-action-tile.quick-action-quiz .hat-icon {
  padding: clamp(6px, 1.8vw, 10px) !important;
  background:
    radial-gradient(120% 90% at 50% 8%, rgba(255,255,255,0.98), rgba(255,255,255,0.48) 56%, transparent 100%),
    linear-gradient(180deg, #ffffff, #e9eef5) !important;
  border: 1px solid rgba(148, 163, 184, 0.42) !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.98),
    inset 0 -18px 30px rgba(100,116,139,0.14),
    0 12px 20px rgba(71,85,105,0.14) !important;
}

#homeScreen .home-action-tile.quick-action-quiz .qa-img {
  mix-blend-mode: normal !important;
  width: min(94%, var(--qa-art-size)) !important;
  max-width: var(--qa-art-size) !important;
  height: min(94%, var(--qa-art-size)) !important;
  max-height: var(--qa-art-size) !important;
  object-fit: contain !important;
  filter: saturate(1.08) contrast(1.04) drop-shadow(0 10px 15px var(--qa-image-shadow)) !important;
}

