      transform 0.16s ease,
      border-color 0.16s ease,
      background 0.16s ease;
  }

  #rhemaModal.open .rhema-occ-row:hover {
    transform: translateX(2px);
    border-color: color-mix(in srgb, var(--secondary-color) 28%, var(--border-color));
    background: color-mix(in srgb, var(--secondary-color) 7%, var(--card-color));
  }

  .rhema-xref-page {
    left: var(--desktop-rhema-rail) !important;
    right: var(--desktop-rhema-gutter);
    top: var(--desktop-rhema-gutter);
    bottom: var(--desktop-rhema-gutter);
    width: auto;
    border: 1px solid color-mix(in srgb, var(--border-color) 62%, rgba(255,255,255,0.54));
    border-radius: 28px;
    box-shadow: 0 26px 70px rgba(15,23,42,0.18);
